window.BANCO['CIEN']["7º Ano"] = [
  {"id": 1, "uid": "CIEN-7-001", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Máquinas Térmicas: Conceito", "dificuldade": "Fácil", "enunciado": "As máquinas térmicas são dispositivos mecânicos capazes de transformar calor em trabalho útil. O princípio básico de funcionamento dessas máquinas consiste em:", "alternativas": {"A": "Converter energia térmica proveniente de uma fonte quente em energia mecânica (movimento).", "B": "Criar energia elétrica a partir do frio sem queimar combustíveis.", "C": "Destruir átomos de carbono para gerar luz invisível.", "D": "Transformar energia solar diretamente em alimentos nas fábricas.", "E": "Gelar motores através de reações nucleares caseiras."}, "resposta_correta": "A", "justificativa": "Por definição termodinâmica, máquinas térmicas operam em ciclos absorvendo calor de uma fonte de alta temperatura e convertendo parte dessa energia térmica em trabalho mecânico útil.", "possui_imagem": true},
  {"id": 2, "uid": "CIEN-7-002", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Fontes de Energia Renováveis", "dificuldade": "Fácil", "enunciado": "Fontes de energia renováveis são aquelas que se regeneram na natureza em um curto espaço de tempo e não se esgotam com o uso humano. Qual das alternativas apresenta apenas fontes renováveis de energia?", "alternativas": {"A": "Carvão mineral, petróleo e gás natural.", "B": "Energia solar, energia eólica e biomassa.", "C": "Urânio nuclear, diesel e gasolina.", "D": "Petróleo, xisto betuminoso e carvão vegetal.", "E": "Gás liquefeito de petróleo e carvão mineral."}, "resposta_correta": "B", "justificativa": "Energia solar (Sol), eólica (ventos) e biomassa (matéria orgânica cultivável) são fontes renováveis. Carvão mineral, petróleo e gás natural são combustíveis fósseis não renováveis.", "possui_imagem": true},
  {"id": 3, "uid": "CIEN-7-003", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Combustíveis Fósseis", "dificuldade": "Fácil", "enunciado": "O petróleo, o carvão mineral e o gás natural são chamados de combustíveis fósseis porque foram formados:", "alternativas": {"A": "Pela queima rápida de florestas provocada por raios cósmicos.", "B": "Ao longo de milhões de anos a partir da decomposição de restos de seres vivos soterrados sob altas pressões e temperaturas.", "C": "Em laboratórios industriais durante a Revolução Industrial.", "D": "Pela solidificação de lava vulcânica na superfície dos oceanos.", "E": "Pela absorção de oxigênio pelas rochas sedimentares no último século."}, "resposta_correta": "B", "justificativa": "Combustíveis fósseis originaram-se do soterramento e fossilização de matéria orgânica vegetal e animal ao longo de eras geológicas sob condições anaeróbias e elevada pressão litosférica.", "possui_imagem": true},
  {"id": 4, "uid": "CIEN-7-004", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "A Máquina a Vapor e a Revolução Industrial", "dificuldade": "Fácil", "enunciado": "O aperfeiçoamento da máquina a vapor no século XVIII por James Watt foi um marco histórico decisivo para a Revolução Industrial. O principal combustível utilizado para ferver a água nas caldeiras daquelas máquinas era o:", "alternativas": {"A": "Petróleo refinado em gasolina.", "B": "Carvão mineral (hulha).", "C": "Etanol de cana-de-açúcar.", "D": "Gás natural comprimido.", "E": "Urânio enriquecido."}, "resposta_correta": "B", "justificativa": "O carvão mineral foi a grande fonte primária de energia da Primeira Revolução Industrial, abastecendo as caldeiras de máquinas a vapor fabris, trens (locomotivas) e navios.", "possui_imagem": true},
  {"id": 5, "uid": "CIEN-7-005", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Biocombustíveis no Brasil", "dificuldade": "Fácil", "enunciado": "No Brasil, um dos biocombustíveis mais utilizados em veículos automotores é o etanol. Esse combustível renovável é produzido em larga escala principalmente a partir da fermentação de qual vegetal?", "alternativas": {"A": "Soja transgênica.", "B": "Cana-de-açúcar.", "C": "Trigo sarraceno.", "D": "Eucalipto reflorestado.", "E": "Café arábica."}, "resposta_correta": "B", "justificativa": "No território brasileiro, o etanol (álcool etílico) combustível é obtido industrialmente pela fermentação dos açúcares do caldo da cana-de-açúcar por leveduras.", "possui_imagem": true},
  {"id": 6, "uid": "CIEN-7-006", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Impacto Ambiental: Efeito Estufa", "dificuldade": "Fácil", "enunciado": "A queima maciça de combustíveis fósseis nos motores de carros e termoelétricas libera grandes volumes de um gás que intensifica o efeito estufa e o aquecimento global. Esse gás é o:", "alternativas": {"A": "Gás oxigênio (O2).", "B": "Dióxido de carbono (gás carbônico - CO2).", "C": "Gás hélio (He).", "D": "Gás ozônio troposférico puro.", "E": "Vapor de mercúrio."}, "resposta_correta": "B", "justificativa": "O dióxido de carbono (CO2) é o principal gás de efeito estufa de origem antropogênica decorrente da combustão de combustíveis fósseis carbonados.", "possui_imagem": true},
  {"id": 7, "uid": "CIEN-7-007", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Tecnologia e Automação", "dificuldade": "Fácil", "enunciado": "Nas indústrias modernas, o uso de robôs e sistemas computadorizados para realizar tarefas repetitivas, perigosas ou que exigem alta precisão é conhecido como:", "alternativas": {"A": "Manufatura artesanal manual.", "B": "Automação industrial.", "C": "Combustão externa.", "D": "Ciclo biológico da matéria.", "E": "Tectonismo fabril."}, "resposta_correta": "B", "justificativa": "A automação industrial consiste na aplicação de tecnologia mecânica, eletrônica e de software para operar processos produtivos com mínima intervenção humana direta.", "possui_imagem": true},
  {"id": 8, "uid": "CIEN-7-008", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Combustão Interna vs. Externa", "dificuldade": "Fácil", "enunciado": "Enquanto na máquina a vapor tradicional o combustível queima do lado de fora do cilindro (combustão externa na caldeira), nos motores da maioria dos automóveis modernos a queima do combustível ocorre:", "alternativas": {"A": "No escapamento traseiro do carro.", "B": "Dentro da própria câmara do cilindro do motor (combustão interna).", "C": "Dentro do tanque de gasolina.", "D": "No radiador de água de resfriamento.", "E": "Nas rodas durante o atrito com o asfalto."}, "resposta_correta": "B", "justificativa": "Nos motores de combustão interna (motores a pistão de quatro tempos), a mistura ar-combustível queima diretamente dentro dos cilindros motores, empurrando os pistões.", "possui_imagem": true},
  {"id": 9, "uid": "CIEN-7-009", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Propagação de Calor: Convecção", "dificuldade": "Fácil", "enunciado": "Nas caldeiras das máquinas térmicas, a água no fundo se aquece, fica menos densa e sobe, enquanto a água fria mais densa desce, formando correntes circulares de aquecimento. Esse processo de propagação de calor é a:", "alternativas": {"A": "Condução.", "B": "Convecção térmica.", "C": "Irradiação luminosa.", "D": "Sublimação mecânica.", "E": "Fusão atômica."}, "resposta_correta": "B", "justificativa": "A convecção é a transferência de calor em fluidos (líquidos e gases) mediante o movimento macroscópico de matéria gerado por diferenças de densidade decorrentes da temperatura.", "possui_imagem": true},
  {"id": 10, "uid": "CIEN-7-010", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Calor e Temperatura: Diferenciação", "dificuldade": "Fácil", "enunciado": "Em ciências físicas, os conceitos de calor e temperatura não são sinônimos. A definição correta de calor é:", "alternativas": {"A": "A quantidade de frio armazenada em um corpo.", "B": "Energia térmica em trânsito de um corpo de maior temperatura para outro de menor temperatura.", "C": "A medida exclusiva da massa de um objeto metálico.", "D": "A velocidade constante com que o ar se move na atmosfera.", "E": "A eletricidade acumulada em uma pilha de brinquedo."}, "resposta_correta": "B", "justificativa": "Calor é definido estritamente como a energia térmica transferida espontaneamente entre corpos motivada exclusivamente por uma diferença de temperatura entre eles.", "possui_imagem": true},
  {"id": 11, "uid": "CIEN-7-011", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Locomotiva a Vapor: Maria-Fumaça", "dificuldade": "Fácil", "enunciado": "As antigas locomotivas a vapor, conhecidas popularmente no Brasil como 'marias-fumaça', foram fundamentais para o transporte e escoamento do café no século XIX e início do século XX. O vapor de água gerado na caldeira movia o trem porque:", "alternativas": {"A": "A água líquida congelava instantaneamente as rodas do trem.", "B": "O vapor de água sob alta pressão expandia-se dentro de cilindros, empurrando pistões ligados às rodas da locomotiva.", "C": "O vapor de água puxava o trem por atração magnética com os trilhos.", "D": "O carvão queimado voava como asas ao redor da cabine do maquinista.", "E": "A fumaça preta criava um vácuo que sugava o trem para a frente."}, "resposta_correta": "B", "justificativa": "A expansão volumétrica violenta do vapor de água a altas pressões converte energia térmica em força mecânica que empurra pistões, transmitida às bielas e rodas motrizes.", "possui_imagem": true},
  {"id": 12, "uid": "CIEN-7-012", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Biodiesel", "dificuldade": "Fácil", "enunciado": "Além do etanol, outro biocombustível de grande destaque no Brasil é o biodiesel. Ele é fabricado a partir de:", "alternativas": {"A": "Plásticos reciclados e pneus velhos derretidos.", "B": "Óleos vegetais (como óleo de soja, dendê e girassol) ou gorduras animais.", "C": "Água mineral purificada em hidrelétricas.", "D": "Gás oxigênio retirado da atmosfera das cidades.", "E": "Minério de ferro extraído de jazidas rochosas."}, "resposta_correta": "B", "justificativa": "O biodiesel é obtido pela reação química de transesterificação entre triglicerídeos de óleos vegetais (soja, mamona, palma) ou gorduras animais com um álcool (metanol ou etanol).", "possui_imagem": true},
  {"id": 13, "uid": "CIEN-7-013", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Equilíbrio Térmico", "dificuldade": "Fácil", "enunciado": "Ao colocar uma colher de metal quente dentro de um copo com água gelada e aguardar alguns minutos, observa-se que a colher esfria e a água esquenta até que ambas atinjam a mesma temperatura. Esse estado final é chamado de:", "alternativas": {"A": "Fusão nuclear.", "B": "Equilíbrio térmico.", "C": "Combustão completa.", "D": "Condensação espontânea.", "E": "Evaporação crítica."}, "resposta_correta": "B", "justificativa": "O equilíbrio térmico é alcançado quando dois ou mais corpos em contato térmico cessam a troca líquida de calor por terem igualado suas temperaturas.", "possui_imagem": true},
  {"id": 14, "uid": "CIEN-7-014", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Inteligência Artificial e Tecnologias Atuais", "dificuldade": "Fácil", "enunciado": "No contexto da Quarta Revolução Industrial (Indústria 4.0), sistemas de computador capazes de reconhecer padrões, tomar decisões e aprender a partir de grandes volumes de dados são exemplos de:", "alternativas": {"A": "Máquinas a vapor manuais.", "B": "Inteligência Artificial (IA).", "C": "Locomotivas mecânicas de carvão.", "D": "Termômetros de mercúrio antigos.", "E": "Moinhos de vento medievais."}, "resposta_correta": "B", "justificativa": "Sistemas de Inteligência Artificial e aprendizado de máquina (Machine Learning) constituem o cerne tecnológico da automação avançada da Indústria 4.0 contemporânea.", "possui_imagem": true},
  {"id": 15, "uid": "CIEN-7-015", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Poluição do Ar nas Cidades", "dificuldade": "Fácil", "enunciado": "O uso massivo de veículos movidos a combustíveis fósseis em grandes centros urbanos provoca problemas respiratórios na população devido à emissão de poluentes atmosféricos como:", "alternativas": {"A": "Oxigênio medicinal e vapor de água destilada.", "B": "Monóxido de carbono, óxidos de nitrogênio e material particulado (fuligem).", "C": "Gás hélio e gás argônio inertes.", "D": "Glicose pura e amido dissolvido.", "E": "Cloreto de sódio em pó branco."}, "resposta_correta": "B", "justificativa": "A queima incompleta e sob alta temperatura de combustíveis derivados de petróleo emite CO (gás asfixiante), NOx (precursor de ozônio e chuva ácida) e partículas microscópicas de fuligem.", "possui_imagem": false},
  {"id": 16, "uid": "CIEN-7-016", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Segunda Lei da Termodinâmica: Calor Perdido", "dificuldade": "Fácil", "enunciado": "Em qualquer máquina térmica real, é impossível transformar 100% do calor fornecido pelo combustível em trabalho mecânico útil. Parte dessa energia é obrigatoriamente:", "alternativas": {"A": "Destruída e apagada do universo.", "B": "Dissipada (perdida) para o ambiente na forma de calor para uma fonte fria.", "C": "Convertida em novos átomos de ouro dentro do motor.", "D": "Transformada em água potável para o motorista.", "E": "Armazenada permanentemente sem aquecer nada."}, "resposta_correta": "B", "justificativa": "A Segunda Lei da Termodinâmica (enunciado de Kelvin-Planck) determina que nenhuma máquina térmica operando em ciclo pode converter integralmente calor em trabalho; parte do calor deve ser rejeitada à fonte fria.", "possui_imagem": false},
  {"id": 17, "uid": "CIEN-7-017", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Energia Solar Fotovoltaica", "dificuldade": "Fácil", "enunciado": "Painéis solares instalados nos telhados de residências e escolas que geram energia elétrica silenciosamente ao receber a luz do sol utilizam a tecnologia:", "alternativas": {"A": "De queima de biomassa líquida.", "B": "Solar fotovoltaica.", "C": "De turbinas a vapor de carvão.", "D": "Geotérmica subterrânea profunda.", "E": "Nuclear de fissão de urânio."}, "resposta_correta": "B", "justificativa": "Células fotovoltaicas de silício convertem a radiação eletromagnética da luz solar diretamente em corrente elétrica contínua por meio do efeito fotoelétrico.", "possui_imagem": false},
  {"id": 18, "uid": "CIEN-7-018", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Gás Natural Veicular (GNV)", "dificuldade": "Fácil", "enunciado": "O Gás Natural Veicular (GNV) é composto principalmente pelo hidrocarboneto metano (CH4). Embora queime de forma mais limpa que o óleo diesel, o GNV é classificado como fonte:", "alternativas": {"A": "Renovável de ciclo rápido de semanas.", "B": "Não renovável, pois é um combustível fóssil formado há milhões de anos.", "C": "Exclusivamente solar direta.", "D": "Biológica cultivada na agricultura.", "E": "Inesgotável que nunca terminará na Terra."}, "resposta_correta": "B", "justificativa": "O gás natural fóssil compartilha a mesma gênese geológica que o petróleo bruto; suas jazidas no subsolo são finitas e não renováveis na escala de tempo da civilização humana.", "possui_imagem": false},
  {"id": 19, "uid": "CIEN-7-019", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Propagação de Calor: Condução Térmica", "dificuldade": "Fácil", "enunciado": "Ao mexer uma sopa quente em uma panela com uma colher totalmente de metal, o cabo da colher esquenta rapidamente e pode queimar a mão do cozinheiro. A transferência de calor que ocorreu ao longo do corpo de metal da colher é a:", "alternativas": {"A": "Condução térmica.", "B": "Convecção líquida.", "C": "Irradiação espacial.", "D": "Evaporação forçada.", "E": "Refração atômica."}, "resposta_correta": "A", "justificativa": "A condução é a transferência de energia térmica partícula a partícula através do choque molecular sem deslocamento macroscópico de matéria, típica de sólidos (especialmente metais).", "possui_imagem": false},
  {"id": 20, "uid": "CIEN-7-020", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Revolução dos Meios de Transporte", "dificuldade": "Fácil", "enunciado": "Antes da invenção da máquina a vapor, as viagens terrestres e marítimas dependiam exclusivamente de tração animal (cavalos, bois) e da força dos ventos (navios a vela). A máquina a vapor revolucionou o transporte ao permitir:", "alternativas": {"A": "Viagens muito mais rápidas, pontuais e com capacidade de transportar cargas muito maiores em qualquer época do ano.", "B": "Que os barcos voassem acima das nuvens como aviões.", "C": "O fim completo do comércio internacional entre países.", "D": "Que os cavalos deixassem de existir na natureza.", "E": "A redução da população urbana mundial a zero."}, "resposta_correta": "A", "justificativa": "A energia a vapor conferiu autonomia motriz inédita à humanidade, rompendo a dependência exclusiva de ventos oceânicos ou animais de carga e impulsionando a expansão da economia global.", "possui_imagem": false},
  {"id": 21, "uid": "CIEN-7-021", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Robótica e Linhas de Montagem", "dificuldade": "Fácil", "enunciado": "Nas modernas fábricas de automóveis, braços robóticos realizam soldas precisas, pintura e montagem de peças pesadas. Uma grande vantagem da robótica nesses ambientes fabris é:", "alternativas": {"A": "Aumentar a produtividade, a padronização das peças e evitar acidentes de trabalho com operadores humanos.", "B": "Fazer com que os carros sejam fabricados sem gastar nenhuma energia.", "C": "Permitir que as fábricas funcionem apenas durante o inverno.", "D": "Eliminar totalmente o uso de eletricidade e computadores.", "E": "Tornar os motores de automóveis feitos inteiramente de madeira."}, "resposta_correta": "A", "justificativa": "A automação robótica assegura elevada repetibilidade geométrica, velocidade de ciclo, redução de refugo e segurança ocupacional ao retirar trabalhadores humanos de atividades insalubres e perigosas.", "possui_imagem": false},
  {"id": 22, "uid": "CIEN-7-022", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Rendimento das Máquinas Térmicas", "dificuldade": "Médio", "enunciado": "Uma máquina térmica industrial consome 1.000 joules de calor de sua caldeira (fonte quente) a cada ciclo e realiza 250 joules de trabalho mecânico útil para mover uma esteira. O rendimento térmico dessa máquina é de:", "alternativas": {"A": "10%.", "B": "25%.", "C": "50%.", "D": "75%.", "E": "100%."}, "resposta_correta": "B", "justificativa": "O rendimento (η) de uma máquina térmica é a razão entre o trabalho mecânico útil produzido e a energia térmica total absorvida da fonte quente: η = W / Qq = 250 J / 1.000 J = 0,25 (25%).", "possui_imagem": false},
  {"id": 23, "uid": "CIEN-7-023", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Ciclo das Quatro Etapas do Motor a Combustão", "dificuldade": "Médio", "enunciado": "O motor de combustão interna de quatro tempos presente na maioria dos automóveis modernos executa um ciclo contínuo repetitivo. A sequência correta dos quatro tempos desse motor é:", "alternativas": {"A": "Combustão -> Exaustão -> Admissão -> Compressão.", "B": "Admissão (mistura ar/combustível) -> Compressão -> Combustão/Expansão (tempo motor útil) -> Escape/Exaustão (liberação dos gases).", "C": "Compressão -> Admissão -> Escape -> Resfriamento.", "D": "Escape -> Ignição -> Admissão -> Desaceleração.", "E": "Expansão -> Admissão -> Compressão -> Desligamento."}, "resposta_correta": "B", "justificativa": "O ciclo de quatro tempos (Ciclo Otto) compreende sucessivamente: 1) Admissão do ar e combustível; 2) Compressão da mistura pelo pistão; 3) Combustão (ignição por faísca) e expansão dos gases gerando trabalho; 4) Escape dos gases residuais.", "possui_imagem": false},
  {"id": 24, "uid": "CIEN-7-024", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Transição Energética e Descarbonização", "dificuldade": "Médio", "enunciado": "Diante da crise climática global, diversos países têm implementado políticas de 'transição energética'. Esse processo busca substituir a matriz energética fóssil por matrizes de baixo carbono. A razão ambiental fundamental dessa transição é:", "alternativas": {"A": "Acabar com a energia elétrica em todas as cidades do mundo.", "B": "Reduzir drasticamente as emissões líquidas de gases causadores do efeito estufa para limitar o aumento da temperatura média do planeta a níveis seguros.", "C": "Aumentar o preço dos alimentos para desestimular o consumo de carnes.", "D": "Forçar todas as indústrias a voltarem a usar força muscular animal.", "E": "Congelar o calor dos oceanos com gelo artificial."}, "resposta_correta": "B", "justificativa": "A descarbonização da matriz energética global visa mitigar as mudanças climáticas antropogênicas, reduzindo as emissões de dióxido de carbono e metano originadas da queima de carvão, derivados de petróleo e gás.", "possui_imagem": false},
  {"id": 25, "uid": "CIEN-7-025", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Balanço de Carbono: Fóssil vs. Biocombustível", "dificuldade": "Médio", "enunciado": "Cientistas afirmam que o etanol de cana-de-açúcar é muito menos prejudicial ao clima do que a gasolina fóssil, mesmo liberando gás carbônico ao queimar no motor do carro. Essa vantagem do etanol é explicada pelo fato de que:", "alternativas": {"A": "O etanol não produz gás carbônico quando queima.", "B": "O gás carbônico liberado na queima do etanol foi previamente capturado da atmosfera pelas próprias plantas de cana-de-açúcar durante a fotossíntese (ciclo fechado de carbono recente).", "C": "A gasolina destrói a camada de ozônio em segundos e o etanol a restaura.", "D": "O motor que usa etanol gasta metade do oxigênio do motor a gasolina.", "E": "A cana-de-açúcar só cresce no escuro sem precisar de carbono."}, "resposta_correta": "B", "justificativa": "Os biocombustíveis participam do ciclo biogeoquímico curto do carbono: o CO2 emitido no escapamento foi absorvido recentemente pelas plantas na fotossíntese. Já os combustíveis fósseis injetam na atmosfera carbono que estava estocado no subsolo há centenas de milhões de anos.", "possui_imagem": false},
  {"id": 26, "uid": "CIEN-7-026", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Propagação de Calor: Irradiação Térmica", "dificuldade": "Médio", "enunciado": "A energia solar que aquece a Terra viaja cerca de 150 milhões de quilômetros através do vácuo absoluto do espaço sideral antes de atingir o topo da atmosfera terrestre. O único processo físico de transferência de calor capaz de se propagar no vácuo é a:", "alternativas": {"A": "Condução através de barras de ferro invisíveis.", "B": "Irradiação térmica por ondas eletromagnéticas (principalmente radiação infravermelha).", "C": "Convecção de ventos espaciais de ar rarefeito.", "D": "Evaporação cósmica de hidrogênio estelar.", "E": "Fricção mecânica entre planetas vizinhos."}, "resposta_correta": "B", "justificativa": "Ao contrário da condução e da convecção, que exigem suporte material para propagação, a irradiação térmica ocorre por meio de ondas eletromagnéticas e propaga-se no vácuo à velocidade da luz.", "possui_imagem": false},
  {"id": 27, "uid": "CIEN-7-027", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "A Garrafa Térmica e o Bloqueio de Calor", "dificuldade": "Médio", "enunciado": "Uma garrafa térmica convencional mantém líquidos quentes ou frios por muitas horas porque foi projetada para dificultar as três formas de propagação de calor. Assinale a alternativa que associa corretamente o recurso da garrafa ao tipo de perda de calor que ele combate:", "alternativas": {"A": "Paredes espelhadas combatem a condução; tampa de plástico combate a irradiação.", "B": "Vácuo entre as paredes duplas bloqueia a condução e a convecção; superfícies espelhadas refletem e diminuem a perda por irradiação.", "C": "Tampa aberta combate a convecção; vidro transparente combate o calor solar.", "D": "O plástico externo absorve 100% da irradiação para alimentar o líquido.", "E": "O vácuo impede apenas que a luz visível entre na garrafa."}, "resposta_correta": "B", "justificativa": "O vácuo entre as paredes de vidro elimina o meio material, impedindo condução e convecção; as faces espelhadas refletem a radiação infravermelha, contendo as trocas por irradiação; e a tampa veda as perdas por convecção com o ar externo.", "possui_imagem": false},
  {"id": 28, "uid": "CIEN-7-028", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Impacto Social da Revolução Industrial", "dificuldade": "Médio", "enunciado": "A introdução das máquinas térmicas nas fábricas têxteis da Inglaterra causou profundas transformações socioeconômicas a partir do final do século XVIII. Entre essas transformações, destacou-se:", "alternativas": {"A": "A saída em massa da população do campo para as cidades industriais (êxodo urbano) e o surgimento do trabalho assalariado nas fábricas.", "B": "O retorno de todas as pessoas para a vida agrícola de subsistência.", "C": "O fim do comércio marítimo internacional devido à poluição dos rios.", "D": "A diminuição drástica da população humana no continente europeu.", "E": "O abandono total do carvão e do ferro na fabricação de ferramentas."}, "resposta_correta": "A", "justificativa": "A mecanização fabril concentrou os meios de produção nas cidades, desencadeando intensa migração campo-cidade (urbanização acelerada), formação da classe operária proletária e jornadas de trabalho reguladas pelo relógio fabril.", "possui_imagem": false},
  {"id": 29, "uid": "CIEN-7-029", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Inversão Térmica e Poluição Urbana", "dificuldade": "Médio", "enunciado": "Em grandes cidades cercadas por montanhas, como São Paulo, é comum no inverno ocorrer o fenômeno meteorológico da 'inversão térmica'. Em dias de inversão térmica:", "alternativas": {"A": "O ar quente sobe com velocidade máxima e limpa a atmosfera da cidade.", "B": "Uma camada de ar quente se sobrepõe a uma camada de ar frio rente ao solo, bloqueando a convecção natural e aprisionando os poluentes emitidos pelos veículos perto da superfície.", "C": "A temperatura do solo sobe para 60 ºC provocando queimadas espontâneas.", "D": "A chuva ácida congela e forma pedras de granizo de petróleo.", "E": "O vento sopra forte em todas as direções dissipando toda a fumaça."}, "resposta_correta": "B", "justificativa": "Em madrugadas frias de inverno, o solo perde calor rapidamente e resfria a camada inferior de ar. O ar frio mais denso fica retido sob uma camada superior de ar mais quente, impedindo as correntes de convecção ascendentes e retendo poluentes.", "possui_imagem": false},
  {"id": 30, "uid": "CIEN-7-030", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Ciclo Termodinâmico e Conservação de Energia", "dificuldade": "Médio", "enunciado": "Em uma usina termoelétrica movida a carvão mineral, a energia contida no carvão passa por sucessivas transformações até chegar às nossas casas como eletricidade. A cadeia correta dessas transformações de energia é:", "alternativas": {"A": "Energia química (no combustível) -> Energia térmica (no vapor aquecido) -> Energia mecânica (na turbina girando) -> Energia elétrica (no gerador).", "B": "Energia elétrica -> Energia nuclear -> Energia solar -> Energia cinética.", "C": "Energia térmica -> Energia fóssil -> Energia magnética -> Energia sonora pura.", "D": "Energia mecânica -> Energia química -> Energia de biomassa -> Eletricidade.", "E": "Energia potencial gravitacional -> Energia térmica -> Petróleo bruto."}, "resposta_correta": "A", "justificativa": "A queima do carvão converte energia química em energia térmica do vapor sob pressão. O vapor em alta velocidade faz girar pás de uma turbina (energia mecânica), que aciona um gerador eletromagnético produzindo eletricidade.", "possui_imagem": false},
  {"id": 31, "uid": "CIEN-7-031", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Carros Elétricos vs. Carros a Combustão", "dificuldade": "Médio", "enunciado": "Veículos elétricos têm sido amplamente apontados como alternativas para reduzir a poluição local nas cidades em relação aos veículos a combustão interna. Uma das principais vantagens mecânicas e energéticas dos motores elétricos é:", "alternativas": {"A": "Não emitirem poluentes atmosféricos nem gases de efeito estufa pelo escapamento e possuírem eficiência energética muito superior (acima de 80% contra cerca de 25% a 30% dos motores a combustão).", "B": "Funcionarem sem necessidade de baterias ou recarga elétrica.", "C": "Serem movidos exclusivamente a vapor de água fervida no capô.", "D": "Queimarem óleo diesel de forma 100% silenciosa sem fumaça.", "E": "Não precisarem de freios para parar o veículo."}, "resposta_correta": "A", "justificativa": "Motores elétricos operam com emissão zero no tubo de escape local e convertem mais de 80% da energia elétrica da bateria em movimento mecânico nas rodas, superando com folga o rendimento térmico de motores a combustão interna.", "possui_imagem": false},
  {"id": 32, "uid": "CIEN-7-032", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Efeito da Poluição por Enxofre: Chuva Ácida", "dificuldade": "Médio", "enunciado": "Combustíveis fósseis como o carvão mineral de baixa qualidade e o óleo diesel comum contêm impurezas de enxofre (S). Quando esses combustíveis são queimados, o enxofre reage com o oxigênio do ar e, na atmosfera, combina-se com o vapor de água formando:", "alternativas": {"A": "Ácido sulfúrico (H2SO4), um dos principais responsáveis pelo fenômeno da chuva ácida.", "B": "Água com açúcar que fertiliza as lavouras automaticamente.", "C": "Sal de cozinha puro que precipita como neve branca.", "D": "Oxigênio medicinal que melhora a respiração das árvores.", "E": "Gás hélio que faz a chuva flutuar no céu."}, "resposta_correta": "A", "justificativa": "A oxidação do enxofre gera dióxido de enxofre (SO2) e trióxido de enxofre (SO3), que reagem com a umidade da atmosfera gerando ácido sulfúrico (H2SO4), acidificando corpos hídricos, solos e desgastando monumentos e florestas.", "possui_imagem": false},
  {"id": 33, "uid": "CIEN-7-033", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "A Máquina de Newcomen e o Aperfeiçoamento de Watt", "dificuldade": "Médio", "enunciado": "A primeira máquina a vapor prática utilizada em larga escala foi projetada por Thomas Newcomen no início do século XVIII para bombear água de minas de carvão inundadas. Seu rendimento era extremamente baixo porque o cilindro era aquecido e resfriado a cada ciclo. James Watt revolucionou a tecnologia ao introduzir:", "alternativas": {"A": "Um condensador separado, que mantinha o cilindro principal permanentemente aquecido, economizando enormes quantidades de combustível.", "B": "Velas de cera no lugar do carvão mineral.", "C": "Motores de combustão interna movidos a gasolina.", "D": "Painéis solares fotovoltaicos acoplados aos pistões.", "E": "Engrenagens de plástico leves e flexíveis."}, "resposta_correta": "A", "justificativa": "A inovação patenteada por Watt foi o condensador externo separado. Ao evitar o resfriamento e reaquecimento alternados do cilindro de trabalho a cada golpe do pistão, o consumo de carvão da máquina reduziu-se em cerca de 75%.", "possui_imagem": false},
  {"id": 34, "uid": "CIEN-7-034", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Internet das Coisas (IoT) na Indústria", "dificuldade": "Médio", "enunciado": "Na Indústria 4.0, o conceito de 'Internet das Coisas' (IoT) refere-se a:", "alternativas": {"A": "Comprar roupas e livros através de sites de comércio eletrônico.", "B": "A conexão em rede de máquinas, sensores e equipamentos industriais que coletam e trocam dados em tempo real para otimizar a produção e prever falhas antes que ocorram.", "C": "A criação de computadores gigantescos que funcionam a lenha.", "D": "O cancelamento do uso de robôs nas montadoras de veículos.", "E": "O uso de telefones fixos com fio para ligar aos fornecedores."}, "resposta_correta": "B", "justificativa": "A Internet das Coisas (IoT) industrial integra sensores inteligentes, conectividade em nuvem e análise de dados (Big Data), viabilizando monitoramento remoto, manutenção preditiva e otimização autônoma de linhas produtivas.", "possui_imagem": false},
  {"id": 35, "uid": "CIEN-7-035", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Vapor Saturado e Pressão da Água", "dificuldade": "Médio", "enunciado": "Nas panelas de pressão domésticas e nas caldeiras das máquinas térmicas, a água ferve a temperaturas bem superiores a 100 ºC (frequentemente atingindo 120 ºC a 150 ºC ou mais). Isso acontece porque:", "alternativas": {"A": "A panela foi fabricada com metais que destroem as moléculas de água.", "B": "O confinamento do vapor aumenta a pressão interna sobre a superfície do líquido, elevando o ponto de ebulição da água.", "C": "A água pura não consegue ferver em ambientes fechados.", "D": "A tampa hermética bloqueia a entrada de calor da chama.", "E": "A gravidade diminui dentro da panela de pressão."}, "resposta_correta": "B", "justificativa": "O ponto de ebulição de um líquido depende diretamente da pressão externa exercida sobre ele. Ao aprisionar o vapor, a pressão interna sobe acima de 1 atm, exigindo maior energia cinética (maior temperatura) para que as moléculas de água entrem em ebulição.", "possui_imagem": false},
  {"id": 36, "uid": "CIEN-7-036", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Aparelhos de Refrigeração: Máquinas Térmicas Inversas", "dificuldade": "Médio", "enunciado": "Geladeiras e condicionadores de ar são exemplos de 'máquinas térmicas que operam em ciclo inverso' (refrigeradores). A função desses aparelhos é:", "alternativas": {"A": "Fazer o calor fluir espontaneamente do corpo frio para o quente sem gastar energia.", "B": "Retirar calor de uma fonte fria (interior da geladeira) e rejeitá-lo para uma fonte quente (ambiente externo), o que exige consumo de trabalho externo (energia elétrica no compressor).", "C": "Destruir a energia térmica dos alimentos dentro do congelador.", "D": "Criar gelo utilizando reações químicas de combustão de gás metano.", "E": "Produzir oxigênio líquido para resfriar as prateleiras."}, "resposta_correta": "B", "justificativa": "Pela 2ª Lei da Termodinâmica (enunciado de Clausius), o calor não pode fluir espontaneamente de um corpo frio para um corpo quente. Um ciclo refrigerador transfere calor contra o gradiente térmico às custas de trabalho mecânico do compressor.", "possui_imagem": false},
  {"id": 37, "uid": "CIEN-7-037", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Biogás e Biodigestores", "dificuldade": "Médio", "enunciado": "Em propriedades rurais com criação de suínos ou gado leiteiro, é comum a instalação de biodigestores que tratam o esterco dos animais. O produto gasoso gerado pela fermentação anaeróbia da matéria orgânica nesses sistemas é o:", "alternativas": {"A": "Gás oxigênio medicinal puro.", "B": "Biogás (composto predominantemente por gás metano - CH4), que pode ser queimado para gerar calor e eletricidade na fazenda.", "C": "Gás nobre hélio utilizado em balões meteorológicos.", "D": "Gás carbônico líquido incombustível.", "E": "Monóxido de carbono asfixiante descartado no ar."}, "resposta_correta": "B", "justificativa": "Bactérias metanogênicas decompõem fezes de animais e resíduos orgânicos em meio anaeróbio (ausência de O2) dentro de biodigestores, gerando biogás (60-70% CH4), uma fonte limpa e renovável de bioenergia rural.", "possui_imagem": false},
  {"id": 38, "uid": "CIEN-7-038", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Eficiência Energética no Cotidiano", "dificuldade": "Médio", "enunciado": "O Programa Brasileiro de Etiquetagem (PBE) do Inmetro atribui notas de eficiência energética aos eletrodomésticos, variando de 'A' (mais eficiente) a 'E' ou 'F' (menos eficiente). Escolher uma geladeira ou ar-condicionado com selo Procel 'A' significa optar por um equipamento que:", "alternativas": {"A": "Produz menos frio e não gela os alimentos no verão.", "B": "Executa a mesma função de refrigeração consumindo consideravelmente menos energia elétrica na conta de luz.", "C": "Custa o dobro e não possui garantia técnica de fábrica.", "D": "Utiliza carvão mineral em vez de eletricidade da tomada.", "E": "Funciona apenas durante o dia sob a luz do sol."}, "resposta_correta": "B", "justificativa": "A eficiência energética mede a razão entre o serviço prestado (trabalho de refrigeração) e o insumo consumido (quilowatt-hora de eletricidade). Aparelhos com classe 'A' possuem compressores modernos (como tecnologia inverter) que minimizam perdas.", "possui_imagem": false},
  {"id": 39, "uid": "CIEN-7-039", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Energia Eólica e Geração Elétrica", "dificuldade": "Médio", "enunciado": "Parques eólicos no litoral nordestino brasileiro contam com aerogeradores de grande porte que transformam a força dos ventos em eletricidade. A conversão de energia em um aerogerador é:", "alternativas": {"A": "Energia química da maresia -> Eletricidade.", "B": "Energia cinética dos ventos (que gira as pás da hélice) -> Energia mecânica de rotação -> Energia elétrica induzida no gerador.", "C": "Energia nuclear dos átomos de ar -> Energia térmica -> Eletricidade.", "D": "Energia solar fotovoltaica refletida nas pás brancas -> Eletricidade.", "E": "Energia sonora do vento -> Eletricidade por microfones acústicos."}, "resposta_correta": "B", "justificativa": "O fluxo de massas de ar (vento) possui energia cinética. As pás do rotor capturam essa força aerodinâmica, fazendo girar o eixo de baixa velocidade, multiplicado por engrenagens até acionar o gerador que converte energia mecânica em elétrica.", "possui_imagem": false},
  {"id": 40, "uid": "CIEN-7-040", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Poluição Térmica de Corpos Hídricos", "dificuldade": "Médio", "enunciado": "Usinas termoelétricas e termonucleares utilizam água de rios ou do mar para resfriar seus condensadores de vapor, devolvendo a água aquecida aos mananciais naturais. Esse aquecimento artificial das águas (poluição térmica) causa sérios impactos ecológicos aos peixes porque:", "alternativas": {"A": "A água quente congela instantaneamente as brânquias dos animais.", "B": "O aumento da temperatura da água diminui drasticamente a solubilidade do gás oxigênio (O2) dissolvido, podendo provocar asfixia e morte de organismos aquáticos.", "C": "A água morna faz os peixes perderem suas escamas em poucos segundos.", "D": "O vapor destrói todos os minerais de sal do oceano.", "E": "Os peixes passam a respirar gás carbônico puro."}, "resposta_correta": "B", "justificativa": "A solubilidade de gases em líquidos é inversamente proporcional à temperatura. Quando a água aquecida de usinas é despejada em rios, a concentração de O2 dissolvido despenca, enquanto a taxa metabólica dos peixes aumenta, levando a hipóxia severa.", "possui_imagem": false},
  {"id": 41, "uid": "CIEN-7-041", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Segurança na Automatização: Sensores de Parada", "dificuldade": "Médio", "enunciado": "Em células robóticas de manufatura avançada, utilizam-se cortinas de luz infravermelha e sensores a laser ao redor dos robôs. Se um operador humano ultrapassar a linha de segurança delimitada, o sistema:", "alternativas": {"A": "Acelera o robô para terminar o trabalho antes que o operador se aproxime.", "B": "Interrompe instantaneamente o movimento mecânico do robô (parada de emergência segura) para prevenir acidentes graves.", "C": "Desliga a iluminação da fábrica inteira.", "D": "Emite um choque elétrico no operador para alertá-lo.", "E": "Despeja tinta vermelha no chão da fábrica."}, "resposta_correta": "B", "justificativa": "Sistemas de segurança intrínseca e barreiras ópticas monitoram o perímetro de células automatizadas; a interrupção do feixe óptico aciona relés de segurança que cortam a energia motriz dos atuadores robóticos para proteção à vida.", "possui_imagem": false},
  {"id": 42, "uid": "CIEN-7-042", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Pegada de Carbono (Carbon Footprint)", "dificuldade": "Médio", "enunciado": "O conceito de 'pegada de carbono' representa a quantidade total de gases de efeito estufa (expressa em toneladas equivalentes de CO2) gerada direta ou indiretamente pelas atividades diárias de um indivíduo, empresa ou produto. Uma estratégia individual eficaz para reduzir a pegada de carbono pessoal é:", "alternativas": {"A": "Utilizar transporte coletivo ou bicicleta em vez de automóvel individual movido a combustíveis fósseis.", "B": "Deixar todas as lâmpadas da casa acesas durante a noite.", "C": "Queimar lixo plástico no quintal de casa aos finais de semana.", "D": "Substituir alimentos frescos por produtos altamente processados e importados de avião.", "E": "Tomar banhos de chuveiro elétrico de 40 minutos todos os dias."}, "resposta_correta": "A", "justificativa": "O setor de transporte individual por motores a combustão é um dos maiores emissores per capita de GEE. Priorizar mobilidade ativa (bicicleta, caminhada) e transporte coletivo reduz drasticamente a demanda por combustíveis fósseis.", "possui_imagem": false},
  {"id": 43, "uid": "CIEN-7-043", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "O Ciclo Ideal de Carnot e Limites Físicos", "dificuldade": "Difícil", "enunciado": "Em 1824, o engenheiro francês Sadi Carnot demonstrou teoricamente que o rendimento máximo possível de qualquer máquina térmica operando entre duas temperaturas absolutas (Tquente e Tfria, em Kelvin) é dado por η = 1 - (Tfria / Tquente). Essa lei física fundamental implica que:", "alternativas": {"A": "Uma máquina térmica pode atingir 100% de rendimento se o motor for bem lubrificado com óleo sintético.", "B": "Nenhuma máquina térmica real pode ter rendimento superior ao de uma máquina ideal de Carnot, e o rendimento de 100% é inalcançável porque exigiria uma fonte fria no zero absoluto (0 Kelvin).", "C": "O rendimento de um motor depende apenas da marca do combustível utilizado.", "D": "Máquinas térmicas funcionam com maior rendimento quando a fonte quente é fria e a fonte fria é quente.", "E": "O ciclo de Carnot aplica-se exclusivamente a locomotivas a carvão do século XIX."}, "resposta_correta": "B", "justificativa": "O Teorema de Carnot define o limite termodinâmico superior absoluto de rendimento de qualquer conversor de calor em trabalho. Como o zero absoluto (0 K) é inatingível na prática (3ª Lei), η < 1 sempre; logo, toda máquina dissipa calor.", "possui_imagem": false},
  {"id": 44, "uid": "CIEN-7-044", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Cálculo de Rendimento de Carnot", "dificuldade": "Difícil", "enunciado": "Uma usina termoelétrica a vapor opera com sua caldeira (fonte quente) a uma temperatura de 600 Kelvin e resfria seu condensador com água de rio (fonte fria) a 300 Kelvin. Qual é o rendimento MÁXIMO teórico que essa usina poderia atingir segundo o Ciclo de Carnot?", "alternativas": {"A": "25%.", "B": "50%.", "C": "75%.", "D": "90%.", "E": "100%."}, "resposta_correta": "B", "justificativa": "Pela fórmula de Carnot: η_max = 1 - (Tfria / Tquente) = 1 - (300 K / 600 K) = 1 - 0,5 = 0,50 (ou 50%). Mesmo na ausência absoluta de atritos ou perdas mecânicas, metade do calor deve ser rejeitado ao ambiente.", "possui_imagem": false},
  {"id": 45, "uid": "CIEN-7-045", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Monóxido de Carbono (CO) e Intoxicação Asfixiante", "dificuldade": "Difícil", "enunciado": "Em ambientes fechados onde há queima incompleta de combustíveis em aquecedores a gás sem ventilação ou motores ligados em garagens, há risco iminente de morte por inalação de monóxido de carbono (CO). A periculosidade extrema desse gás inodoro e incolor decorre do fato de que:", "alternativas": {"A": "O CO congela a traqueia humana instantaneamente.", "B": "O CO liga-se à hemoglobina do sangue com afinidade cerca de 200 a 250 vezes maior que o oxigênio, formando carboxiemoglobina e impedindo o transporte de O2 para as células do cérebro e coração.", "C": "O CO queima a pele por combustão espontânea externa.", "D": "O CO transforma os pulmões em pedras calcárias sólidas.", "E": "O CO destrói o esmalte dentário impedindo a mastigação."}, "resposta_correta": "B", "justificativa": "O monóxido de carbono é um asfixiante químico que forma ligação covalente de coordenação extremamente estável com o ferro da hemoglobina (carboxi-Hb). A saturação da hemoglobina impede a oxigenação celular e provoca hipóxia tecidual fatal sem causar tosse ou irritação prévia.", "possui_imagem": false},
  {"id": 46, "uid": "CIEN-7-046", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Cogeração de Energia", "dificuldade": "Difícil", "enunciado": "Em usinas de açúcar e álcool no Brasil, o bagaço resultante do esmagamento da cana é queimado em caldeiras de alta pressão para gerar vapor. Esse vapor aciona turbinas gerando eletricidade para a própria usina e para a rede elétrica nacional, e o calor residual do vapor de escape é aproveitado para aquecer as colunas de destilação de etanol. Esse processo integrado é denominado:", "alternativas": {"A": "Fissão nuclear caseira.", "B": "Cogeração de energia.", "C": "Combustão criogênica.", "D": "Fotossíntese eletroquímica.", "E": "Efeito estufa secundário."}, "resposta_correta": "B", "justificativa": "A cogeração é a produção simultânea e sequencial de duas ou mais formas úteis de energia (tipicamente eletricidade e energia térmica/vapor de processo) a partir de uma única fonte de combustível (biomassa da cana), elevando a eficiência térmica global acima de 80%.", "possui_imagem": false},
  {"id": 47, "uid": "CIEN-7-047", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Efeito Estufa Natural vs. Antropogênico", "dificuldade": "Difícil", "enunciado": "O efeito estufa é um fenômeno físico-químico natural da atmosfera terrestre que mantém a temperatura média do planeta em cerca de +15 ºC, permitindo a existência de água líquida e vida. O problema climático contemporâneo reside no:", "alternativas": {"A": "Fato de que o efeito estufa foi inventado em 1950 por cientistas da computação.", "B": "Aumento descontrolado na concentração de gases de efeito estufa provocado por atividades humanas (queima de fósseis, desmatamento), que retém calor em excesso na baixa atmosfera e altera o balanço radiativo do planeta (aquecimento global antropogênico).", "C": "Fato de que a atmosfera da Terra está perdendo todos os seus gases para o espaço sideral.", "D": "Resfriamento acelerado do Sol devido à poluição por fumaça.", "E": "Fato de que o efeito estufa bloqueia 100% da luz solar impedindo a fotossíntese."}, "resposta_correta": "B", "justificativa": "Sem o efeito estufa natural (vapor de água, CO2, metano), a temperatura média da Terra seria de aproximadamente -18 ºC (congelada). O agravamento antropogênico intensifica a forçante radiativa positiva, desequilibrando o sistema climático global.", "possui_imagem": false},
  {"id": 48, "uid": "CIEN-7-048", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Entropia e Degradação da Energia", "dificuldade": "Difícil", "enunciado": "Na termodinâmica, a grandeza física chamada 'entropia' está associada à dispersão da energia e ao grau de desordem de um sistema. Quando um carro queima combustível e anda, parte da energia química organizada é convertida em energia cinética e o restante é dissipado na forma de calor no radiador e atrito nos pneus. Sob a ótica da entropia:", "alternativas": {"A": "A quantidade total de energia do universo diminuiu.", "B": "A energia total se conservou (1ª Lei), mas a qualidade e utilidade da energia degradaram-se, aumentando a entropia do universo (2ª Lei).", "C": "A energia do carro transformou-se em matéria atômica indestrutível.", "D": "A entropia do universo diminui sempre que um carro acelera.", "E": "O calor dissipado pode ser recolhido do ar e transformado em gasolina pura sem gasto de energia."}, "resposta_correta": "B", "justificativa": "A Primeira Lei estabelece a conservação da quantidade de energia (ΔU = Q - W). A Segunda Lei determina a degradação inevitável da qualidade da energia: formas nobres e organizadas de energia degradam-se em calor disperso de baixa temperatura e alta entropia.", "possui_imagem": false},
  {"id": 49, "uid": "CIEN-7-049", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Combustíveis Hidrocarbonetos e Densidade Energética", "dificuldade": "Difícil", "enunciado": "Uma das razões pelas quais a gasolina e o óleo diesel ainda são amplamente utilizados na aviação e no transporte de carga pesado em navios e caminhões de longa distância, apesar de seus impactos ambientais, é a sua altíssima densidade energética por massa (cerca de 44 a 46 MJ/kg). Em comparação, as melhores baterias de íons de lítio atuais possuem densidade energética de aproximadamente 0,9 a 1,0 MJ/kg. Essa disparidade significa que:", "alternativas": {"A": "Um avião elétrico precisaria de baterias dezenas de vezes mais pesadas do que o combustível de aviação fóssil para voar a mesma distância, tornando o peso inviável para decolagem comercial de longo alcance.", "B": "As baterias elétricas explodem espontaneamente em qualquer altitude elevada.", "C": "A gasolina de aviação não queima na presença de oxigênio.", "D": "O óleo diesel é feito de gases nobres ultraleves.", "E": "Os aviões a combustão gastam menos oxigênio por quilômetro do que uma bicicleta."}, "resposta_correta": "A", "justificativa": "A densidade gravimétrica de energia dos hidrocarbonetos fósseis é mais de 40 vezes superior à das baterias eletroquímicas modernas. Para aeronaves de longo curso, o peso gigantesco de baterias equivalentes comprometeria o limite máximo de decolagem estrutural.", "possui_imagem": false},
  {"id": 50, "uid": "CIEN-7-050", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Células a Combustível de Hidrogênio", "dificuldade": "Difícil", "enunciado": "Veículos movidos a células a combustível de hidrogênio (FCEV) combinam gás hidrogênio (H2) armazenado em tanques de alta pressão com oxigênio (O2) do ar para gerar eletricidade e mover motores elétricos. O único subproduto emitido pelo escapamento desse veículo em operação é:", "alternativas": {"A": "Dióxido de enxofre tóxico.", "B": "Água líquida / vapor de água (H2O) pura.", "C": "Monóxido de carbono e fuligem preta.", "D": "Ácido sulfúrico diluído.", "E": "Chumbo tetraetila gasoso."}, "resposta_correta": "B", "justificativa": "Na célula a combustível tipo membrana de troca de prótons (PEMFC), o H2 sofre oxidação anódica e o O2 sofre redução catódica, gerando corrente elétrica útil e produzindo exclusivamente água (2 H2 + O2 -> 2 H2O) e calor residual limpo.", "possui_imagem": false},
  {"id": 51, "uid": "CIEN-7-051", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Gêmeos Digitais (Digital Twins) na Indústria 4.0", "dificuldade": "Difícil", "enunciado": "Nas linhas fabris mais avançadas do mundo, engenheiros utilizam a tecnologia de 'Gêmeos Digitais' (Digital Twins). Essa ferramenta tecnológica consiste em:", "alternativas": {"A": "Contratar dois operários idênticos para trabalhar no mesmo turno de serviço.", "B": "Um modelo virtual digital altamente fiel de um produto ou processo físico em operação real, atualizado continuamente por dados de sensores em tempo real para simular cenários e prever manutenções.", "C": "Duas máquinas mecânicas que quebram sempre no mesmo dia.", "D": "A clonagem biológica de técnicos de manutenção industrial.", "E": "Um espelho de vidro colocado na frente da esteira transportadora."}, "resposta_correta": "B", "justificativa": "Um Digital Twin é uma representação computacional virtual dinâmica de um ativo, máquina ou sistema físico, acoplada bidirecionalmente por sensores IoT, permitindo testes preditivos, análise de fadiga e otimização operacional sem interrupção física.", "possui_imagem": false},
  {"id": 52, "uid": "CIEN-7-052", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Injeção Eletrônica vs. Carburador", "dificuldade": "Difícil", "enunciado": "Até a década de 1990, os carros utilizavam carburadores mecânicos para misturar o combustível ao ar. Atualmente, todos os carros utilizam sistemas computadorizados de injeção eletrônica multiponto. A superioridade da injeção eletrônica deve-se a:", "alternativas": {"A": "Medir parâmetros com sensores (como sonda lambda no escapamento, sensor de fluxo de ar e rotação) e dosar com precisão microscópica a quantidade ideal de combustível (razão estequiométrica), maximizando a potência e minimizando o consumo e as emissões de poluentes.", "B": "Fazer o carro funcionar sem necessidade de queima de combustível.", "C": "Misturar água da chuva na gasolina para reduzir o custo do abastecimento.", "D": "Eliminar os pistões e o virabrequim do interior do motor a combustão.", "E": "Resfriar o escapamento com nitrogênio líquido comercial."}, "resposta_correta": "A", "justificativa": "A injeção eletrônica gerida por uma Unidade de Controle do Motor (ECU) monitora a estequiometria da mistura em malha fechada via sensor de oxigênio (sonda lambda), assegurando que o catalisador funcione em sua faixa máxima de conversão química.", "possui_imagem": false},
  {"id": 53, "uid": "CIEN-7-053", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Efeito da Altitude no Desempenho de Motores a Combustão", "dificuldade": "Difícil", "enunciado": "Um carro com motor a combustão naturalmente aspirado (sem turbo) perde cerca de 10% de sua potência a cada 1.000 metros de altitude em relação ao nível do mar (por exemplo, ao subir a Cordilheira dos Andes). A explicação física para essa perda de rendimento é:", "alternativas": {"A": "A gravidade nas montanhas atrai o carro com força excessiva para trás.", "B": "A pressão atmosférica e a densidade do ar diminuem com a altitude, de modo que cada cilindrada do motor admite uma massa menor de gás oxigênio (comburente), queimando menos combustível por ciclo.", "C": "O combustível congela instantaneamente dentro do tanque nas montanhas.", "D": "O atrito das rodas com o asfalto das serras anula a eletricidade da bateria.", "E": "O motor a combustão só funciona quando a pressão atmosférica é superior a 5 atmosferas."}, "resposta_correta": "B", "justificativa": "A densidade do ar cai exponencialmente com a altitude devido à rarefação da atmosfera. Em altitudes elevadas, a menor pressão parcial de O2 admitida em cada curso de aspiração limita a quantidade de combustível que pode reagir estequiometricamente, derrubando a pressão média efetiva nos pistões.", "possui_imagem": false},
  {"id": 54, "uid": "CIEN-7-054", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Turbocompressores: Reaproveitamento de Energia de Exaustão", "dificuldade": "Difícil", "enunciado": "Os motores turbocomprimidos modernos (turbo) conseguem entregar grande potência a partir de cilindradas pequenas (como motores 1.0 turbo com desempenho de 2.0 aspirados). O princípio de funcionamento do turbocompressor baseia-se em:", "alternativas": {"A": "Utilizar o fluxo veloz e quente dos gases de escape que seriam descartados para girar uma turbina, que por sua vez aciona um compressor que força uma quantidade maior de ar comprimido para dentro dos cilindros.", "B": "Queimar hidrogênio atômico puro injetado diretamente nas velas de ignição.", "C": "Eliminar o óleo lubrificante para diminuir o atrito interno do bloco do motor.", "D": "Aumentar o peso do virabrequim em 500 quilos de chumbo.", "E": "Armazenar vento em botijões sob o banco do passageiro."}, "resposta_correta": "A", "justificativa": "O turbocompressor reaproveita a entalpia residual dos gases da exaustão: os gases em expansão movem uma turbina acoplada por eixo a um compressor centrífugo, que pressuriza o ar admitido (sobrealimentação), aumentando a massa de comburente por ciclo sem consumir potência mecânica direta do eixo motriz.", "possui_imagem": false},
  {"id": 55, "uid": "CIEN-7-055", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Cracking Catalítico do Petróleo", "dificuldade": "Difícil", "enunciado": "O petróleo cru extraído dos poços de perfuração é uma mistura complexa de milhares de hidrocarbonetos. Nas refinarias, além da destilação fracionada, utiliza-se o processo químico de 'craqueamento catalítico' (cracking). Esse processo consiste em:", "alternativas": {"A": "Fundir átomos de hidrogênio para formar hélio como no interior do Sol.", "B": "Quebrar moléculas grandes e pesadas de hidrocarbonetos de baixo valor comercial (como óleos pesados) em moléculas menores e mais leves de alto valor comercial e energético (como gasolina e GLP), utilizando altas temperaturas e catalisadores.", "C": "Misturar água e sabão no petróleo para transformá-lo em querosene de aviação.", "D": "Remover todo o carbono do petróleo deixando apenas oxigênio líquido.", "E": "Solidificar o petróleo em blocos de gelo para transporte em navios."}, "resposta_correta": "B", "justificativa": "O craqueamento (pirólise catalítica) quebra ligações carbono-carbono de frações pesadas de gasóleo residual sob ação de zeólitas aquecidas a cerca de 500 ºC, maximizando o rendimento de frações leves de alta octanagem demandadas pelo mercado automotivo.", "possui_imagem": false},
  {"id": 56, "uid": "CIEN-7-056", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Otimização de Linhas de Produção: Métricas OEE", "dificuldade": "Difícil", "enunciado": "Na engenharia de produção de fábricas automatizadas, utiliza-se a métrica OEE (Overall Equipment Effectiveness / Eficácia Global do Equipamento) para monitorar a saúde produtiva das máquinas. O OEE é calculado pelo produto de três indicadores fundamentais:", "alternativas": {"A": "Peso da máquina x Altura do galpão x Número de lâmpadas acesas.", "B": "Disponibilidade (tempo em que a máquina esteve apta a operar) x Desempenho (velocidade real em relação à projetada) x Qualidade (proporção de peças perfeitas sem defeitos).", "C": "Salário dos operários x Preço da energia elétrica x Imposto de renda.", "D": "Consumo de água x Temperatura da caldeira x Velocidade do vento local.", "E": "Número de robôs x Quilometragem dos caminhões de entrega x Lucro líquido."}, "resposta_correta": "B", "justificativa": "A metodologia OEE integra sistematicamente as três principais dimensões de perda operacional de qualquer ativo produtivo: perdas por paradas (Disponibilidade), perdas por velocidade reduzida (Desempenho) e perdas por refugo/reparo (Qualidade).", "possui_imagem": false},
  {"id": 57, "uid": "CIEN-7-057", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Biodigestão Anaeróbia: Etapas Bioquímicas", "dificuldade": "Difícil", "enunciado": "A conversão biológica de dejetos orgânicos em biogás dentro de um biodigestor não ocorre em uma única etapa, mas sim através de uma cadeia metabólica complexa realizada por diferentes consórcios de microrganismos. A sequência correta das etapas da digestão anaeróbia é:", "alternativas": {"A": "Metanogênese -> Respiração celular -> Fotossíntese -> Destilação.", "B": "Hidrólise (quebra de polímeros) -> Acidogênese (produção de ácidos graxos voláteis) -> Acetogênese (produção de acetato e H2) -> Metanogênese (produção de metano CH4 por arqueias).", "C": "Combustão externa -> Condensação -> Oxidação -> Evaporação.", "D": "Fermentação alcoólica -> Filtração mecânica -> Eletrólise -> Queima.", "E": "Acidogênese -> Calcificação -> Cristalização -> Fusão."}, "resposta_correta": "B", "justificativa": "A digestão anaeróbia decompõe matéria orgânica complexa em quatro fases coordenadas: 1) Hidrólise enzimática; 2) Acidogênese fermentativa; 3) Acetogênese por bactérias sintróficas; 4) Metanogênese por arqueias metanogênicas estritas que convertem acetato, CO2 e H2 em CH4.", "possui_imagem": false},
  {"id": 58, "uid": "CIEN-7-058", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Custo Ambiental da Cadeia de Baterias", "dificuldade": "Difícil", "enunciado": "Embora os veículos elétricos não emitam gases pelo escapamento durante o uso, a análise de ciclo de vida (ACV) completa desses veículos exige avaliar os impactos socioambientais da fabricação de suas baterias de alta capacidade, que envolvem:", "alternativas": {"A": "A destruição total de todo o plástico do planeta.", "B": "A mineração em larga escala de metais como lítio, níquel e cobalto, que demanda intenso consumo de água, gera efluentes e pode causar degradação ambiental em regiões ecologicamente sensíveis se não houver reciclagem eficiente.", "C": "A queima de carvão vegetal dentro das células da bateria durante a viagem.", "D": "A emissão de radiação nuclear gama nas ruas das cidades.", "E": "A proliferação de bactérias devoradoras de estradas de asfalto."}, "resposta_correta": "B", "justificativa": "A avaliação de sustentabilidade deve abranger o berço ao túmulo (Life Cycle Assessment). A extração de matérias-primas críticas (lítio em salares, cobalto e níquel) gera expressiva pegada hídrica e emissões incorporadas, demandando cadeias de suprimento responsáveis e reciclagem circular em circuito fechado.", "possui_imagem": false},
  {"id": 59, "uid": "CIEN-7-059", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Manutenção Preditiva com Aprendizado de Máquina", "dificuldade": "Difícil", "enunciado": "Diferente da manutenção corretiva (consertar após a quebra) e da preventiva (trocar peças por tempo fixo de calendário), a 'manutenção preditiva' apoiada por Inteligência Artificial na indústria baseia-se em:", "alternativas": {"A": "Desligar as máquinas toda sexta-feira para economizar peças.", "B": "Monitorar continuamente parâmetros operacionais (vibração mecânica, temperatura de mancais, espectrometria do óleo e ultrassom) com sensores IoT e algoritmos que detectam padrões anômalos que indicam falha iminente, programando o reparo antes que a avaria ocorra.", "C": "Substituir todos os motores a cada trinta dias por precaução extrema.", "D": "Esperar que o motor pegue fogo para acionar os bombeiros industriais.", "E": "Substituir técnicos humanos por manuais de papel guardados em gavetas."}, "resposta_correta": "B", "justificativa": "A manutenção preditiva baseada em condições (CBM) utiliza telemetria em tempo real e modelos de machine learning para identificar anomalias espectrais ou assinaturas térmicas incipientes, maximizando a vida útil remanescente (RUL) de componentes críticos.", "possui_imagem": false},
  {"id": 60, "uid": "CIEN-7-060", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Relação Ar-Combustível e Emissões de NOx", "dificuldade": "Difícil", "enunciado": "Nos motores de combustão interna, quando a mistura queima com excesso de ar (mistura pobre) sob pressões e temperaturas extremamente elevadas no interior da câmara, o nitrogênio atmosférico (N2), que normalmente é inerte, reage com o oxigênio (O2), formando óxidos de nitrogênio (NO e NO2, conhecidos coletivamente como NOx). O problema dessas emissões é que o NOx:", "alternativas": {"A": "É um gás doce que melhora a qualidade do ar nas florestas.", "B": "Contribui diretamente para a formação de nevoeiro fotoquímico (smog), geração de ozônio tóxico na troposfera e formação de ácido nítrico causador de chuva ácida.", "C": "Faz os rios se transformarem em água mineral pura.", "D": "Resfria o clima da Terra a ponto de congelar os motores dos carros.", "E": "Transforma os pneus de borracha em aço temperado."}, "resposta_correta": "B", "justificativa": "A formação térmica de NOx (mecanismo de Zeldovich) ocorre em temperaturas superiores a 1.300 ºC. O dióxido de nitrogênio reage fotoquimicamente na presença de hidrocarbonetos e luz solar formando ozônio ao nível do solo (smog fotoquímico) e ácido nítrico (HNO3).", "possui_imagem": false},
  {"id": 61, "uid": "CIEN-7-061", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Avanço da Automação e o Futuro do Trabalho", "dificuldade": "Difícil", "enunciado": "Relatórios da Organização Internacional do Trabalho (OIT) e de fóruns globais destacam que o avanço veloz da automação robótica e da IA substituirá milhões de postos de trabalho operacionais repetitivos, mas criará novas demandas profissionais. O principal desafio educacional e social decorrente dessa transformação tecnológica é:", "alternativas": {"A": "Proibir totalmente o ensino de ciências e matemática nas escolas para conter as máquinas.", "B": "A necessidade de requalificação profissional contínua da força de trabalho (lifelong learning), desenvolvendo competências analíticas complexas, criatividade, pensamento crítico e habilidades socioemocionais que não são facilmente automatizadas por máquinas.", "C": "Construir fábricas sem eletricidade para que mais pessoas precisem trabalhar manualmente.", "D": "Forçar todas as crianças a trabalharem como operárias a partir dos 10 anos de idade.", "E": "Destruir todos os computadores para restaurar o século XIX."}, "resposta_correta": "B", "justificativa": "A Quarta Revolução Industrial altera profundamente a divisão social do trabalho. Enquanto tarefas procedimentais e rotineiras são assumidas por algoritmos e robótica, cresce a demanda por julgamento crítico, resolução de problemas interdisciplinares, flexibilidade cognitiva e habilidades relacionais humanas.", "possui_imagem": false},
  {"id": 62, "uid": "CIEN-7-062", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Armazenamento de Energia em Redes Renováveis Intermitentes", "dificuldade": "Difícil", "enunciado": "Fontes renováveis como solar fotovoltaica e eólica apresentam o desafio técnico da intermitência (o sol não brilha à noite e o vento varia constantemente). Para manter a estabilidade contínua do fornecimento na rede elétrica de um país com alta penetração dessas fontes, é indispensável o uso de:", "alternativas": {"A": "Sistemas de armazenamento de energia em larga escala (como baterias utilitárias de rede, usinas hidrelétricas reversíveis de bombeamento e hidrogênio verde), além de redes elétricas inteligentes (Smart Grids).", "B": "Queima de pneus velhos nos horários de pico para aquecer os postes de luz.", "C": "Desligamento obrigatório de todas as geladeiras do país aos domingos.", "D": "Espelhos espaciais de vidro para focar a luz da Lua nos telhados residenciais.", "E": "Cabos de cobre submarinos conectados ao centro da Terra."}, "resposta_correta": "A", "justificativa": "A intermitência climática exige flexibilidade no lado da oferta e da demanda. Sistemas de armazenamento (baterias de fluxo/íon-lítio, hidrelétricas reversíveis que bombeiam água de volta ao reservatório superior) e redes digitais inteligentes balanceiam a carga horária sem apagões.", "possui_imagem": false},
  {"id": 63, "uid": "CIEN-7-063", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 15: Máquinas Térmicas, Combustíveis e Tecnologia", "tema": "Ciclo Termodinâmico Combinado em Termoelétricas Modernas", "dificuldade": "Difícil", "enunciado": "As usinas termoelétricas de ponta a gás natural operam em 'Ciclo Combinado', atingindo eficiências térmicas próximas de 60% (as mais altas da engenharia de potência térmica). A arquitetura inovadora do ciclo combinado consiste em:", "alternativas": {"A": "Queimar gás natural duas vezes no mesmo tanque de combustível.", "B": "Acoplar dois ciclos termodinâmicos em série: o gás natural queima em uma turbina a gás (Ciclo Brayton) e os gases de escape em altíssima temperatura passam por uma caldeira de recuperação que produz vapor para acionar uma segunda turbina (Ciclo Rankine).", "C": "Misturar álcool e carvão mineral em água com gás pressurizada.", "D": "Utilizar a eletricidade da tomada para aquecer o gás antes de queimar.", "E": "Operar os motores sob a água do mar para evitar aquecimento das peças."}, "resposta_correta": "B", "justificativa": "O Ciclo Combinado integra o ciclo Joule-Brayton no topo (gases a mais de 1.100 ºC em turbina a gás) com o ciclo Rankine na base (recuperação de calor em gerador de vapor HRSG acionando turbina a vapor), reaproveitando a entalpia residual de escape e superando o limite individual de cada ciclo isolado.", "possui_imagem": false},
  {"id": 64, "uid": "CIEN-7-064", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Características Gerais dos Cordados", "dificuldade": "Fácil", "enunciado": "Todos os animais pertencentes ao filo Chordata (Cordados), incluindo peixes, anfíbios, répteis, aves e mamíferos, compartilham características diagnósticas exclusivas durante o desenvolvimento embrionário. Entre elas, destaca-se a presença de um eixo de sustentação flexível chamado:", "alternativas": {"A": "Coluna vertebral de osso puro desde a fecundação.", "B": "Notocorda.", "C": "Carapaça de quitina externa.", "D": "Casca calcária rígida.", "E": "Tentáculos urticantes na boca."}, "resposta_correta": "B", "justificativa": "A notocorda é o bastão dorsal fibrocelular semirrígido que atua como eixo de sustentação esquelético primitivo presente em todos os embriões de cordados, sendo substituída pela coluna vertebral nos vertebrados adultos.", "possui_imagem": true},
  {"id": 65, "uid": "CIEN-7-065", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Classificação dos Peixes: Condríctes vs. Osteíctes", "dificuldade": "Fácil", "enunciado": "Os peixes são tradicionalmente divididos em dois grandes grupos taxonômicos principais de acordo com a composição predominante de seu esqueleto interno. Esses dois grupos são:", "alternativas": {"A": "Peixes pulmonados e peixes fósseis.", "B": "Condríctes (peixes cartilaginosos) e Osteíctes (peixes ósseos).", "C": "Anfíbios aquáticos e répteis marinhos.", "D": "Peixes terrestres e peixes de água doce.", "E": "Craniados e invertebrados marinhos."}, "resposta_correta": "B", "justificativa": "Chondrichthyes (tubarões, raias e quimeras) possuem endoesqueleto cartilaginoso; Osteichthyes (como sardinhas, tilápias, atuns e bacalhaus) possuem esqueleto predominantemente ósseo mineralizado.", "possui_imagem": true},
  {"id": 66, "uid": "CIEN-7-066", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Bexiga Natatória em Peixes Ósseos", "dificuldade": "Fácil", "enunciado": "A maioria dos peixes ósseos possui um órgão interno em forma de saco preenchido por gases, que se enche ou esvazia permitindo ao peixe subir ou descer na coluna de água sem gastar energia nadando. Esse órgão é a:", "alternativas": {"A": "Linha lateral sensorial.", "B": "Bexiga natatória.", "C": "Brânquia opercular.", "D": "Nadadeira caudal heterocerca.", "E": "Ampola de Lorenzini."}, "resposta_correta": "B", "justificativa": "A bexiga natatória atua como um órgão hidrostático; ao controlar o volume de gás em seu interior, o peixe regula sua densidade média igualando-a à da água na profundidade desejada (flutuabilidade neutra).", "possui_imagem": true},
  {"id": 67, "uid": "CIEN-7-067", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Órgão Sensorial: Linha Lateral dos Peixes", "dificuldade": "Fácil", "enunciado": "Ao observar a lateral do corpo de um peixe ósseo, nota-se uma linha longitudinal de pequenos poros que vai da cabeça até a cauda (linha lateral). Esse órgão sensorial serve para o peixe:", "alternativas": {"A": "Sentir o cheiro de algas marinhas no fundo da água.", "B": "Detectar correntes de água, vibrações mecânicas e variações de pressão ao seu redor.", "C": "Produzir luz fluorescente no escuro dos oceanos.", "D": "Armazenar urina antes de eliminá-la na água.", "E": "Respirar oxigênio quando sai da água para pular."}, "resposta_correta": "B", "justificativa": "A linha lateral é um sistema mecanorreceptor composto por neuromastos que captam ondas de pressão e movimentação da água, permitindo ao peixe navegar em cardumes e detectar presas e predadores.", "possui_imagem": true},
  {"id": 68, "uid": "CIEN-7-068", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Respiração dos Peixes", "dificuldade": "Fácil", "enunciado": "A captação de gás oxigênio dissolvido na água pela grande maioria das espécies de peixes ocorre por meio de órgãos laminares altamente vascularizados chamados:", "alternativas": {"A": "Pulmões traqueais.", "B": "Brânquias (guelras).", "C": "Pele queratinizada grossa.", "D": "Tentáculos bucais.", "E": "Espiráculos abdominais."}, "resposta_correta": "B", "justificativa": "As brânquias são filamentos ricamente vascularizados adaptados para trocas gasosas na água, onde o oxigênio dissolvido na água passa para o sangue por difusão.", "possui_imagem": true},
  {"id": 69, "uid": "CIEN-7-069", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Opérculo em Peixes Ósseos", "dificuldade": "Fácil", "enunciado": "Diferente dos tubarões, que possuem fendas branquiais abertas para o exterior, os peixes ósseos possuem uma placa óssea protetora móvel de cada lado da cabeça que cobre e protege as brânquias, chamada de:", "alternativas": {"A": "Nadadeira dorsal.", "B": "Opérculo.", "C": "Clásper copulatório.", "D": "Escama placoide.", "E": "Plastrom protetor."}, "resposta_correta": "B", "justificativa": "O opérculo é a tampa óssea lateral que recobre a câmara branquial dos osteíctes, funcionando ativamente como uma bomba de sucção para renovar o fluxo contínuo de água sobre as brânquias.", "possui_imagem": true},
  {"id": 70, "uid": "CIEN-7-070", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Conceito de Anfíbio: Vida Dupla", "dificuldade": "Fácil", "enunciado": "O nome da classe Amphibia tem origem grega e significa literalmente 'vida dupla' (amphi = dois; bios = vida). Esse nome foi atribuído a esse grupo biológico porque a maioria de suas espécies:", "alternativas": {"A": "Consegue viver tanto no planeta Terra quanto no espaço sideral.", "B": "Passa por uma fase larval aquática com respiração branquial (girino) e uma fase adulta terrestre ou semi-aquática com respiração pulmonar e cutânea.", "C": "Possui dois corações e quatro cérebros em cada indivíduo.", "D": "Pode se transformar em peixe quando chega à velhice.", "E": "Alimenta-se exclusivamente de água e luz solar."}, "resposta_correta": "B", "justificativa": "A denominação faz referência ao ciclo de vida bifásico característico dos anfíbios: fase de larva aquática (girino herbívoro com brânquias e cauda nadadeira) e fase adulta pós-metamorfose (carnívora, tetrápode, pulmonada e cutânea).", "possui_imagem": true},
  {"id": 71, "uid": "CIEN-7-071", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Metamorfose dos Anuros", "dificuldade": "Fácil", "enunciado": "Durante o desenvolvimento de um sapo, o girino aquático sofre profundas transformações anatômicas até se tornar um indivíduo adulto. Durante a metamorfose do girino ocorrem:", "alternativas": {"A": "O crescimento de guelras adicionais e a perda de todas as patas.", "B": "A regressão da cauda e das brânquias, o desenvolvimento de membros locomotores (patas) e a formação de pulmões.", "C": "O surgimento de penas impermeáveis no abdômen.", "D": "A transformação do esqueleto em casca calcária externa.", "E": "A perda da capacidade de saltar no solo seco."}, "resposta_correta": "B", "justificativa": "Na metamorfose dos anuros, ocorrem apoptose e reabsorção da cauda, atrofia das brânquias, desenvolvimento das quatro patas e diferenciação dos pulmões e pele vascularizada para vida semi-terrestre.", "possui_imagem": true},
  {"id": 72, "uid": "CIEN-7-072", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Ordens de Anfíbios", "dificuldade": "Fácil", "enunciado": "Os anfíbios atuais são agrupados em três ordens zoológicas. Sapos, rãs e pererecas pertencem à ordem:", "alternativas": {"A": "Urodela (como as salamandras).", "B": "Anura (anfíbios sem cauda no estado adulto).", "C": "Gymnophiona / Apoda (como as cobras-cegas).", "D": "Testudines (como as tartarugas).", "E": "Squamata (como os lagartos)."}, "resposta_correta": "B", "justificativa": "A ordem Anura (do grego an = sem, oura = cauda) reúne sapos, rãs e pererecas, caracterizados pela ausência de cauda na fase adulta e membros posteriores alongados adaptados ao salto.", "possui_imagem": true},
  {"id": 73, "uid": "CIEN-7-073", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Respiração Cutânea em Anfíbios", "dificuldade": "Fácil", "enunciado": "A pele dos sapos e rãs é muito fina, desprovida de escamas, altamente vascularizada e mantida constantemente úmida por secreções de glândulas mucosas. Essa característica da pele é essencial para a:", "alternativas": {"A": "Respiração cutânea, permitindo a difusão de oxigênio do ar diretamente para o sangue através da pele.", "B": "Produção de eletricidade estática para afastar predadores.", "C": "Locomoção rápida no fundo da areia do deserto seco.", "D": "Proteção contra o frio por meio de grossas camadas de pelos.", "E": "Digestão externa de insetos capturados pela língua."}, "resposta_correta": "A", "justificativa": "Como os pulmões dos anfíbios são saculiformes simples com pouca superfície de troca, a respiração cutânea responde por grande parte da captação de O2 e eliminação de CO2, exigindo pele constantemente hidratada.", "possui_imagem": true},
  {"id": 74, "uid": "CIEN-7-074", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Dependência da Água para Reprodução dos Anfíbios", "dificuldade": "Fácil", "enunciado": "A maioria dos anfíbios não consegue colonizar ambientes terrestres áridos e secos, dependendo obrigatoriamente de corpos d'água doce (lagoas, poças) para a reprodução porque:", "alternativas": {"A": "Seus ovos não possuem casca protetora contra o ressecamento e desidratariam rapidamente no solo seco.", "B": "Eles só conseguem enxergar fêmeas quando estão debaixo d'água.", "C": "A água do mar é necessária para endurecer os ossos do sapo adulto.", "D": "Eles bebem 100 litros de água por minuto durante o acasalamento.", "E": "Os girinos nascem com asas e precisam de água para aprender a voar."}, "resposta_correta": "A", "justificativa": "Os ovos de anfíbios são anamnióticos (desprovidos de casca calcária impermeável e de âmnio), envoltos apenas por cápsulas gelatinosas permeáveis que perdem água rapidamente no ar seco.", "possui_imagem": true},
  {"id": 75, "uid": "CIEN-7-075", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Glândulas Paratóides nos Sapos", "dificuldade": "Fácil", "enunciado": "Atrás dos olhos dos sapos verdadeiros (como o sapo-cururu) existem duas bolsas salientes visíveis chamadas glândulas paratóides. A função biológica dessas glândulas é:", "alternativas": {"A": "Armazenar água mineral para beber no verão.", "B": "Produzir e armazenar substâncias tóxicas de defesa que são expelidas quando a glândula é pressionada na boca de um predador.", "C": "Secretar lágrimas salgadas para lubrificar a língua.", "D": "Ajudar o sapo a ouvir sons de alta frequência debaixo da terra.", "E": "Produzir ovos durante o período reprodutivo."}, "resposta_correta": "B", "justificativa": "As glândulas paratóides contêm veneno leitoso (bufotoxina); quando um predador (como um cão ou serpente) morde a cabeça do sapo, a pressão mecânica esguicha a secreção tóxica na mucosa bucal, causando irritação e rejeição.", "possui_imagem": true},
  {"id": 76, "uid": "CIEN-7-076", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Conquista do Ambiente Terrestre pelos Répteis", "dificuldade": "Fácil", "enunciado": "Os répteis foram os primeiros vertebrados a conquistar de forma definitiva e independente o ambiente terrestre seco. Essa conquista evolutiva foi possibilitada principalmente pelo surgimento de:", "alternativas": {"A": "Pele fina e úmida e ovos sem casca depositados em lagoas.", "B": "Pele impermeável e queratinizada com escamas e ovo amniótico com casca resistente à dessecação.", "C": "Membros voadores dotados de penas térmicas.", "D": "Brânquias operculadas que respiram oxigênio da areia.", "E": "Glândulas mamárias que amamentam os filhotes no deserto."}, "resposta_correta": "B", "justificativa": "A independência da água foi viabilizada pela cobertura tegumentar fortemente queratinizada e impermeável (evitando perda de água corpórea) e pelo ovo amniótico com casca calcária que protege o embrião no solo seco.", "possui_imagem": true},
  {"id": 77, "uid": "CIEN-7-077", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "O Ovo Amniótico dos Répteis", "dificuldade": "Fácil", "enunciado": "O ovo com casca dos répteis possui estruturas anexas especiais que garantem a sobrevivência do embrião fora da água. A bolsa repleta de líquido que envolve diretamente o embrião, protegendo-o contra choques mecânicos e desidratação, é o:", "alternativas": {"A": "Alantoide.", "B": "Âmnio (líquido amniótico).", "C": "Saco vitelínico.", "D": "Córion externo.", "E": "Opérculo."}, "resposta_correta": "B", "justificativa": "O âmnio é uma membrana anexa que delimita a cavidade amniótica cheia de fluido, criando um 'aquário particular' no qual o embrião se desenvolve protegido contra ressecamento e impactos mecânicos.", "possui_imagem": true},
  {"id": 78, "uid": "CIEN-7-078", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Grupos de Répteis Atuais", "dificuldade": "Fácil", "enunciado": "Tartarugas marinhas, jabutis terrestres e cágados de água doce pertencem a qual ordem da classe dos répteis?", "alternativas": {"A": "Squamata (escamados).", "B": "Testudines (quelônios).", "C": "Crocodylia (crocodilianos).", "D": "Anura (anfíbios com carapaça).", "E": "Urodela (salamandras de casco)."}, "resposta_correta": "B", "justificativa": "A ordem Testudines (Chelonia) engloba os quelônios, caracterizados pela presença de carapaça dorsal e plastrão ventral ósseos fundidos às costelas e vértebras, e bico córneo desprovido de dentes.", "possui_imagem": false},
  {"id": 79, "uid": "CIEN-7-079", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Termorregulação: Ectotermia", "dificuldade": "Fácil", "enunciado": "Peixes, anfíbios e répteis são animais ectotérmicos (antigamente chamados de 'animais de sangue frio'). Isso significa que eles:", "alternativas": {"A": "Possuem sangue congelado com temperatura de zero graus Celsius.", "B": "Não conseguem produzir calor metabólico suficiente para manter a temperatura do corpo constante, dependendo de fontes externas de calor (como o sol) para se aquecer.", "C": "Mantêm a temperatura do corpo rigorosamente constante em 37 ºC mesmo no inverno.", "D": "Possuem pele coberta por penas de isolamento térmico.", "E": "Não têm vasos sanguíneos nem coração para bombear sangue."}, "resposta_correta": "B", "justificativa": "Organismos ectotérmicos dependem primordialmente da absorção de calor do ambiente circundante (radiação solar, contato com substratos aquecidos) e de ajustes comportamentais para regular sua temperatura interna.", "possui_imagem": false},
  {"id": 80, "uid": "CIEN-7-080", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Escamas dos Répteis", "dificuldade": "Fácil", "enunciado": "A pele dos lagartos e serpentes é seca e coberta por escamas epidérmicas formadas por uma proteína rígida e impermeável que também compõe as nossas unhas e cabelos. Essa proteína é a:", "alternativas": {"A": "Hemoglobina.", "B": "Queratina.", "C": "Insulina.", "D": "Amilase.", "E": "Clorofila."}, "resposta_correta": "B", "justificativa": "A queratina é uma escleroproteína insolúvel e altamente resistente sintetizada pelas células da epiderme, que confere rigidez, impermeabilidade e proteção mecânica ao tegumento dos répteis.", "possui_imagem": false},
  {"id": 81, "uid": "CIEN-7-081", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Troca de Pele nas Serpentes: Ecdise", "dificuldade": "Fácil", "enunciado": "Ao longo de seu crescimento, as serpentes periodicamente 'trocam de pele', deixando para trás uma capa transparente e fina que reproduz o desenho de suas escamas. Esse processo periódico de troca da camada externa de queratina é chamado de:", "alternativas": {"A": "Metamorfose larval.", "B": "Ecdise (muda).", "C": "Fecundação externa.", "D": "Clonagem epitelial.", "E": "Bioluminescência."}, "resposta_correta": "B", "justificativa": "A ecdise (ou muda epidérmica) consiste no desprendimento periódico do estrato córneo externo queratinizado da epiderme, permitindo o crescimento corporal contínuo e a renovação de escamas desgastadas.", "possui_imagem": false},
  {"id": 82, "uid": "CIEN-7-082", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Diferença entre Tartaruga, Jabuti e Cágado", "dificuldade": "Fácil", "enunciado": "Dentro da ordem dos quelônios (Testudines), o jabuti distingue-se das tartarugas marinhas e dos cágados principalmente por ser um animal:", "alternativas": {"A": "Exclusivamente marinho dotado de nadadeiras em forma de remo.", "B": "Exclusivamente terrestre, com patas grossas e cilíndricas semelhantes a pés de elefante e casco alto e arredondado.", "C": "Voador que se alimenta de morcegos nas cavernas.", "D": "Aquático de água doce que dobra o pescoço lateralmente.", "E": "Sem ossos e sem carapaça rígida."}, "resposta_correta": "B", "justificativa": "Jabutis são quelônios terrestres estritos; apresentam carapaça alta e convexa, patas colunares e unhas grossas adaptadas à caminhada no solo seco, sendo incapazes de nadar.", "possui_imagem": false},
  {"id": 83, "uid": "CIEN-7-083", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Serpentes Peçonhentas e Não Peçonhentas", "dificuldade": "Fácil", "enunciado": "Diferente das serpentes não peçonhentas (que matam suas presas por constrição mecânica, como a jiboia), as serpentes peçonhentas (como jararaca, cascavel e coral-verdadeira) possuem dentes especializados inoculadores chamados de:", "alternativas": {"A": "Molares carnívoros.", "B": "Presas inoculadoras de veneno.", "C": "Dentes incisivos caninos de osso duro.", "D": "Bicos de queratina calcificados.", "E": "Tentáculos mandibulares."}, "resposta_correta": "B", "justificativa": "Serpentes peçonhentas apresentam presas modificadas conectadas a glândulas de veneno (dentição proteróglifa ou solenóglifa), permitindo a injeção ativa de toxinas proteolíticas, hemotóxicas ou neurotóxicas.", "possui_imagem": false},
  {"id": 84, "uid": "CIEN-7-084", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Soros Antiofídicos no Brasil", "dificuldade": "Fácil", "enunciado": "No Brasil, o cientista Vital Brazil fundou o renomado Instituto Butantan em São Paulo, desenvolvendo soros específicos para salvar vidas de pessoas picadas por serpentes venenosas. O soro antiofídico é produzido principalmente a partir de:", "alternativas": {"A": "Plantas medicinais maceradas em álcool puro.", "B": "Anticorpos produzidos no sangue de cavalos que receberam pequenas doses controladas do veneno da serpente.", "C": "Veneno de aranha fervido com bicarbonato de sódio.", "D": "Água mineral enriquecida com queratina marinha.", "E": "Pó de escamas de cascavel moído em laboratório."}, "resposta_correta": "B", "justificativa": "O soro hiperimune é obtido pela inoculação de antígenos (veneno purificado em doses subletais) em cavalos saudáveis; o organismo do animal produz altos títulos de anticorpos específicos, cujo plasma é centrifugado, purificado e padronizado.", "possui_imagem": false},
  {"id": 85, "uid": "CIEN-7-085", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Fluxo Contracorrente nas Brânquias dos Peixes", "dificuldade": "Médio", "enunciado": "Nas brânquias dos peixes, a água flui pelas lamelas em sentido exatamente oposto ao fluxo do sangue dentro dos capilares branquiais (mecanismo de trocas contracorrente). A enorme vantagem fisiológica desse arranjo hidrodinâmico é:", "alternativas": {"A": "Aquecer o sangue do peixe até 40 ºC para evitar o congelamento.", "B": "Manter um gradiente de concentração favorável de gás oxigênio ao longo de toda a extensão do capilar, permitindo extrair até mais de 80% do oxigênio dissolvido na água.", "C": "Impedir que o peixe engula água salgada pela boca.", "D": "Fazer com que o peixe nade mais rápido para trás do que para a frente.", "E": "Transformar a amônia excretada em glicose comestível."}, "resposta_correta": "B", "justificativa": "No sistema de fluxo contracorrente, o sangue que percorre o capilar encontra sucessivamente água com teores ligeiramente mais altos de oxigênio do que o seu próprio sangue, sustentando difusão líquida positiva ao longo de todo o percurso e atingindo eficácia extrativa extraordinária.", "possui_imagem": false},
  {"id": 86, "uid": "CIEN-7-086", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Osmorregulação em Peixes Marinhos vs. Dulcícolas", "dificuldade": "Médio", "enunciado": "Peixes ósseos marinhos vivem em um meio hipertônico em relação aos seus fluidos corporais, correndo o risco constante de perder água por osmose. Para sobreviver a essa condição fisiológica, os peixes marinhos:", "alternativas": {"A": "Nunca bebem água do mar e produzem urina extremamente volumosa e diluída.", "B": "Bebem grandes quantidades de água do mar, eliminam o excesso de sais ativamente pelas brânquias e produzem pouquíssima urina altamente concentrada.", "C": "Absorvem sal pela pele até igualar sua densidade à das rochas do fundo.", "D": "Respiram apenas ar atmosférico subindo à superfície a cada dois minutos.", "E": "Transformam toda a água salgada em gordura subcutânea isolante."}, "resposta_correta": "B", "justificativa": "Para combater a desidratação osmótica na água salgada, teleósteos marinhos ingerem água do mar continuamente, excretam íons monovalentes (Na+ e Cl-) ativamente por células de cloreto branquiais e minimizam o volume urinário renal.", "possui_imagem": false},
  {"id": 87, "uid": "CIEN-7-087", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Circulação Sanguínea dos Peixes", "dificuldade": "Médio", "enunciado": "O sistema circulatório da maioria dos peixes é fechado, simples e completo. O coração dos peixes possui apenas duas cavidades contíguas (um átrio e um ventrículo). No interior do coração de um peixe passa exclusivamente:", "alternativas": {"A": "Sangue arterial ricamente oxigenado que acabou de sair dos pulmões.", "B": "Sangue venoso pobre em oxigênio e rico em gás carbônico, que é bombeado em direção às brânquias para ser oxigenado.", "C": "Uma mistura de sangue venoso e arterial misturada no ventrículo único.", "D": "Água do mar misturada com hemoglobina líquida.", "E": "Linfa pura desprovida de glóbulos vermelhos."}, "resposta_correta": "B", "justificativa": "A circulação dos peixes é simples: o sangue passa apenas uma vez pelo coração a cada circuito corporal. O coração recebe sangue venoso desoxigenado de todo o corpo e o projeta diretamente para o arco aórtico ventral rumo aos capilares branquiais (sangue venoso exclusivo no coração).", "possui_imagem": false},
  {"id": 88, "uid": "CIEN-7-088", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Tubarões: Flutuabilidade sem Bexiga Natatória", "dificuldade": "Médio", "enunciado": "Os tubarões e raias (peixes cartilaginosos) não possuem bexiga natatória. Para não afundarem continuamente no oceano quando param de nadar, eles contam com adaptações como:", "alternativas": {"A": "Um fígado volumoso e repleto de óleos de baixa densidade (esqualeno) e sustentação hidrodinâmica gerada pela forma das nadadeiras peitorais durante a natação contínua.", "B": "Ossos ocos de vidro cheios de gás carbônico comprimido.", "C": "Pulmões rudimentares que acumulam ar respirado na superfície das ondas.", "D": "Pernas articuladas retráteis que se apoiam no leito do mar.", "E": "Cascas calcárias externas flutuantes."}, "resposta_correta": "A", "justificativa": "Os condríctes compensam a ausência de bexiga natatória acumulando grandes estoques de lipídios de baixa densidade (óleo esqualeno) em seu fígado maciço e dependem da sustentação hidrodinâmica dinâmica conferida por suas nadadeiras peitorais rígidas e cauda heterocerca.", "possui_imagem": false},
  {"id": 89, "uid": "CIEN-7-089", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Ampolas de Lorenzini nos Tubarões", "dificuldade": "Médio", "enunciado": "Na região do focinho e da cabeça dos tubarões existem centenas de pequenos poros preenchidos por gel condutor elétrico chamados de 'ampolas de Lorenzini'. Esses órgãos sensoriais altamente especializados permitem ao tubarão:", "alternativas": {"A": "Escutar ultrassons emitidos por morcegos voando acima do mar.", "B": "Detectar campos elétricos minúsculos gerados pela atividade muscular e batimentos cardíacos de presas enterradas na areia do fundo do mar.", "C": "Produzir descargas elétricas mortais de 2.000 volts para eletrocutar presas.", "D": "Medir a temperatura da água com termômetros ópticos de vidro.", "E": "Enxergar em cores perfeitas em cavernas oceânicas de escuridão total."}, "resposta_correta": "B", "justificativa": "As ampolas de Lorenzini são eletrorreceptores de extrema sensibilidade constituídos por canais de glicoproteína condutora, capazes de captar gradientes de campo elétrico de microvolts por centímetro produzidos por contrações neuromusculares de animais marinhos.", "possui_imagem": false},
  {"id": 90, "uid": "CIEN-7-090", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Circulação Dupla e Incompleta nos Anfíbios", "dificuldade": "Médio", "enunciado": "O coração dos anfíbios adultos é tricavitário, sendo formado por dois átrios e um único ventrículo. A consequência anatômica e fisiológica dessa estrutura cardíaca é:", "alternativas": {"A": "A separação de 100% entre o sangue arterial e o venoso dentro do coração.", "B": "A ocorrência de mistura parcial de sangue oxigenado (que veio dos pulmões e pele) com sangue desoxigenado (que veio dos tecidos) dentro do ventrículo único.", "C": "A impossibilidade de o sangue circular pelos membros locomotores.", "D": "O sangue parar de circular sempre que o sapo salta no solo.", "E": "A ausência total de glóbulos vermelhos na circulação."}, "resposta_correta": "B", "justificativa": "Nos anfíbios a circulação é dupla (circuito sistêmico e circuito pulmocutâneo), mas é incompleta porque o ventrículo único não possui septo interventricular completo, ocorrendo coalescência parcial dos fluxos sanguíneos no ápice ventricular.", "possui_imagem": false},
  {"id": 91, "uid": "CIEN-7-091", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Coração dos Répteis e o Septo de Sabatier", "dificuldade": "Médio", "enunciado": "Na maioria dos répteis não crocodilianos (como serpentes e lagartos), o coração apresenta dois átrios e um ventrículo parcialmente dividido por uma parede muscular chamada septo de Sabatier. Esse septo confere aos répteis a vantagem de:", "alternativas": {"A": "Reduzir significativamente a mistura entre sangue venoso e sangue arterial dentro do ventrículo quando comparado aos anfíbios.", "B": "Eliminar completamente o ventrículo e deixar apenas átrios funcionando.", "C": "Bombear água do mar para os pulmões durante mergulhos profundos.", "D": "Substituir o fígado no controle da glicose sanguínea.", "E": "Permitir que o sangue se transforme em veneno nas presas superiores."}, "resposta_correta": "A", "justificativa": "O septo de Sabatier (interventricular parcial) orienta hemodinamicamente os jatos sanguíneos no ventrículo reptiliano, canalizando a maior fração de sangue oxigenado para os arcos aórticos sistêmicos e sangue venoso para a artéria pulmonar, reduzindo expressivamente a mistura de sangues.", "possui_imagem": false},
  {"id": 92, "uid": "CIEN-7-092", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Coração dos Crocodilianos e o Forame de Panizza", "dificuldade": "Médio", "enunciado": "Diferente dos outros répteis, os crocodilianos (jacarés e crocodilos) possuem o coração completamente dividido em quatro cavidades (dois átrios e dois ventrículos separados). No entanto, entre os dois arcos aórticos principais existe uma comunicação direta chamada 'Forame de Panizza'. A função fisiológica dessa abertura durante os longos mergulhos subaquáticos do jacaré é:", "alternativas": {"A": "Fazer o jacaré respirar água líquida pelas narinas.", "B": "Permitir um desvio circulatório (shunt da direita para a esquerda), direcionando o sangue venoso de volta para o corpo sem passar pelos pulmões enquanto o animal não está respirando.", "C": "Aumentar a perda de calor corporal para resfriar a cabeça do jacaré.", "D": "Destruir a hemoglobina para economizar ferro nos tecidos.", "E": "Fazer o coração do animal parar de bater permanentemente."}, "resposta_correta": "B", "justificativa": "Em apneia subaquática prolongada, a vasoconstrição pulmonar eleva a resistência no circuito pulmonar. O Forame de Panizza permite que o sangue do ventrículo direito seja desviado para a aorta sistêmica esquerda (shunt cardíaco), preservando oxigênio e poupando energia.", "possui_imagem": false},
  {"id": 93, "uid": "CIEN-7-093", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Anexos Embrionários: O Alantoide", "dificuldade": "Médio", "enunciado": "No ovo amniótico com casca dos répteis, o anexo embrionário responsável por armazenar as excretas nitrogenadas insolúveis (ácido úrico) produzidas pelo metabolismo do embrião e por participar das trocas gasosas respiratórias em conjunto com o córion é o:", "alternativas": {"A": "Saco vitelínico.", "B": "Alantoide.", "C": "Âmnio.", "D": "Plastrão.", "E": "Opérculo embrionário."}, "resposta_correta": "B", "justificativa": "O alantoide é uma vesícula derivada do intestino posterior embrionário que desempenha papel excretor fundamental ao funcionar como depósito de resíduos de ácido úrico e vasculariza a membrana corioalantoidea responsável pela hematose através dos poros da casca.", "possui_imagem": false},
  {"id": 94, "uid": "CIEN-7-094", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Excreção de Ácido Úrico e Economia Hídrica", "dificuldade": "Médio", "enunciado": "Diferente dos mamíferos (que excretam ureia solúvel em água) e dos peixes de água doce (que excretam amônia tóxica), os répteis e as aves excretam predominantemente ácido úrico pastoso e insolúvel. Essa excreção de ácido úrico representa uma adaptação crucial ao ambiente terrestre porque:", "alternativas": {"A": "O ácido úrico exige um volume mínimo de água para ser eliminado do corpo, permitindo máxima retenção hídrica em habitats secos e possibilitando o desenvolvimento dentro do ovo fechado.", "B": "O ácido úrico atua como combustível que queima parasitas no intestino.", "C": "A substância atrai insetos que servem de alimento aos filhotes no ninho.", "D": "O ácido úrico é um gás leve que ajuda o réptil a saltar distâncias maiores.", "E": "A amônia destruiria o esqueleto de queratina da carapaça."}, "resposta_correta": "A", "justificativa": "O ácido úrico tem baixíssima toxicidade e é praticamente insolúvel em água, precipitando como cristais pastosos brancos. Isso viabiliza o confinamento seguro de excretas no alantoide dentro do ovo fechado e confere extrema economia de água em animais terrestres.", "possui_imagem": false},
  {"id": 95, "uid": "CIEN-7-095", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Fosseta Loreal em Serpentes Peçonhentas", "dificuldade": "Médio", "enunciado": "Serpentes da família dos viperídeos brasileiras, como a jararaca, a cascavel e a surucucu, possuem entre o olho e a narina uma pequena abertura especializada chamada fosseta loreal. Esse orifício abriga um órgão termorreceptor capaz de:", "alternativas": {"A": "Escutar passos de pequenos roedores a quilômetros de distância.", "B": "Detectar variações microscópicas de radiação infravermelha (calor corporal emitido por presas endotérmicas, como roedores e aves), permitindo dar botes certeiros mesmo na escuridão total da noite.", "C": "Injetar veneno à distância como um spray sob alta pressão.", "D": "Respirar debaixo d'água quando a serpente engole presas grandes.", "E": "Emitir luz estroboscópica para hipnotizar pássaros em galhos."}, "resposta_correta": "B", "justificativa": "A fosseta loreal é uma câmara forrada por uma membrana ricamente inervada pelo nervo trigêmeo, sensível a diferenças de temperatura de milésimos de grau Celsius por detecção de radiação térmica infravermelha, viabilizando caça noturna eficiente.", "possui_imagem": false},
  {"id": 96, "uid": "CIEN-7-096", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Diferenciação: Serpente Coral-Verdadeira vs. Falsa", "dificuldade": "Médio", "enunciado": "No Brasil, encontrar serpentes com anéis coloridos de vermelho, preto e branco ou amarelo no corpo exige cautela extrema. Enquanto a coral-falsa não possui presas anteriores de veneno, a coral-verdadeira (gênero Micrurus) é altamente perigosa porque:", "alternativas": {"A": "Mata suas presas exclusivamente por asfixia mecânica em volta do pescoço.", "B": "Possui dentição proteróglifa (presas anteriores fixas) e inocula um veneno neurotóxico potente que bloqueia as sinapses neuromusculares, podendo causar parada respiratória rápida.", "C": "Dispara veneno pelos olhos a até dez metros de distância.", "D": "Possui casco de quelônio em vez de escamas flexíveis.", "E": "Gera choques elétricos semelhantes aos do peixe-elétrico poraquê."}, "resposta_correta": "B", "justificativa": "As corais-verdadeiras pertencem à família Elapidae. Possuem presas inoculadoras pequenas e fixas na região anterior da maxila (proteróglifas) e veneno com neurotoxinas pré e pós-sinápticas que bloqueiam a transmissão colinérgica, paralisando a musculatura diafragmática.", "possui_imagem": false},
  {"id": 97, "uid": "CIEN-7-097", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Declínio Global de Populações de Anfíbios", "dificuldade": "Médio", "enunciado": "Biólogos em todo o mundo têm alertado para o rápido desaparecimento de populações de anfíbios. Devido à sua pele permeável e ao ciclo de vida bifásico (aquático e terrestre), os anfíbios são considerados excelentes 'bioindicadores ecológicos'. As principais causas desse declínio incluem:", "alternativas": {"A": "A poluição de corpos hídricos por pesticidas, a destruição de brejos/florestas e a proliferação do fungo microscópico quitrídio (quitridiomicose), que ataca a pele dos animais.", "B": "O excesso de oxigênio puro gerado pelas florestas tropicais maduras.", "C": "A caça comercial intensiva de sapos para fabricação de tecidos finos.", "D": "A invasão de lagartos herbívoros que comem todas as pedras dos rios.", "E": "A perda da capacidade genética dos sapos de colocar ovos na primavera."}, "resposta_correta": "A", "justificativa": "A sensibilidade dos anfíbios à poluição hídrica e atmosférica decorre de sua absorção cutânea desprotegida. A quitridiomicose (causada pelo fungo Batrachochytrium dendrobatidis) queratiniza e espessa a pele, impedindo a respiração e osmorregulação e dizimando espécies inteiras.", "possui_imagem": false},
  {"id": 98, "uid": "CIEN-7-098", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Ecolocalização vs. Sentidos Químicos: Órgão de Jacobson", "dificuldade": "Médio", "enunciado": "Ao observar uma serpente ou lagarto em repouso, nota-se que o animal coloca a língua bífida para fora repetidas vezes e depois a recolhe para dentro da boca. O objetivo biológico desse comportamento é:", "alternativas": {"A": "Beber umidade do ar para não ter que ir até lagoas de água doce.", "B": "Capturar partículas odoríferas e químicas suspensas no ar e levá-las até o órgão de Jacobson (vomeronasal), localizado no céu da boca, para serem analisadas pelo olfato/paladar.", "C": "Resfriar o sangue da cabeça como um radiador de arrefecimento térmico.", "D": "Espantar mosquitos e moscas que pousam sobre a cabeça da serpente.", "E": "Testar a velocidade do vento antes de rastejar para a frente."}, "resposta_correta": "B", "justificativa": "A língua bífida das serpentes atua como coletora de moléculas químicas voláteis do ambiente. Ao ser retraída, as pontas da língua são introduzidas nas duas aberturas do órgão vomeronasal de Jacobson no palato, cujos neurônios olfatórios transmitem a informação química ao bulbo acessório.", "possui_imagem": false},
  {"id": 99, "uid": "CIEN-7-099", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Respiração nos Répteis: Ausência de Diafragma", "dificuldade": "Médio", "enunciado": "Ao contrário dos anfíbios, que precisam forçar o ar para os pulmões engolindo-o pela boca (bomba de pressão positiva), os répteis aspiram ar para os pulmões através de pressão negativa. Na maioria dos répteis (como lagartos), essa sucção pulmonar é gerada pela:", "alternativas": {"A": "Ação de um músculo diafragma idêntico ao dos seres humanos.", "B": "Contração e movimentação dos músculos das costelas (musculatura intercostal da caixa torácica), expandindo o volume do tronco e reduzindo a pressão interna.", "C": "Contração das escamas de queratina da ponta da cauda.", "D": "Abertura e fechamento das fendas branquiais do pescoço.", "E": "Atração magnética das moléculas de ar pelas carapaças."}, "resposta_correta": "B", "justificativa": "Répteis não possuem músculo diafragma (com exceção de feixes tendíneos nos crocodilianos). A ventilação pulmonar por pressão negativa é realizada ativamente pelos músculos intercostais que movimentam a caixa torácica, expandindo a cavidade celômica.", "possui_imagem": false},
  {"id": 100, "uid": "CIEN-7-100", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Peixes Dipnoicos (Pulmonados)", "dificuldade": "Médio", "enunciado": "A piramboia (Lepidosiren paradoxa) é um peixe nativo das bacias hidrográficas amazônica e do Pantanal que habita águas lodosas com baixíssimo teor de oxigênio. Durante as secas severas, ela se enterra na lama e sobrevive respirando ar atmosférico porque:", "alternativas": {"A": "Desenvolveu pernas articuladas de anfíbio para caçar insetos fora d'água.", "B": "Possui bexiga natatória modificada e ricamente vascularizada que atua como um pulmão verdadeiro (peixe dipnoico), além de brânquias atrofiadas.", "C": "Consegue armazenar gás hélio em sua casca de quitina por meses.", "D": "Realiza fotossíntese celular graças a algas simbiontes nas escamas.", "E": "Não consome oxigênio e não possui células vivas na fase adulta."}, "resposta_correta": "B", "justificativa": "Os dipnoicos (Sarcopterygii) são peixes pulmonados que possuem uma ou duas bexigas natatórias altamente septadas e vascularizadas ligadas à faringe que operam funcionalmente como pulmões, permitindo a respiração aérea facultativa ou obrigatória em corpos de água hipóxicos.", "possui_imagem": false},
  {"id": 101, "uid": "CIEN-7-101", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Cecílias (Cobras-Cegas): Anfíbios Ápodos", "dificuldade": "Médio", "enunciado": "As cecílias (cobras-cegas) são animais serpentiformes e sem patas que vivem enterrados em solos úmidos de florestas tropicais. Embora sejam frequentemente confundidas com cobras (répteis) ou minhocas (anelídeos), elas são classificadas zoológicamente como:", "alternativas": {"A": "Anelídeos hermafroditas de corpo segmentado com cerdas duras.", "B": "Répteis escamados venenosos de sangue quente.", "C": "Anfíbios da ordem Gymnophiona (Apoda), dotados de pele lisa, úmida e glandular, sem escamas externas e sem patas.", "D": "Mamíferos fossoriais que amamentam seus filhotes na terra.", "E": "Peixes ósseos que perderam as brânquias para nadar no barro."}, "resposta_correta": "C", "justificativa": "As cecílias pertencem à ordem Gymnophiona (Apoda) da classe Amphibia. São vertebrados tetrápodes que sofreram perda secundária dos membros locomotores, apresentando crânio ósseo rígido adaptado à escavação e pele glandular úmida típica de anfíbios.", "possui_imagem": false},
  {"id": 102, "uid": "CIEN-7-102", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Escamas Placoides nos Condríctes", "dificuldade": "Médio", "enunciado": "Ao passar a mão no sentido da cauda para a cabeça na pele de um cação ou tubarão, sente-se uma textura extremamente áspera, semelhante a uma lixa de madeira. Essa aspereza deve-se às escamas placoides, cuja estrutura anatômica é microscópica e surpreendentemente homóloga a:", "alternativas": {"A": "Plumas leves de aves voadoras.", "B": "Dentes de vertebrados, apresentando uma base óssea dérmica, dentina interna e uma camada externa brilhante semelhante ao esmalte dentário.", "C": "Pêlos de mamíferos ricos em queratina flexível.", "D": "Cascas de caracol compostas por carbonato de cálcio puro.", "E": "Folhas vegetais mineralizadas por sílica sedimentar."}, "resposta_correta": "B", "justificativa": "As escamas placoides (dentículos dérmicos) dos condríctes têm a mesma origem embriológica e estrutura tecidual que os dentes: polpa conjuntiva central, dentina mineralizada e camada superficial de esmalte vitrificado (esmaltina).", "possui_imagem": false},
  {"id": 103, "uid": "CIEN-7-103", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Determinação do Sexo por Temperatura em Répteis", "dificuldade": "Médio", "enunciado": "Em muitas espécies de tartarugas marinhas e crocodilianos, o sexo dos filhotes que nascerão dos ovos não é determinado por cromossomos sexuais (como X e Y), mas sim por um fator ecológico do ninho. Esse fator é a:", "alternativas": {"A": "Profundidade da água do mar durante a maré alta da desova.", "B": "Temperatura média de incubação da areia ou do monte de folhas onde os ovos foram depositados.", "C": "Quantidade de sal marinho dissolvido na casca do ovo.", "D": "Fase em que a Lua se encontrava na noite do acasalamento.", "E": "Cor das penas da fêmea que chocou os ovos no ninho."}, "resposta_correta": "B", "justificativa": "O mecanismo de Determinação Sexual Dependente da Temperatura (TSD) é comum em Testudines e Crocodylia. Variações de poucos graus na temperatura média do ninho ativam diferencialmente enzimas como a aromatase, induzindo a diferenciação gonadal em machos ou fêmeas.", "possui_imagem": false},
  {"id": 104, "uid": "CIEN-7-104", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Veneno de Serpente: Ação Hemotóxica vs. Neurotóxica", "dificuldade": "Médio", "enunciado": "O veneno da jararaca (Bothrops) possui ação predominantemente proteolítica e coagulante/hemorrágica (hemotóxica), provocando dor intensa, edema e necrose tecidual no local da picada. Já o veneno da cascavel (Crotalus) possui ação predominantemente:", "alternativas": {"A": "Digestiva ácida que queima a pele por fora sem entrar no sangue.", "B": "Neurotóxica e miotóxica, causando paralisia da musculatura facial (fácies miastênica), visão dupla (diplopia) e destruição de fibras musculares que libera mioglobina escurecendo a urina.", "C": "Exclusivamente alérgica, sem nenhum efeito no organismo humano.", "D": "Hormonal estimulante que aumenta os batimentos cardíacos sem dor.", "E": "Sonífera pura sem risco de sequelas ou morte."}, "resposta_correta": "B", "justificativa": "O veneno crotálico contém crotoxina e crotamina, frações com potente toxicidade neurotóxica (bloqueio pré-sináptico da liberação de acetilcolina) e miotóxica (rabdomiólise com liberação massiva de mioglobina que sobrecarrega os rins).", "possui_imagem": false},
  {"id": 105, "uid": "CIEN-7-105", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Pecilotermia e Hibernação / Estivação", "dificuldade": "Médio", "enunciado": "Durante invernos muito rigorosos em regiões temperadas ou em períodos de seca extrema no semiárido, muitos répteis e anfíbios reduzem drasticamente sua atividade metabólica e permanecem em estado de dormência profunda enterrados em fendas ou na lama. Esses comportamentos ecológicos de dormência são chamados, respectivamente, de:", "alternativas": {"A": "Homeotermia e fotossíntese.", "B": "Hibernação (no frio) e estivação (no calor/seca).", "C": "Ecdise e metamorfose.", "D": "Metamorfose e fecundação cruzada.", "E": "Osmorregulação e convecção biológica."}, "resposta_correta": "B", "justificativa": "A hibernação é a dormência metabólica hipometabólica em resposta a baixas temperaturas hibernais. A estivação é a dormência prolongada assumida durante períodos críticos de calor intenso e escassez extrema de água (como em anuros do semiárido).", "possui_imagem": false},
  {"id": 106, "uid": "CIEN-7-106", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Evolução dos Tetrápodes: Do Tiktaalik aos Anfíbios", "dificuldade": "Difícil", "enunciado": "O registro fóssil da transição dos peixes sarcopterígeos para os primeiros tetrápodes no período Devoniano Superior (há cerca de 375 milhões de anos) revelou organismos de transição cruciais como o Tiktaalik roseae e o Acanthostega. A principal novidade anatômica homóloga presente nas nadadeiras lobadas desses peixes fósseis que deu origem aos membros locomotores dos tetrápodes terrestres é:", "alternativas": {"A": "A presença de raios córneos de queratina semelhantes a asas de inseto.", "B": "Um arranjo ósseo endoesquelético proximal com um único osso (homólogo ao úmero), articulado a dois ossos (homólogos ao rádio e ulna), seguido por elementos digitais rudimentares.", "C": "Tentáculos musculares de cartilagem sem nenhuma articulação óssea.", "D": "Garras retráteis de aço de alta resistência mecânica.", "E": "Nadadeiras operculares fundidas à coluna vertebral dorsal."}, "resposta_correta": "B", "justificativa": "A nadadeira lobada dos peixes sarcopterígeos ancestrais apresentava o padrão ósseo quiridiano basal (1 osso proximal -> 2 ossos intermediários -> carpais e dígitos), homologia direta compartilhada por todos os tetrápodes (anfíbios, répteis, aves e mamíferos).", "possui_imagem": false},
  {"id": 107, "uid": "CIEN-7-107", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Bexiga Natatória Fisóstoma vs. Fisóclista", "dificuldade": "Difícil", "enunciado": "Quanto à conexão com o sistema digestório, a bexiga natatória dos peixes ósseos é classificada em 'fisóstoma' ou 'fisóclista'. Em peixes teleósteos fisóclistas mais derivados (como o robalo e a pescada):", "alternativas": {"A": "A bexiga natatória não possui nenhuma conexão física por ducto com o esôfago; as trocas gasosas de enchimento e esvaziamento são feitas estritamente pelo sangue através do corpo vermelho (rete mirabile) e da glândula de gás, e reabsorvidas pelo oval.", "B": "O peixe precisa engolir ar na superfície para encher a bexiga a cada dez minutos.", "C": "A bexiga é preenchida por água do mar pura bombeada pelo ânus.", "D": "O órgão é conectado à boca por um tubo elástico que nunca se fecha.", "E": "A bexiga natatória é eliminada durante a primeira muda de escamas."}, "resposta_correta": "A", "justificativa": "Peixes fisóclistas não possuem o ducto pneumático presente nos fisóstomos basais. O volume gasoso (frequentemente oxigênio a alta pressão) é secretado por multiplicação por contracorrente na rete mirabile e glândula de gás, e reabsorvido na região especializada do oval.", "possui_imagem": false},
  {"id": 108, "uid": "CIEN-7-108", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Células Eletrogênicas do Poraquê (Electrophorus)", "dificuldade": "Difícil", "enunciado": "O poraquê (Electrophorus voltai), peixe elétrico nativo da bacia amazônica, é capaz de desferir descargas elétricas de até 860 volts. Esse choque de alta voltagem é produzido por órgãos elétricos constituídos por milhares de células especializadas derivadas de fibras musculares modificadas chamadas:", "alternativas": {"A": "Eletrócitos, dispostos em série como uma bateria eletroquímica gigante.", "B": "Neurônios de mielina pura sem axônios condutores.", "C": "Bastonetes oculares de alta sensibilidade noturna.", "D": "Células da glia que armazenam ácido sulfúrico concentrado.", "E": "Papilas gustativas que explodem ao tocar na água doce."}, "resposta_correta": "A", "justificativa": "Os órgãos elétricos dos gimnotiformes são constituídos por placas de eletrócitos orientadas paralelamente em colunas em série; a estimulação colinérgica coordenada deflagra a despolarização assimétrica de suas membranas, somando os potenciais de membrana até atingir centenas de volts.", "possui_imagem": false},
  {"id": 109, "uid": "CIEN-7-109", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Mecanismo Osmorregulatório dos Condríctes: Retenção de Ureia", "dificuldade": "Difícil", "enunciado": "Diferente dos peixes ósseos marinhos que bebem água do mar e eliminam sais ativamente para combater a desidratação, os tubarões e raias marinhos não sofrem perda osmótica de água para o oceano. A estratégia bioquímica ímpar utilizada pelos condríctes para manter seus fluidos corporais ligeiramente hipertônicos (ou isosmóticos) em relação à água do mar é:", "alternativas": {"A": "Reter e acumular altas concentrações de ureia e óxido de trimetilamina (TMAO) no sangue e nos tecidos musculares.", "B": "Transformar toda a água salgada em pedras de calcário eliminadas na cloaca.", "C": "Absorver oxigênio através de uma carapaça de gordura impermeável a sais.", "D": "Beber 500 litros de água destilada que eles produzem no estômago.", "E": "Parar a circulação sanguínea durante as marés de água salgada."}, "resposta_correta": "A", "justificativa": "Os elasmobrânquios marinhos são osmorreguladores uremotélicos: acumulam grandes concentrações de solutos orgânicos (ureia e TMAO estabilizador de proteínas) no plasma sanguíneo, elevando sua osmolaridade acima da osmolaridade da água do mar, o que promove influxo osmótico passivo de água pelas brânquias.", "possui_imagem": false},
  {"id": 110, "uid": "CIEN-7-110", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Morfologia e Fisiologia do Coração Reptiliano Crocodiliano", "dificuldade": "Difícil", "enunciado": "O sistema cardiovascular dos crocodilianos apresenta o mais complexo arranjo anatômico entre os répteis: quatro câmaras cardíacas completas, artéria aorta direita saindo do ventrículo esquerdo e artéria aorta esquerda saindo do ventrículo direito. A função adaptativa do desvio de sangue desoxigenado (rico em CO2) pela aorta esquerda para o trato gastrointestinal após grandes refeições carnívoras é:", "alternativas": {"A": "Impedir que a carne apodreça no estômago do jacaré.", "B": "Fornecer grandes quantidades de CO2 diretamente à mucosa gástrica, que o utiliza como substrato enzimático para sintetizar e secretar massivas quantidades de ácido clorídrico (HCl), acelerando a digestão química de ossos, carapaças e carne densa de suas presas.", "C": "Resfriar o fígado do crocodilo durante a digestão noturna.", "D": "Neutralizar o veneno de serpentes que o crocodilo tenha engolido vivas.", "E": "Transformar o sangue do estômago em veneno neurotóxico."}, "resposta_correta": "B", "justificativa": "O shunt vascular fisiológico pós-prandial desvia sangue venoso hipercapnico (com alta pCO2) para a circulação celíaca do estômago. A alta disponibilidade de CO2 acelera a ação da anidrase carbônica gástrica, maximizando a secreção de ácido clorídrico para dissolver ossos inteiros de presas.", "possui_imagem": false},
  {"id": 111, "uid": "CIEN-7-111", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Crânio Cinético dos Squamata e Ingestão de Grandes Presas", "dificuldade": "Difícil", "enunciado": "As serpentes são capazes de engolir presas inteiras cujo diâmetro é várias vezes superior à sua própria cabeça (como um bezerro ou capivara inteira por uma sucuri). Essa extraordinária capacidade mecânica é possibilitada pelo chamado 'crânio cinético', cujas características anatômicas incluem:", "alternativas": {"A": "A quebra proposital de todos os ossos do crânio da serpente a cada refeição.", "B": "Articulações móveis entre os ossos do crânio, osso quadrado altamente móvel e flexível, e a mandíbula inferior dividida em duas metades independentes unidas na frente apenas por um ligamento muscular altamente elástico, permitindo abertura angular e lateral gigantesca.", "C": "A ausência total de ossos na cabeça, sendo o crânio composto apenas por borracha biológica.", "D": "Dentes molares que trituram a presa em pequenos pedaços de 1 mm antes de engolir.", "E": "Uma boca circular com ventosas musculares semelhantes às das sanguessugas."}, "resposta_correta": "B", "justificativa": "O crânio streptostílico das serpentes possui hipercinesia: o osso quadrado atua como uma alavanca de duplo pivô e as hemimandíbulas esquerda e direita não se fundem na sínfise mentoniana, ligando-se por tecido elástico conjuntivo e movendo-se de forma alternada e independente para engolir presas volumosas.", "possui_imagem": false},
  {"id": 112, "uid": "CIEN-7-112", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Fisiologia da Respiração Cutânea em Anfíbios sem Pulmão", "dificuldade": "Difícil", "enunciado": "Todas as salamandras pertencentes à família Plethodontidae (que inclui mais da metade de todas as espécies de salamandras do planeta) são completamente desprovidas de pulmões durante toda a vida adulta. A respiração desses animais adultos é mantida exclusivamente por:", "alternativas": {"A": "Brânquias operculadas que permanecem funcionais na terra seca.", "B": "Trocas gasosas através da pele fina e ricamente vascularizada (respiração cutânea) e pela mucosa interna altamente vascularizada da cavidade bucal (respiração bucofaríngea).", "C": "Fígado e baço que captam gás oxigênio de minhocas ingeridas.", "D": "Espiráculos semelhantes aos dos insetos abertos no abdômen.", "E": "Glicólise anaeróbia perpétua sem consumo de oxigênio gasoso."}, "resposta_correta": "B", "justificativa": "Os pletodontídeos realizaram a perda evolutiva secundária dos pulmões; a hematose é mantida integralmente pela pele glandular úmida e pela mucosa orofaríngea mediante ventilação por bombeamento gular bucal, exigindo habitats terrestres frios e saturados de umidade.", "possui_imagem": false},
  {"id": 113, "uid": "CIEN-7-113", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Excreção Nitrogenada no Ciclo de Vida dos Anfíbios", "dificuldade": "Difícil", "enunciado": "Ao longo de sua metamorfose, um anfíbio anuro como o sapo-cururu altera radicalmente não apenas sua anatomia respiratória, mas também suas vias metabólicas de excreção nitrogenada. Durante a fase de girino aquático e durante a fase adulta terrestre, as principais excretas nitrogenadas eliminadas são, respectivamente:", "alternativas": {"A": "Ácido úrico na fase de girino e amônia na fase adulta.", "B": "Amônia (amoniotelismo na água, altamente solúvel e tóxica) e Ureia (ureotelismo no adulto terrestre, que demanda menor volume hídrico para ser excretada).", "C": "Ureia na fase aquática e glicose sólida na fase terrestre.", "D": "Oxigênio líquido na larva e gás carbônico puro no adulto.", "E": "Proteínas plasmáticas intactas em ambas as fases da vida."}, "resposta_correta": "B", "justificativa": "Como girino que dispõe de abundância hídrica, a excreção de amônia consome pouca energia metabólica por difusão branquial direta. Na transição para a terra firme, enzimas do ciclo da ornitina-ureia hepáticas são induzidas, passando o animal adulto a excretar ureia para economizar água.", "possui_imagem": false},
  {"id": 114, "uid": "CIEN-7-114", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Mimetismo Batesiano: Coral-Verdadeira e Coral-Falsa", "dificuldade": "Difícil", "enunciado": "O padrão cromático de anéis brilhantes e alternados de vermelho, preto e branco/amarelo presente em serpentes corais é um clássico exemplo de coloração de advertência (aposematismo). Quando uma serpente não peçonhenta da família Colubridae (coral-falsa) apresenta coloração e comportamento muito semelhantes aos da venenosa coral-verdadeira (Elapidae), esse fenômeno ecológico evolutivo é denominado:", "alternativas": {"A": "Mimetismo Mülleriano.", "B": "Mimetismo Batesiano, no qual uma espécie inofensiva simula os sinais de advertência de uma espécie nociva ou venenosa para usufruir da proteção contra predadores que aprenderam a evitar o modelo.", "C": "Camuflagem criocromática de neve.", "D": "Comensalismo alimentar parasitário.", "E": "Competição intraespecífica predatória."}, "resposta_correta": "B", "justificativa": "No mimetismo batesiano, a espécie mímica (palatável ou inofensiva) imita a morfologia aposemática de uma espécie modelo (tóxica ou perigosa). Predadores que associaram o padrão de cores a experiências nocivas evitam atacar ambos os animais.", "possui_imagem": false},
  {"id": 115, "uid": "CIEN-7-115", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Ação Anticoagulante e Proteolítica do Veneno Bothrópico", "dificuldade": "Difícil", "enunciado": "O envenenamento botrópico (provocado por jararacas e jararacuçus) é responsável por mais de 85% dos acidentes ofídicos registrados no Brasil. O veneno dessa serpente contém metaloproteinases, serinoproteases e fosfolipases A2. A ação fisiopatológica conjunta dessas toxinas no organismo da vítima caracteriza-se por:", "alternativas": {"A": "Paralisia dos músculos dos olhos sem nenhuma dor no local.", "B": "Destruição celular local intensa (mionecrose, dor em queimação e bolhas hemorrágicas) associada ao consumo desenfreado de fibrinogênio no sangue, tornando o sangue incoagulável e provocando hemorragias sistêmicas graves (gengivorragia, hematúria).", "C": "Aumento súbito da coagulação do sangue que transforma o coração em pedra em 10 segundos.", "D": "Perda imediata de todos os ossos da perna picada.", "E": "Ausência total de qualquer reação inflamatória ou dor no local afetado."}, "resposta_correta": "B", "justificativa": "O veneno botrópico possui tripé fisiopatológico: 1) Ação proteolítica/inflamatória (metaloproteinases que degradam matriz extracelular, causando necrose tecidual); 2) Ação coagulante sobre protrombina/fibrinogênio (afibrinogenemia de consumo e sangue incoagulável); 3) Ação hemorrágica direta (hemorraginas que rompem endotélio capilar).", "possui_imagem": false},
  {"id": 116, "uid": "CIEN-7-116", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Regulação Fisiológica da Flutuabilidade nos Teleósteos", "dificuldade": "Difícil", "enunciado": "Em peixes teleósteos fisóclistas que nadam em profundidades de 50 metros ou mais sob pressões hidrostáticas de 6 atmosferas ou superiores, o sangue precisa secretar gás oxigênio puro para dentro da bexiga natatória contra um gradiente de pressão gasosa imenso. O mecanismo biofísico que força a hemoglobina a liberar oxigênio para a glândula de gás nessas condições extremas baseia-se em:", "alternativas": {"A": "Aumento do oxigênio atmosférico que o peixe engole na superfície.", "B": "Acidificação do sangue na rete mirabile por secreção de ácido lático e CO2, disparando o Efeito Root (uma queda dramática na capacidade máxima de fixação de oxigênio pela hemoglobina induzida pelo pH ácido) e o Efeito Bohr, forçando a liberação do O2 para a bexiga.", "C": "Congelamento instantâneo do sangue do peixe no fundo do oceano.", "D": "Eliminação de todo o sangue para o mar através do ânus.", "E": "Transformação da água salgada em oxigênio puro por fotossíntese estomacal."}, "resposta_correta": "B", "justificativa": "O Efeito Root (característico de peixes) difere do Bohr clássico porque não apenas diminui a afinidade, mas reduz a capacidade total de saturação da hemoglobina sob pH baixo gerado por ácido láctico da glândula de gás, forçando a liberação de oxigênio contra altíssimas pressões parciais.", "possui_imagem": false},
  {"id": 117, "uid": "CIEN-7-117", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Fisiologia dos Peixes Anádromos e Catádromos", "dificuldade": "Difícil", "enunciado": "Espécies como o salmão nascem em rios de água doce, migram para viver nos oceanos de água salgada e retornam aos rios de origem para se reproduzir (peixes anádromos). Já espécies como a enguia realizam o caminho inverso (peixes catádromos). A capacidade desses peixes de transitar entre ambientes de salinidades tão contrastantes (peixes eurialinos) depende de:", "alternativas": {"A": "Mudar a cor de suas escamas de branco para preto a cada maré.", "B": "Inversão fisiológica completa no transporte de íons pelas brânquias (as bombas de cloreto passam de absorver ativamente sais na água doce para secretar ativamente sais na água salgada) e readequação do volume urinário e do hábito de beber água, reguladas por hormônios como prolactina e cortisol.", "C": "Trocar os ossos de seu esqueleto por cartilagem elástica durante a viagem.", "D": "Parar de respirar por brânquias e passar a respirar por pulmões na água do mar.", "E": "Dormir no fundo do mar por cinco anos para se adaptar ao sal."}, "resposta_correta": "B", "justificativa": "Peixes eurialinos sofrem remodelação morfológica e molecular sob controle endócrino: no mar secretam ativamente íons pelas células ricas em mitocôndrias (células de cloreto) e ingerem água produzindo pouca urina; na água doce invertem a polaridade das bombas para reter íons ativamente e excretam urina farta e hipotônica.", "possui_imagem": false},
  {"id": 118, "uid": "CIEN-7-118", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Classificação Filogenética dos Répteis e a Condição Diapsida", "dificuldade": "Difícil", "enunciado": "Na sistemática filogenética moderna, os répteis tradicionais formam um grupo parafilético se as aves não forem incluídas. O crânio dos répteis verdadeiros (incluindo dinossauros, crocodilos, serpentes, lagartos e aves) é caracterizado ancestralmente pela presença de duas aberturas temporais de cada lado atrás da órbita ocular, condição craniana denominada:", "alternativas": {"A": "Anapsida (crânio sem fossas temporais, típico de peixes primitivos).", "B": "Diapsida (duas fossas temporais que conferem inserção eficiente aos músculos mastigadores).", "C": "Synapsida (uma única fossa temporal inferior, linhagem que originou os mamíferos).", "D": "Euryapsida pura marinha fóssil.", "E": "Acraniata pura sem mandíbula."}, "resposta_correta": "B", "justificativa": "Os répteis e as aves constituem o clado Diapsida, caracterizado fundamentalmente por duas fenestras temporais (superior e inferior) no crânio, conferindo leveza óssea e ancoragem otimizada para potente musculatura adutora mandibular.", "possui_imagem": false},
  {"id": 119, "uid": "CIEN-7-119", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Glândulas de Sal em Répteis Marinhos", "dificuldade": "Difícil", "enunciado": "Iguanas-marinhas das Ilhas Galápagos alimentam-se de algas subaquáticas e ingerem grandes volumes de água do mar salgada. Como os rins dos répteis não possuem alça de Henle e não conseguem produzir urina mais concentrada que o próprio sangue, a eliminação do excesso de sal que entra no corpo é realizada por:", "alternativas": {"A": "Transpiração através de poros na carapaça.", "B": "Glândulas de sal especializadas localizadas acima dos olhos ou nasais, que secretam ativamente uma solução salina hipersaturada espirrada pelas narinas.", "C": "Armazenamento de sal dentro dos ossos da cauda até a morte do animal.", "D": "Destruição do cloreto de sódio em átomos de oxigênio pelo estômago.", "E": "Eliminação contínua de escamas de sal pelas pernas."}, "resposta_correta": "B", "justificativa": "Répteis marinhos (iguanas marinhas, serpentes marinhas, tartarugas marinhas e crocodilos de água salgada) utilizam glândulas extra-renais de sal (glândulas nasais, lacrimais ou sublinguais) dotadas de bombas de Na+/K+-ATPase que produzem fluidos até duas vezes mais concentrados em sais do que a própria água do mar.", "possui_imagem": false},
  {"id": 120, "uid": "CIEN-7-120", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Dentição em Serpentes: Proteróglifa vs. Solenóglifa", "dificuldade": "Difícil", "enunciado": "A evolução das serpentes peçonhentas desenvolveu dois sistemas anatômicos avançados de inoculação de veneno: o sistema proteróglifo e o sistema solenóglifo. A diferença anatômica crucial entre as presas de uma coral-verdadeira (proteróglifa) e as de uma jararaca ou cascavel (solenóglifa) é:", "alternativas": {"A": "As corais possuem presas dobráveis de 5 cm de comprimento; as jararacas possuem dentes moles sem canal de veneno.", "B": "As proteróglifas possuem presas anteriores relativamente pequenas e fixas (eretas) com sulco de veneno; as solenóglifas possuem presas ocas tubulares muito longas, curvadas e retráteis articuladas no osso maxilar móvel, que se projetam para a frente a até 90º apenas no momento do bote.", "C": "Ambas as espécies possuem dentes de osso que quebram na presa sem injetar nada.", "D": "As solenóglifas não possuem veneno e usam as presas apenas para mastigar folhas.", "E": "As proteróglifas injetam veneno através do ânus na ponta da cauda."}, "resposta_correta": "B", "justificativa": "A dentição solenóglifa (Viperidae) é o ápice biomecânico ofídico: o maxilar encurtado gira em torno do pré-frontal, permitindo recolher presas longas e recurvadas contra o palato quando a boca se fecha e projetá-las em ângulo reto para injeção intramuscular profunda durante o bote.", "possui_imagem": false},
  {"id": 121, "uid": "CIEN-7-121", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Respiração e Termorregulação na Piracema", "dificuldade": "Difícil", "enunciado": "Durante a época da reprodução, muitas espécies de peixes neotropicais de água doce (como o dourado, o curimbatá e o pintado) realizam a 'piracema', nadando centenas de quilômetros contra a correnteza dos rios para desovar nas cabeceiras. O esforço muscular hercúleo desses peixes durante a subida do rio demanda:", "alternativas": {"A": "Menor consumo de oxigênio e parada temporária dos batimentos cardíacos.", "B": "Aumento maciço do consumo de oxigênio e da circulação branquial, mobilização de reservas de glicogênio e gordura estocadas nos músculos vermelhos aeróbicos, dependendo da vazão e oxigenação natural dos rios livres sem barragens.", "C": "A substituição das brânquias por pulmões de réptil durante a viagem.", "D": "O consumo de 100 kg de carvão mineral por dia encontrado nas pedras.", "E": "A transformação dos machos em fêmeas após a primeira cachoeira."}, "resposta_correta": "B", "justificativa": "A migração reprodutiva reofílica da piracema mobiliza extensas reservas lipídicas e exige máxima taxa metabólica aeróbica suportada pela hematose branquial. Barragens e barramentos hidrelétricos sem passagens funcionais fragmentam o habitat e impedem a chegada às áreas lóticas ideais de desova.", "possui_imagem": false},
  {"id": 122, "uid": "CIEN-7-122", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "O Fígado e a Respiração Cutânea no Ciclo de Vida do Sapinho-Pingo-de-Ouro", "dificuldade": "Difícil", "enunciado": "Pequenos sapos da Mata Atlântica brasileira conhecidos como 'sapinhos-pingo-de-ouro' (gênero Brachycephalus) possuem coloração aposemática laranja/amarela brilhante e medem menos de 1,5 cm. Esses animais exibem tetrodotoxina (TTX) potente na pele e apresentam 'desenvolvimento direto'. O desenvolvimento direto significa que:", "alternativas": {"A": "Os sapinhos nascem como girinos aquáticos que nadam em rios por dez anos.", "B": "Eles não possuem fase de girino aquático de vida livre; o desenvolvimento embrionário e a metamorfose ocorrem inteiramente dentro do ovo protegido no folhiço úmido da floresta, do qual já eclode uma miniatura do sapo adulto completamente formado.", "C": "Eles nascem como répteis escamados e depois viram anfíbios.", "D": "Os ovos são chocados no ninho de aves predadoras.", "E": "Eles se reproduzem apenas por clonagem vegetal sem ovos."}, "resposta_correta": "B", "justificativa": "O desenvolvimento direto (ausência de fase larval aquática livre) é uma especialização adaptativa em anfíbios de florestas úmidas: os ovos ricos em vitelo são depositados no microclima úmido da serapilheira e os estágios larvais são concluídos intraovularmente, eclodindo juvenis já metamorfoseados.", "possui_imagem": false},
  {"id": 123, "uid": "CIEN-7-123", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Efeito da Acidificação das Águas em Ovos de Anfíbios", "dificuldade": "Difícil", "enunciado": "A poluição atmosférica e a chuva ácida provocam a queda do pH das águas de lagoas e poças para valores abaixo de 4,5. Em experimentos laboratoriais de ecotoxicologia, constatou-se que a água ácida causa elevada mortalidade e deformidades graves em embriões de anuros. A causa bioquímica direta desse impacto é:", "alternativas": {"A": "A água ácida queima os ossos do sapo adulto instantaneamente.", "B": "A inibição da enzima eclosina (hatching enzyme) secretada pelo embrião para dissolver a membrana gelatinosa do ovo, além da interrupção da osmorregulação e transporte ativo de íons sódio e cálcio essenciais para o desenvolvimento dos órgãos embrionários.", "C": "A transformação dos girinos em peixes pulmonados marinhos.", "D": "O congelamento imediato da água em pleno verão tropical.", "E": "A falta total de luz solar dentro das lagoas ácidas."}, "resposta_correta": "B", "justificativa": "O pH ácido inativa a eclosina (protease de eclosão), aprisionando o embrião dentro de uma matriz gelatinosa rígida e opaca, e perturba as ATPases de transporte iônico transmembrana, induzindo desequilíbrios osmóticos letais e teratogênese esquelética.", "possui_imagem": false},
  {"id": 124, "uid": "CIEN-7-124", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Fisiologia dos Répteis e Mecanismo de Termorregulação Comportamental", "dificuldade": "Difícil", "enunciado": "Lagartos de deserto e de ambientes campestres conseguem manter sua temperatura corporal notavelmente estável durante o dia (frequentemente entre 35 ºC e 38 ºC) mesmo sendo ectotérmicos estritos. Essa proeza termorregulatória é alcançada através de:", "alternativas": {"A": "Produção contínua de calor por queima de tecido adiposo marrom no fígado.", "B": "Termorregulação comportamental refinada: alternam períodos de heliotermia (tomar sol em rochas perpendiculares aos raios pela manhã), mudam a orientação do corpo em relação ao sol, alteram a cor da pele (escurecendo para absorver calor ou clareando para refletir) e buscam tocas sombreadas nas horas mais quentes do dia.", "C": "Congelamento intencional dos batimentos cardíacos ao meio-dia.", "D": "Transpiração abundante por glândulas sudoríparas espalhadas pelas escamas.", "E": "Beber água fervida do solo para aquecer os órgãos internos."}, "resposta_correta": "B", "justificativa": "Os ectotérmicos utilizam a heliotermia comportamental: ajustam o alinhamento corporal relativo aos raios solares, controlam a vasodilatação cutânea periférica para transferir calor para o núcleo corporal e selecionam micro-habitats térmicos com precisão para sustentar sua temperatura ótima de atividade enzimática.", "possui_imagem": false},
  {"id": 125, "uid": "CIEN-7-125", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Origem da Notocorda e Folhetos Embrionários nos Cordados", "dificuldade": "Difícil", "enunciado": "Na embriologia comparada dos cordados vertebrados, a notocorda origina-se durante o processo de gastrulação e neurulação a partir de qual folheto embrionário primitivo?", "alternativas": {"A": "Ectoderme neural superficial.", "B": "Mesoderme cordal (mesoderma axial).", "C": "Endoderme arquentérica ventral.", "D": "Crista neural epidérmica.", "E": "Folheto amniótico da casca."}, "resposta_correta": "B", "justificativa": "A notocorda diferencia-se a partir do mesoderma axial (mesoderma cordal) que se invagina pelo lábio dorsal do blastóporo (organizador de Spemann-Mangold) e induz a ectoderme sobrejacente a se diferenciar na placa e tubo neural dorsal.", "possui_imagem": false},
  {"id": 126, "uid": "CIEN-7-126", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 16: Cordados Vertebrados I: Peixes, Anfíbios e Répteis", "tema": "Circulação e Excreção em Chondrichthyes: Glândula Retal", "dificuldade": "Difícil", "enunciado": "No sistema excretor e osmorregulador dos tubarões e raias existe um órgão glandular tubular associado ao reto chamado 'glândula retal' (ou glândula de sal dos elasmobrânquios). A função vital dessa glândula é:", "alternativas": {"A": "Produzir enzimas para digerir conchas de moluscos marinhos.", "B": "Secretar ativamente uma solução líquida concentrada de cloreto de sódio (NaCl) para o interior do lúmen intestinal, auxiliando os rins na eliminação do excesso de sal que penetra no corpo pelas brânquias e pela alimentação carnívora.", "C": "Produzir fezes em forma de esferas de calcário impermeável.", "D": "Armazenar espermatozoides durante a cópula reprodutiva.", "E": "Bombear sangue oxigenado para as nadadeiras pélvicas."}, "resposta_correta": "B", "justificativa": "A glândula retal dos condríctes é um órgão osmorregulador acessório rico em transportadores NKCC2 e bombas de Na+/K+-ATPase que excreta ativamente fluido isotônico com altíssima concentração de NaCl diretamente no reto, aliviando a carga excretora renal.", "possui_imagem": false},
  {"id": 127, "uid": "CIEN-7-127", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Características Exclusivas das Aves: Penas", "dificuldade": "Fácil", "enunciado": "As penas são estruturas corporais exclusivas das aves. Entre as funções vitais desempenhadas pelas penas no dia a dia desses animais, destacam-se:", "alternativas": {"A": "A condução de eletricidade estática para aquecer os ovos no ninho.", "B": "A sustentação aerodinâmica para o voo e o isolamento térmico eficiente contra o frio.", "C": "A respiração cutânea substituindo os pulmões durante mergulhos.", "D": "A mastigação mecânica de sementes e grãos duros no papo.", "E": "A excreção de ureia líquida acumulada nos tecidos corporais."}, "resposta_correta": "B", "justificativa": "As penas de queratina desempenham duplo papel biofísico: formam a superfície aerodinâmica alar que gera sustentação no voo e criam uma camada de ar imóvel isolante que retém o calor metabólico.", "possui_imagem": true},
  {"id": 128, "uid": "CIEN-7-128", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Homeotermia / Endotermia nas Aves e Mamíferos", "dificuldade": "Fácil", "enunciado": "Diferente dos peixes, anfíbios e répteis (que são ectotérmicos), as aves e os mamíferos são animais endotérmicos (homeotérmicos). Isso significa que eles:", "alternativas": {"A": "Têm a temperatura do corpo sempre igual à temperatura da água onde nadam.", "B": "São capazes de produzir calor através de seu próprio metabolismo interno, mantendo a temperatura corporal relativamente constante mesmo em ambientes frios.", "C": "Não possuem vasos sanguíneos nem circulação de sangue no inverno.", "D": "Necessitam ficar parados sob o sol o dia inteiro para conseguir andar.", "E": "Respiram por brânquias quando a temperatura cai abaixo de zero grau."}, "resposta_correta": "B", "justificativa": "A endotermia consiste na capacidade de gerar e regular calor corporal a partir de reações metabólicas internas, permitindo taxa de atividade contínua independente das flutuações térmicas ambientais.", "possui_imagem": true},
  {"id": 129, "uid": "CIEN-7-129", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Adaptações das Aves ao Voo: Ossos Pneumáticos", "dificuldade": "Fácil", "enunciado": "O esqueleto das aves que voam apresenta ossos com cavidades internas cheias de ar, chamados de ossos pneumáticos. A principal vantagem adaptativa desses ossos é:", "alternativas": {"A": "Tornar o esqueleto mais pesado para que o vento não leve a ave para longe.", "B": "Reduzir o peso total do corpo da ave sem perder resistência mecânica, facilitando o voo.", "C": "Armazenar água mineral para longas migrações pelo deserto.", "D": "Produzir som de canto como uma flauta de bambu.", "E": "Substituir os músculos das pernas durante a corrida na terra."}, "resposta_correta": "B", "justificativa": "Os ossos pneumáticos possuem trabéculas ósseas internas que conferem grande rigidez mecânica com baixíssima massa específica, reduzindo a carga alar exigida para a decolagem e sustentação no ar.", "possui_imagem": true},
  {"id": 130, "uid": "CIEN-7-130", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Esqueleto das Aves: Quilha ou Carena", "dificuldade": "Fácil", "enunciado": "No esqueleto de aves voadoras (como pombos, gaivotas e falcões), o osso esterno apresenta uma projeção óssea proeminente em forma de quilha de navio (carena). A função dessa estrutura é:", "alternativas": {"A": "Proteger a ave contra a picada de serpentes no chão.", "B": "Servir de ponto de fixação para os potentes músculos peitorais responsáveis pelo bater das asas no voo.", "C": "Armazenar sementes mastigadas antes da digestão.", "D": "Substituir o bico na captura de peixes na água.", "E": "Aumentar o atrito com o ar para frear a ave na descida."}, "resposta_correta": "B", "justificativa": "A quilha (carena) do esterno fornece ampla área de ancoragem esquelética para os robustos músculos peitorais maior e supracoracoídeo, que realizam a depressão e elevação das asas no voo batido.", "possui_imagem": true},
  {"id": 131, "uid": "CIEN-7-131", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Sistema Digestório das Aves: Moela", "dificuldade": "Fácil", "enunciado": "Como as aves não possuem dentes na boca para mastigar o alimento, elas engolem os grãos inteiros. A trituração mecânica do alimento é realizada no estômago mecânico, um órgão com paredes musculares grossas e resistentes chamado:", "alternativas": {"A": "Papo.", "B": "Moela.", "C": "Proventrículo.", "D": "Cloaca.", "E": "Saco aéreo."}, "resposta_correta": "B", "justificativa": "A moela (ventrículo gástrico) possui musculatura espessa e mucosa queratinizada (camada de coilina). Com o auxílio de pequenas pedrinhas (gastrólitos) ingeridas pela ave, a moela mói eficientemente sementes e grãos duros.", "possui_imagem": true},
  {"id": 132, "uid": "CIEN-7-132", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Ausência de Bexiga Urinária nas Aves", "dificuldade": "Fácil", "enunciado": "Entre as adaptações que diminuem a massa corporal das aves para viabilizar o voo, destaca-se uma modificação no sistema excretor, que é a:", "alternativas": {"A": "Eliminação de rins da circulação sanguínea.", "B": "Ausência de bexiga urinária, com eliminação direta e frequente de ácido úrico pastoso junto com as fezes pela cloaca.", "C": "Produção de 10 litros de urina líquida a cada voo.", "D": "Transformação da urina em penas no rabo da ave.", "E": "Armazenamento de urina nos ossos das asas."}, "resposta_correta": "B", "justificativa": "A inexistência de bexiga urinária impede o acúmulo de peso morto de líquido no interior da cavidade corporal; as aves eliminam continuamente ácido úrico pastoso e esbranquiçado através da cloaca.", "possui_imagem": true},
  {"id": 133, "uid": "CIEN-7-133", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula Uropigiana", "dificuldade": "Fácil", "enunciado": "Ao observar patos e marrecos nadando em lagoas, nota-se que suas penas não encharcam e o animal não afunda. As aves impermeabilizam suas penas retirando uma secreção oleosa com o bico a partir de uma glândula localizada na base da cauda, chamada:", "alternativas": {"A": "Glândula sudorípara dorsal.", "B": "Glândula uropigiana.", "C": "Glândula mamária caudal.", "D": "Glândula salivar de ninho.", "E": "Glândula paratóide de pena."}, "resposta_correta": "B", "justificativa": "A glândula uropigiana situa-se sobre as vértebras caudais; a ave esfrega o bico na glândula e espalha a secreção lipídica hidrofóbica sobre a plumagem, repelindo a água e conservando a flutuabilidade e o isolamento térmico.", "possui_imagem": true},
  {"id": 134, "uid": "CIEN-7-134", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Características Diagnósticas dos Mamíferos: Leite", "dificuldade": "Fácil", "enunciado": "A característica biológica exclusiva que dá nome à classe dos Mamíferos (Mammalia) e que está presente em todas as fêmeas dessa classe é a presença de:", "alternativas": {"A": "Penas de voo nos membros anteriores.", "B": "Glândulas mamárias funcionais que produzem leite para a alimentação e nutrição dos filhotes.", "C": "Bicos com dentes de osso para mastigação de grama.", "D": "Cascas calcárias rígidas ao redor do corpo adulto.", "E": "Brânquias operculadas no pescoço dos jovens."}, "resposta_correta": "B", "justificativa": "As glândulas mamárias produtoras de secreção láctea rica em proteínas, lipídios, carboidratos e anticorpos são apomorfia diagnóstica definidora da classe Mammalia.", "possui_imagem": true},
  {"id": 135, "uid": "CIEN-7-135", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Pelos nos Mamíferos", "dificuldade": "Fácil", "enunciado": "Os pelos são estruturas dérmicas e epidérmicas exclusivas dos mamíferos compostas por queratina. A função primordial dos pelos para a sobrevivência desses animais é:", "alternativas": {"A": "Fazer o animal voar mais rápido do que as aves no céu.", "B": "Isolamento térmico, evitando a perda excessiva de calor corporal para o ambiente externo.", "C": "Absorver água líquida da chuva para matar a sede do animal.", "D": "Trocar gases respiratórios de oxigênio pela pele como nos anfíbios.", "E": "Produzir leite para os filhotes na ponta da cauda."}, "resposta_correta": "B", "justificativa": "A pelagem retém uma camada isolante de ar junto à epiderme, reduzindo a condutividade térmica e permitindo que os mamíferos mantenham sua homeotermia com menor gasto energético.", "possui_imagem": true},
  {"id": 136, "uid": "CIEN-7-136", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Músculo Diafragma", "dificuldade": "Fácil", "enunciado": "No corpo dos seres humanos e de todos os outros mamíferos, existe um músculo estriado em forma de cúpula que separa a cavidade torácica da abdominal e atua ativamente na respiração pulmonar. Esse músculo exclusivo dos mamíferos é o:", "alternativas": {"A": "Bíceps braquial.", "B": "Diafragma.", "C": "Tendão de Aquiles.", "D": "Esterno carenado.", "E": "Miócito uropigiano."}, "resposta_correta": "B", "justificativa": "O diafragma é um músculo respiratório exclusivo de mamíferos. Sua contração puxa o assoalho torácico para baixo, aumentando o volume dos pulmões e promovendo ventilação pulmonar por pressão negativa.", "possui_imagem": true},
  {"id": 137, "uid": "CIEN-7-137", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Coração de Aves e Mamíferos", "dificuldade": "Fácil", "enunciado": "Tanto as aves quanto os mamíferos possuem circulação sanguínea fechada, dupla e completa. Isso é possível porque o coração desses animais apresenta:", "alternativas": {"A": "Apenas duas cavidades (um átrio e um ventrículo).", "B": "Quatro cavidades completamente separadas (dois átrios e dois ventrículos), sem nenhuma mistura de sangue venoso e arterial.", "C": "Três cavidades que misturam sangue no ventrículo único.", "D": "Seis cavidades que bombeiam sangue diretamente para as penas.", "E": "Um ventrículo com septo aberto de Sabatier permanente."}, "resposta_correta": "B", "justificativa": "A tetracavitação cardíaca completa (septo interatrial e interventricular perfeitos) separa estritamente o sangue venoso (metade direita) do sangue arterial (metade esquerda), assegurando sangue 100% oxigenado para suportar o alto metabolismo endotérmico.", "possui_imagem": true},
  {"id": 138, "uid": "CIEN-7-138", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Classificação dos Mamíferos: Monotremados", "dificuldade": "Fácil", "enunciado": "O ornitorrinco e a équidna, animais nativos da Austrália e Nova Guiné, são mamíferos muito peculiares que pertencem ao grupo dos Monotremados (Prototérios). Eles são classificados como mamíferos porque:", "alternativas": {"A": "Possuem penas de ave e botam ovos de galinha no solo.", "B": "Apesar de serem ovíparos (botam ovos com casca), os filhotes recém-nascidos alimentam-se do leite secretado por glândulas mamárias na pele do ventre da mãe e têm o corpo coberto por pelos.", "C": "Possuem escamas de réptil e respiram por brânquias marinhas.", "D": "Não possuem ossos e rastejam como minhocas no solo.", "E": "São anfíbios que se transformaram em dinossauros herbívoros."}, "resposta_correta": "B", "justificativa": "Monotremados são mamíferos basais ovíparos dotados de cloaca; após a eclosão dos ovos, os filhotes lambem o leite expelido sobre tufos de pelos no abdômen materno (ausência de tetas diferenciadas).", "possui_imagem": true},
  {"id": 139, "uid": "CIEN-7-139", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Classificação dos Mamíferos: Marsupiais", "dificuldade": "Fácil", "enunciado": "Os cangurus, coalas e os gambás brasileiros pertencem ao grupo dos mamíferos Marsupiais (Metatérios). A característica marcante da reprodução desses animais é:", "alternativas": {"A": "Os filhotes nascem muito imaturos e completam o seu desenvolvimento dentro de uma bolsa de pele no ventre da mãe (o marsúpio), onde sugam leite de uma teta.", "B": "As fêmeas colocam ovos de casca de pedra no fundo dos rios.", "C": "O filhote passa dez anos dentro do útero da mãe sem nascer.", "D": "Eles nascem com asas e aprendem a voar logo após o parto.", "E": "Os pais chocam os filhotes debaixo das asas de penas."}, "resposta_correta": "A", "justificativa": "Os marsupiais apresentam gestação intrauterina curta com placenta vitelínica rudimentar; o feto prematuro escala os pelos até o marsúpio, abocanha uma mama e ali completa o desenvolvimento somático.", "possui_imagem": true},
  {"id": 140, "uid": "CIEN-7-140", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Classificação dos Mamíferos: Placentários", "dificuldade": "Fácil", "enunciado": "A imensa maioria dos mamíferos atuais (como cães, gatos, cavalos, baleias e seres humanos) pertence ao grupo dos Eutérios (Placentários). Nesses animais, o embrião desenvolve-se completamente dentro do útero materno nutrido por um órgão temporário chamado:", "alternativas": {"A": "Saco aéreo pulmonar.", "B": "Placenta.", "C": "Bolsa marsupial externa.", "D": "Glândula de veneno.", "E": "Casca calcária embrionária."}, "resposta_correta": "B", "justificativa": "Nos eutérios, a placenta alantocoriônica bem desenvolvida conecta intimamente a circulação fetal aos vasos maternos, realizando nutrição, trocas respiratórias, excreção e suporte endócrino durante toda a gestação.", "possui_imagem": true},
  {"id": 141, "uid": "CIEN-7-141", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Dentição Heterodonte dos Mamíferos", "dificuldade": "Fácil", "enunciado": "Diferente dos peixes e répteis, que geralmente possuem dentes todos iguais no formato (homodontes), a maioria dos mamíferos apresenta dentes com formatos e funções anatômicas diferenciadas (heterodontia). Esses dentes são divididos em:", "alternativas": {"A": "Escamas, espinhos, cerdas e garras.", "B": "Incisivos (cortar), caninos (rasgar), pré-molares e molares (triturar e moer).", "C": "Bicos de osso, línguas bífidas e presas venenosas.", "D": "Placas dérmicas, dentes operculares e dentículos placoides.", "E": "Tentáculos mastigadores e ossículos da orelha média."}, "resposta_correta": "B", "justificativa": "A dentição heterodonte reflete a especialização alimentar da mastigação mamaliana: incisivos para apreensão/corte, caninos para perfuração e pré-molares/molares para maceração mecânica eficiente.", "possui_imagem": false},
  {"id": 142, "uid": "CIEN-7-142", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Mamíferos Voadores: Morcegos", "dificuldade": "Fácil", "enunciado": "O único grupo de mamíferos dotado da capacidade de voo verdadeiro ativo sustentado por asas é o dos morcegos (ordem Chiroptera). As asas dos morcegos são formadas por:", "alternativas": {"A": "Penas leves idênticas às das aves voadoras.", "B": "Uma membrana de pele elástica e resistente (patágio) estendida entre os dedos extremamente alongados das mãos, os lados do corpo e as pernas.", "C": "Placas ósseas rígidas que se desprendem na hora do voo.", "D": "Pelos fundidos como plástico duro que batem no ar.", "E": "Nadadeiras peitorais com brânquias de peixe cartilaginoso."}, "resposta_correta": "B", "justificativa": "A asa dos quirópteros é constituída pelo patágio (membrana cutânea vascularizada sustentada pela mão mamaliana hipertrofiada, com dedos II a V extraordinariamente alongados), gerando sustentação alar ativa.", "possui_imagem": false},
  {"id": 143, "uid": "CIEN-7-143", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Mamíferos Aquáticos: Cetáceos", "dificuldade": "Fácil", "enunciado": "Baleias, golfinhos e botos são mamíferos totalmente adaptados à vida na água (ordem Cetacea). Embora se pareçam fisicamente com peixes por convergência evolutiva, eles são mamíferos porque:", "alternativas": {"A": "Botam ovos no leito do oceano e respiram por fendas branquiais.", "B": "Respiram ar atmosférico por pulmões, são endotérmicos, possuem glândulas mamárias para amamentar os filhotes e dão à luz filhotes vivos.", "C": "Têm o corpo coberto por escamas placoides de tubarão e sangue frio.", "D": "Se alimentam apenas de ar comprimido nas profundezas marinhas.", "E": "Não possuem coração nem circulação de sangue oxigenado."}, "resposta_correta": "B", "justificativa": "Cetáceos são mamíferos placentários secundariamente aquáticos: sobem à tona para respirar ar com seus pulmões através do espiráculo dorsal, possuem circulação dupla e completa, mantêm endotermia e produzem leite maternal rico em gordura.", "possui_imagem": false},
  {"id": 144, "uid": "CIEN-7-144", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Siringe: O Órgão do Canto das Aves", "dificuldade": "Fácil", "enunciado": "O canto melodioso dos pássaros, utilizado na demarcação de território e na atração de parceiros sexuais, é produzido por um órgão vocal localizado na base da traqueia (onde ela se divide em dois brônquios), chamado:", "alternativas": {"A": "Papo gástrico.", "B": "Siringe.", "C": "Moela vocal.", "D": "Laringe de cordas de osso.", "E": "Saco aéreo bucal."}, "resposta_correta": "B", "justificativa": "A siringe é o aparelho vocal cartilaginoso exclusivo das aves situado na bifurcação traqueobronquial, contendo membranas timpaniformes vibradas pelo fluxo aéreo sob controle de músculos vocais finos.", "possui_imagem": false},
  {"id": 145, "uid": "CIEN-7-145", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Aves Não Voadoras: Ratitas", "dificuldade": "Fácil", "enunciado": "Aves como a ema brasileira, o avestruz africano e o pinguim não voam. O avestruz e a ema possuem asas reduzidas, pernas longas e musculosas adaptadas à corrida e um osso esterno plano sem quilha. Por não possuírem carena no peito, essas aves são chamadas de:", "alternativas": {"A": "Aves carenatas.", "B": "Aves ratitas.", "C": "Aves canoras de voo rápido.", "D": "Morcegos terrestres.", "E": "Monotremados bípedes."}, "resposta_correta": "B", "justificativa": "As aves ratitas (Palaeognathae) apresentam esterno plano em forma de escudo sem carena (quilha), incapacitadas de voar e adaptadas à locomoção cursorial em ambientes abertos (como avestruzes, emas e casuares).", "possui_imagem": false},
  {"id": 146, "uid": "CIEN-7-146", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Orelha Média dos Mamíferos: Três Ossículos", "dificuldade": "Fácil", "enunciado": "Na orelha média de todos os mamíferos, a transmissão das ondas sonoras do tímpano para a cóclea é realizada por uma cadeia de três ossículos articulados, que são:", "alternativas": {"A": "Martelo, bigorna e estribo.", "B": "Fêmur, patela e tíbia.", "C": "Córnea, cristalino e íris.", "D": "Moela, papo e proventrículo.", "E": "Bexiga, ureter e uretra."}, "resposta_correta": "A", "justificativa": "A cadeia ossicular tríplice (martelo, bigorna e estribo) é exclusiva dos mamíferos (nos répteis e anfíbios existe apenas um ossículo, a columela/estribo), garantindo refinada impedância acústica aérea.", "possui_imagem": false},
  {"id": 147, "uid": "CIEN-7-147", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Hemácias Anucleadas nos Mamíferos", "dificuldade": "Fácil", "enunciado": "Ao analisar o sangue de diferentes vertebrados ao microscópio, um biólogo constata que as hemácias (glóbulos vermelhos) de peixes, anfíbios, répteis e aves possuem núcleo visível, enquanto as hemácias maduras dos mamíferos:", "alternativas": {"A": "Não possuem núcleo (são anucleadas), apresentando formato de disco bicôncavo que maximiza o espaço para conter hemoglobina e transportar oxigênio.", "B": "Têm formato de estrelas gigantescas com quatro núcleos cada.", "C": "São feitas de queratina e não transportam nenhum gás respiratório.", "D": "São substituídas por células de gordura vegetal na fase adulta.", "E": "Se fundem aos ossos para produzir leitematerno."}, "resposta_correta": "A", "justificativa": "A perda secundária do núcleo e de mitocôndrias durante a maturação eritrocitária nos mamíferos maximiza o volume citoplasmático para empacotamento de hemoglobina e confere maleabilidade para atravessar capilares estreitos.", "possui_imagem": false},
  {"id": 148, "uid": "CIEN-7-148", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Sacos Aéreos e Fluxo Respiratório Unidirecional nas Aves", "dificuldade": "Médio", "enunciado": "O sistema respiratório das aves é o mais eficiente de todo o reino animal. Ele conta com pulmões rígidos conectados a nove sacos aéreos anteriores e posteriores que se estendem pelo corpo e ossos. A circulação do ar nesse sistema ocorre de forma:", "alternativas": {"A": "Intermitente como nos mamíferos, parando as trocas gasosas na expiração.", "B": "Unidirecional contínua através dos parabrônquios, de modo que o oxigênio é absorvido tanto durante a inspiração quanto durante a expiração do animal, sem mistura com ar residual viciado.", "C": "Exclusivamente pela boca, sem passagem pela traqueia ou pulmões.", "D": "Em circuito fechado de gás hélio reciclado pelas penas.", "E": "De trás para a frente com expulsão de água pelos olhos."}, "resposta_correta": "B", "justificativa": "O sistema de sacos aéreos atua como foles sem realizar trocas gasosas diretas, empurrando o fluxo de ar em circuito unidirecional contínuo pelos parabrônquios pulmonares ao longo de dois ciclos completos de inspiração e expiração.", "possui_imagem": false},
  {"id": 149, "uid": "CIEN-7-149", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Arqueopterix e a Origem Dinossauriana das Aves", "dificuldade": "Médio", "enunciado": "O fóssil clássico do Archaeopteryx lithographica (datado de cerca de 150 milhões de anos atrás) é considerado uma das mais emblemáticas formas de transição da história evolutiva. Ele comprova que as aves modernas são descendentes diretas de dinossauros terópodes porque exibia conjuntamente:", "alternativas": {"A": "Pele de anfíbio úmida, brânquias funcionais e asas de morcego com pelos.", "B": "Penas e asas funcionais de ave associadas a características esqueléticas reptilianas como dentes na boca, cauda óssea longa e dedos com garras nas asas.", "C": "Glândulas mamárias ativas em um corpo de tartaruga marinha.", "D": "Casco de quelônio e bico sem penas.", "E": "Brânquias e quatro olhos coloridos na cabeça."}, "resposta_correta": "B", "justificativa": "O Archaeopteryx exibe um mosaico de traços: penas modernas de voo assimétricas nas asas e cauda, coexistindo com sinapomorfias reptilianas terópodes (dentes cônicos alveolares, cauda vertebral longa, garras nos membros anteriores e gastrália).", "possui_imagem": false},
  {"id": 150, "uid": "CIEN-7-150", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Ecolocalização em Morcegos e Cetáceos", "dificuldade": "Médio", "enunciado": "Morcegos insetívoros e cetáceos odontocetos (como golfinhos) utilizam a ecolocalização (biossonar) para navegar e capturar presas na escuridão ou em águas turvas. O princípio físico desse sentido consiste em:", "alternativas": {"A": "Enxergar calor infravermelho emitido pelas presas através dos olhos.", "B": "Emitir ondas sonoras de alta frequência (ultrassons) e captar o eco refletido pelos obstáculos e presas com ouvidos especializados, mapeando mentalmente o ambiente tridimensional.", "C": "Disparar pulsos de luz laser a partir da ponta da cauda.", "D": "Sentir o cheiro de bactérias através da linha lateral da pele.", "E": "Medir a gravidade com pedras de carbonato na língua."}, "resposta_correta": "B", "justificativa": "A ecolocalização baseia-se na emissão laríngea ou nasal de cliques e pulsos ultrassônicos (acima de 20 a 100 kHz) que colidem com alvos e retornam como ecos, decodificados no córtex auditivo para determinar distância, tamanho, velocidade e textura do objeto.", "possui_imagem": false},
  {"id": 151, "uid": "CIEN-7-151", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Digestão nos Ruminantes: Simbiose com Microrganismos", "dificuldade": "Médio", "enunciado": "Mamíferos herbívoros ruminantes (como bois, ovelhas, veados e girafas) alimentam-se de vegetais ricos em celulose fibrosa. Como nenhum vertebrado produz a enzima celulase, a digestão da celulose nesses animais é realizada graças a:", "alternativas": {"A": "Bactérias, protozoários e fungos simbiontes que vivem nos compartimentos do estômago (especialmente no rúmen e retículo), que fermentam a celulose em ácidos graxos voláteis absorvíveis.", "B": "Altas temperaturas de 100 ºC mantidas no estômago que queimam a grama.", "C": "Mastigação que quebra as moléculas de celulose em átomos puros de carbono.", "D": "Saliva rica em ácido clorídrico concentrado que dissolve pedras.", "E": "Veneno produzido no fígado que destrói a parede celular vegetal."}, "resposta_correta": "A", "justificativa": "Ruminantes abrigam um complexo microbioma anaeróbio em suas câmaras pré-estomacais (rúmen e barrete). Microrganismos simbióticos hidrolisam as ligações beta-1,4-glicosídicas da celulose, gerando ácidos graxos de cadeia curta que suprem a maior parte da demanda calórica do animal.", "possui_imagem": false},
  {"id": 152, "uid": "CIEN-7-152", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Arco Aórtico em Aves e Mamíferos", "dificuldade": "Médio", "enunciado": "Embora tanto as aves quanto os mamíferos tenham evoluído corações tetracavitários com separação completa entre circulação pulmonar e sistêmica, eles evoluíram essa característica de forma independente (convergência evolutiva). Essa independência de origens é comprovada anatomicamente pelo trajeto do grande arco aórtico sistêmico:", "alternativas": {"A": "Nas aves o arco aórtico curva-se para a direita, enquanto nos mamíferos o arco aórtico curva-se para a esquerda ao sair do coração.", "B": "Nas aves a aorta conecta-se aos pulmões e nos mamíferos conecta-se à pele.", "C": "Nos mamíferos a aorta não possui sangue, apenas ar comprimido.", "D": "Nas aves a aorta passa por fora das penas das asas.", "E": "Em ambos o arco aórtico desaparece logo após o nascimento."}, "resposta_correta": "A", "justificativa": "Aves retêm o 4º arco aórtico embrionário direito como aorta sistêmica funcional (arco aórtico destro), enquanto mamíferos retêm o 4º arco aórtico embrionário esquerdo (arco aórtico sinistro), evidenciando derivações filogenéticas paralelas a partir de ancestrais reptilianos distintos.", "possui_imagem": false},
  {"id": 153, "uid": "CIEN-7-153", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Camuflagem e Muda de Plumagem nas Aves", "dificuldade": "Médio", "enunciado": "Muitas espécies de aves migratórias de regiões árticas (como a perdiz-das-neves) trocam de plumagem sazonalmente: no verão possuem penas marrons e cinzentas salpicadas que imitam as rochas e líquens da tundra, e no inverno substituem todas as penas por uma plumagem branca imaculada. Esse fenômeno é uma adaptação de:", "alternativas": {"A": "Mimetismo batesiano contra predadores marinhos.", "B": "Camuflagem críptica sazonal, que oculta a ave na paisagem tanto para fugir de predadores quanto para aproximar-se de presas sem ser detectada na neve.", "C": "Mutação genética irreversível provocada pelo frio extremo.", "D": "Perda acidental de penas por queimadura solar polar.", "E": "Parasitismo reprodutivo em ninhos de falcões."}, "resposta_correta": "B", "justificativa": "A muda sazonal de penas atua como coloração críptica sincronizada com o fotoperíodo: no degelo mimetiza o substrato terroso e na estação de neve confere invisibilidade visual contra predadores de topo (como raposas-do-ártico e corujas-das-neves).", "possui_imagem": false},
  {"id": 154, "uid": "CIEN-7-154", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Origem Evolutiva dos Pelos e Glândulas Mamárias", "dificuldade": "Médio", "enunciado": "Na história evolutiva dos vertebrados sinápsidos (linhagem que deu origem aos mamíferos), os pelos e as glândulas mamárias surgiram a partir de modificações em estruturas tegumentares pré-existentes. As glândulas mamárias evoluíram a partir da especialização de:", "alternativas": {"A": "Penas de voo de dinossauros que acumulavam gordura.", "B": "Glândulas sebáceas ou glândulas sudoríparas apócrinas da pele que originalmente secretavam fluidos com propriedades antimicrobianas para proteger os ovos no ninho.", "C": "Células da retina dos olhos que desceram para o peito.", "D": "Dentes de leite quebrados no interior da pele do abdômen.", "E": "Vasos sanguíneos que estouraram na derme materna."}, "resposta_correta": "B", "justificativa": "Evidências filogenéticas e histológicas demonstram que as glândulas mamárias representam modificações apomórficas de glândulas apócrinas/sebáceas tegumentares que ancestrais peludos utilizavam para umedecer e imunizar ovos em ninhadas, evoluindo subsequentemente para secreção nutritiva pós-natal.", "possui_imagem": false},
  {"id": 155, "uid": "CIEN-7-155", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula de Veneno no Ornitorrinco", "dificuldade": "Médio", "enunciado": "O ornitorrinco macho possui na face interna de seus tornozelos traseiros um esporão córneo oco conectado a uma glândula femoral produtora de veneno. A função biológica primária desse aparato venenoso no ornitorrinco é:", "alternativas": {"A": "Matar peixes e caranguejos para alimentação diária no rio.", "B": "Competição agonística territorial e disputas sexuais entre machos durante a estação reprodutiva da primavera.", "C": "Injetar toxinas nos ovos chocados pela fêmea para endurecer a casca.", "D": "Proteger as patas contra congelamento em águas frias da Tasmânia.", "E": "Eliminar ureia em excesso do organismo quando os rins falham."}, "resposta_correta": "B", "justificativa": "O veneno dos machos de ornitorrinco atinge pico de produção na temporada reprodutiva e não serve para forrageamento; é uma arma de combate intraespecífica utilizada em disputas agressivas entre machos por fêmeas e território.", "possui_imagem": false},
  {"id": 156, "uid": "CIEN-7-156", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula do Sal em Aves Marinhas", "dificuldade": "Médio", "enunciado": "Albatrozes e petréis passam meses voando sobre alto-mar sem tocar a terra firme, bebendo exclusivamente água salgada do oceano e alimentando-se de lulas. Para não morrerem desidratados pelo excesso de sal ingerido, essas aves possuem acima das órbitas oculares:", "alternativas": {"A": "Bolsas de gelo que congelam o sal antes de engolir.", "B": "Glândulas nasais de sal altamente ativas que filtram o excesso de cloreto de sódio da corrente sanguínea e o excretam como uma solução salina concentrada pelas narinas.", "C": "Rins gigantes que ocupam todo o espaço das asas.", "D": "Escamas de tartaruga marinha fundidas ao bico.", "E": "Glândulas mamárias que transformam água salgada em leite materno."}, "resposta_correta": "B", "justificativa": "As aves marinhas pelágicas possuem glândulas de sal supraorbitais com túbulos secretores que utilizam transporte ativo para concentrar e expelir salmoura a até 5% de NaCl pelas aberturas nasais, poupando água renal.", "possui_imagem": false},
  {"id": 157, "uid": "CIEN-7-157", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Visão Noturna nas Corujas: Adaptações Sensoriais", "dificuldade": "Médio", "enunciado": "As corujas são predadoras noturnas com extraordinária eficiência na caça de pequenos roedores no escuro total. Entre as adaptações anatômicas do sistema visual e auditivo das corujas, destacam-se:", "alternativas": {"A": "Olhos esféricos pequenos e ausência de audição.", "B": "Olhos tubulares volumosos densamente povoados por fotorreceptores bastonetes, pupilas amplas e ouvidos assimétricos que permitem localização tridimensional de ruídos de presas por diferença de tempo de chegada do som.", "C": "Visão de calor através de tentáculos colocados no topo do crânio.", "D": "Emissão de ultrassons pelas asas cobertas por pelos de morcego.", "E": "Presas venenosas de serpente embutidas no bico afiado."}, "resposta_correta": "B", "justificativa": "As corujas combinam olhos tubulares orientados para a frente com imensa densidade de bastonetes para máxima captação de fótons na penumbra e condutos auditivos externos desalinhados verticalmente, permitindo triangulação acústica binaural de presas no solo.", "possui_imagem": false},
  {"id": 158, "uid": "CIEN-7-158", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Termorregulação em Mamíferos: Vasodilatação e Suor", "dificuldade": "Médio", "enunciado": "Em dias muito quentes ou durante corridas intensas, o corpo humano e o de muitos outros mamíferos utilizam mecanismos fisiológicos involuntários para evitar a hipertermia fatal. Dois desses mecanismos termorregulatórios vitais são:", "alternativas": {"A": "Vasoconstrição periférica e parada da respiração.", "B": "Vasodilatação de vasos sanguíneos da pele (irradiando mais calor para o ar) e sudorese (evaporação do suor pelas glândulas sudoríparas, retirando calor latente de vaporização da pele).", "C": "Aumento do consumo de oxigênio pelas penas do corpo.", "D": "Parada imediata de todos os batimentos do coração.", "E": "Acúmulo de gordura na cabeça para proteger o cérebro."}, "resposta_correta": "B", "justificativa": "O centro termorregulador hipotalâmico dispara vasodilatação cutânea periférica para maximizar a convecção e irradiação dérmica e ativa glândulas sudoríparas écrinas; a evaporação da água do suor absorve calor latente da derme, resfriando o sangue circulante.", "possui_imagem": false},
  {"id": 159, "uid": "CIEN-7-159", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Adaptações Fisiológicas de Mergulho em Cetáceos", "dificuldade": "Médio", "enunciado": "Cachalotes e focas conseguem mergulhar a mais de 1.000 metros de profundidade no oceano e permanecer em apneia subaquática por mais de uma hora sem respirar ar novo. As adaptações fisiológicas que tornam possível essa tolerância extrema à hipóxia incluem:", "alternativas": {"A": "Trocar os pulmões por brânquias de tubarão durante o mergulho.", "B": "Grandes volumes de sangue com altíssimas concentrações de hemoglobina, massivo estoque de oxigênio ligado à mioglobina nos músculos esqueléticos e bradicardia reflexa (desaceleração drástica dos batimentos cardíacos com vasoconstrição seletiva para órgãos vitais).", "C": "Armazenar botijões de ar comprimido dentro dos ossos das pernas.", "D": "Respirar água do mar congelada pelas orelhas internas.", "E": "Parar o funcionamento de todas as células do cérebro no fundo do mar."}, "resposta_correta": "B", "justificativa": "O reflexo de mergulho dos mamíferos marinhos (bradicardia profunda e vasoconstrição periférica restrita a cérebro e coração) soma-se a estoques musculares extraordinários de mioglobina (até 10 vezes maiores que os de humanos), suportando mergulhos prolongados com baixo metabolismo residual.", "possui_imagem": false},
  {"id": 160, "uid": "CIEN-7-160", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "O Papo das Aves e o 'Leite de Pombo'", "dificuldade": "Médio", "enunciado": "O papo é uma dilatação elástica do esôfago nas aves granívoras que serve para armazenar e amolecer grãos e sementes. Em pombos e flamingos, durante o período de criação dos filhotes, o papo desempenha uma função reprodutiva ímpar:", "alternativas": {"A": "Produzir ovos com casca calcária a cada três horas.", "B": "Secretar uma substância pastosa e nutritiva rica em proteínas e lipídios chamada 'leite de papo' (estimulada pelo hormônio prolactina), regurgitada para alimentar os filhotes recém-eclodidos.", "C": "Eliminar as penas velhas para construir o ninho.", "D": "Armazenar ar quente para aquecer os filhotes como um aquecedor a gás.", "E": "Funcionar como uma siringe para cantar músicas suaves."}, "resposta_correta": "B", "justificativa": "O 'leite de papo' (crop milk) é uma secreção holócrina das células epiteliais do papo de pombos machos e fêmeas sob estímulo da prolactina (o mesmo hormônio da lactação mamífera), fundamental para o crescimento acelerado dos filhotes nos primeiros dias de vida.", "possui_imagem": false},
  {"id": 161, "uid": "CIEN-7-161", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Aparelho Digestório de Herbívoros Não Ruminantes: Ceco Desenvolvido", "dificuldade": "Médio", "enunciado": "Mamíferos herbívoros não ruminantes (como cavalos, zebras e coelhos) possuem estômago simples de uma única câmara, mas alimentam-se de pasto rico em celulose. A fermentação bacteriana da fibra vegetal nesses animais ocorre principalmente no:", "alternativas": {"A": "Papo do esôfago.", "B": "Ceco e cólon do intestino grosso, que são extraordinariamente volumosos e abrigam bilhões de microrganismos fermentadores.", "C": "Fígado e vesícula biliar de grande porte.", "D": "Pâncreas com glândulas salivares acessórias.", "E": "Interior da bexiga urinária."}, "resposta_correta": "B", "justificativa": "Cavalos e leporídeos são fermentadores pós-gástricos (hindgut fermenters): o ceco e o cólon ascendente são hipertrofiados formando uma grande câmara de fermentação microbiana que digere a celulose após a passagem pelo estômago e intestino delgado.", "possui_imagem": false},
  {"id": 162, "uid": "CIEN-7-162", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Copofagia em Roedores e Coelhos", "dificuldade": "Médio", "enunciado": "Coelhos e lebres exibem frequentemente o hábito comportamental de ingerir uma categoria específica de suas próprias fezes recém-eliminadas (os cecotrofos, bolotas moles e mucosas produzidas no ceco durante a madrugada). Esse comportamento de cecotrofia serve para:", "alternativas": {"A": "Limpar a toca de terra sem gastar energia.", "B": "Reabsorver nutrientes essenciais (como vitaminas do complexo B e aminoácidos microbianos) produzidos pela fermentação no ceco, que foram eliminados após passarem pelo local principal de absorção do intestino delgado.", "C": "Afastar predadores carnívoros pelo cheiro do ninho.", "D": "Amolar os dentes incisivos superiores com a fibra fecal.", "E": "Substituir a ingestão de água mineral no inverno."}, "resposta_correta": "B", "justificativa": "Como a fermentação bacteriana no coelho ocorre no ceco (localizado após o intestino delgado, sítio primário de absorção de aminoácidos e vitaminas), a ingestão dos cecotrofos viabiliza uma segunda passagem pelo trato digestório, permitindo a assimilação dos nutrientes sintetizados pelos simbiontes.", "possui_imagem": false},
  {"id": 163, "uid": "CIEN-7-163", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "O Pecten Oculi nas Aves", "dificuldade": "Médio", "enunciado": "No interior do globo ocular das aves existe uma estrutura vascularizada pigmentada em forma de pente que se projeta da retina para dentro do humor vítreo, chamada pecten oculi. A função biológica dessa estrutura é:", "alternativas": {"A": "Produzir lágrimas oleosas que impermeabilizam as penas ao redor dos olhos.", "B": "Fornecer oxigênio e nutrientes à retina e remover resíduos metabólicos sem que haja vasos sanguíneos sobre a superfície foveal, garantindo máxima nitidez e acuidade visual desobstruída.", "C": "Emitir luz fosforescente para enxergar insetos debaixo da terra.", "D": "Fazer a íris piscar como uma câmera fotográfica digital.", "E": "Armazenar sementes pequenas capturadas no bico."}, "resposta_correta": "B", "justificativa": "A retina aviária é desprovida de vasos sanguíneos intrarretinianos que dispersariam a luz incidente. O pecten oculi atua como órgão nutricional que banha a retina avascular por difusão vítrea, preservando a incomparável resolução óptica de predadores aéreos.", "possui_imagem": false},
  {"id": 164, "uid": "CIEN-7-164", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Pele e Glândulas Sebáceas nos Mamíferos", "dificuldade": "Médio", "enunciado": "A pele dos mamíferos é um órgão dinâmico rico em glândulas exócrinas. As glândulas sebáceas, associadas aos folículos pilosos, desempenham a função de:", "alternativas": {"A": "Secretar sebo lipídico que lubrifica e impermeabiliza os pelos e o estrato córneo da pele, evitando ressecamento e exercendo ação bacteriostática protetora.", "B": "Produzir suor ácido para queimar insetos invasores na pele.", "C": "Secretar leite materno nos machos adultos durante o frio.", "D": "Produzir queratina rígida para formar a casca calcária dos dentes.", "E": "Absorver gás carbônico do ar para a respiração cutânea."}, "resposta_correta": "A", "justificativa": "As glândulas sebáceas holócrinas secretam lipídios que formam o manto hidrolipídico cutâneo, prevenindo evaporação transepidérmica de água, mantendo a flexibilidade dos pelos e inibindo a colonização por bactérias patogênicas.", "possui_imagem": false},
  {"id": 165, "uid": "CIEN-7-165", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Muda de Penas e Migração nas Aves", "dificuldade": "Médio", "enunciado": "Aves migratórias que realizam viagens intercontinentais de milhares de quilômetros (como o maçarico e a andorinha) acumulam grande quantidade de gordura subcutânea antes da partida e realizam a muda completa de suas penas de voo (rêmiges). Essa renovação periódica das penas é essencial porque:", "alternativas": {"A": "Penas velhas e desgastadas pelo atrito aerodinâmico perdem a integridade das barbelas e o perfil de sustentação, o que aumentaria o arrasto e tornaria o voo migratório inviável ou perigoso.", "B": "Penas novas permitem que a ave respire oxigênio através das asas.", "C": "Penas antigas pesam dez vezes mais do que penas jovens.", "D": "A ave só consegue botar ovos se trocar de asas a cada três meses.", "E": "Penas desgastadas atraem raios elétricos de tempestades."}, "resposta_correta": "A", "justificativa": "O desgaste mecânico das penas degrada o imbricamento de barbas e bárbulas com microganchos, reduzindo a eficiência aerodinâmica e o isolamento térmico. A muda programada restaura a aerodinâmica antes das custosas rotas migratórias.", "possui_imagem": false},
  {"id": 166, "uid": "CIEN-7-166", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Tecido Adiposo Marrom (TAM) nos Mamíferos", "dificuldade": "Médio", "enunciado": "Filhotes recém-nascidos de mamíferos (incluindo bebês humanos) e mamíferos que hibernam possuem depósitos especializados de 'tecido adiposo marrom' (gordura marrom) entre as escápulas e pescoço. Esse tecido atua na termogênese sem calafrios porque:", "alternativas": {"A": "Suas mitocôndrias possuem a proteína termogenina (UCP-1), que desacopla a cadeia respiratória da síntese de ATP, dissipando toda a energia da queima de gordura diretamente na forma de calor para aquecer o sangue.", "B": "Armazena oxigênio sólido congelado para o cérebro.", "C": "Produz leite de emergência no interior da caixa torácica.", "D": "Substitui os pulmões quando o animal fica submerso no gelo.", "E": "Transforma a glicose em ossos rígidos de proteção."}, "resposta_correta": "A", "justificativa": "A termogenina (UCP-1) desvia o gradiente de prótons da membrana mitocondrial interna sem passar pela ATP sintase. A oxidação de ácidos graxos dissipa-se integralmente como energia térmica imediata, aquecendo o leito capilar e prevenindo hipotermia letal em recém-nascidos.", "possui_imagem": false},
  {"id": 167, "uid": "CIEN-7-167", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Adaptação de Aves ao Mergulho: Ossos Não Pneumáticos", "dificuldade": "Médio", "enunciado": "Aves mergulhadoras que nadam ativamente debaixo da água para capturar peixes em profundidade (como os pinguins e biguás) apresentam esqueletos com ossos densos e pesados, praticamente sem pneumatização. Essa modificação esquelética é uma adaptação para:", "alternativas": {"A": "Aumentar a densidade média do corpo da ave, facilitando a submersão e o nado veloz subaquático ao reduzir a flutuabilidade excessiva que a empurraria para a superfície.", "B": "Fazer a ave voar mais alto que os aviões quando sai do mar.", "C": "Permitir que o pinguim respire água salgada como um peixe ósseo.", "D": "Impedir que a ave perca calor quando caminha sobre pedras vulcânicas.", "E": "Proteger as patas contra mordidas de formigas terrestres."}, "resposta_correta": "A", "justificativa": "Ao contrário de aves voadoras aéreas que selecionam ossos ocos e pneumáticos para reduzir peso, mergulhadores pelágicos (Sphenisciformes) selecionam paquiostose (ossos densos e compactos) para anular a flutuabilidade positiva e economizar energia muscular na descida subaquática.", "possui_imagem": false},
  {"id": 168, "uid": "CIEN-7-168", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Sentido Olfatório nos Mamíferos: O Focinho Úmido (Rinário)", "dificuldade": "Médio", "enunciado": "Muitos mamíferos carnívoros e ungulados (como cães, gatos e vacas) possuem a ponta do focinho nua, fria e constantemente úmida (o rinário). A umidade permanente na superfície do focinho desempenha a função biológica de:", "alternativas": {"A": "Ajudar a dissolver moléculas químicas odoríferas trazidas pelo ar e detectar a direção exata de onde o vento está soprando através do resfriamento evaporativo, orientando o animal em direção à presa ou predador.", "B": "Eliminar todo o excesso de urina do animal através do nariz.", "C": "Produzir leite para os filhotes quando a mãe está deitada.", "D": "Impedir que o cão respire ar atmosférico seco.", "E": "Proteger os dentes caninos contra bactérias da carne."}, "resposta_correta": "A", "justificativa": "O rinário úmido aprisiona partículas químicas voláteis no filme aquoso, facilitando a transferência ao epitélio olfatório e ao órgão vomeronasal; adicionalmente, a taxa diferencial de evaporação pelo vento nas bordas do nariz permite que o animal identifique o quadrante azimutal da fonte odorífera.", "possui_imagem": false},
  {"id": 169, "uid": "CIEN-7-169", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Aerodinâmica Alar e Voo das Aves: Asas de Alta Sustentação", "dificuldade": "Difícil", "enunciado": "A morfologia da asa das aves varia de acordo com o nicho ecológico e o padrão de voo da espécie. Albatrozes possuem asas extremamente longas e estreitas (alto alongamento alar), enquanto gaviões que caçam em florestas densas possuem asas curtas, largas e arredondadas com rémiges separadas nas pontas (fendas alares). As fendas alares nas pontas das asas dos gaviões atuam fisicamente para:", "alternativas": {"A": "Emitir assobios estridentes que assustam roedores no solo.", "B": "Reduzir o arrasto induzido dissipando os vórtices de ponta de asa e permitindo decolagens rápidas e manobras ágeis em baixas velocidades com alto ângulo de ataque entre os galhos das árvores.", "C": "Armazenar oxigênio de reserva durante o mergulho em alta velocidade.", "D": "Cortar folhas e galhos como navalhas para abrir clareiras na mata.", "E": "Fazer a asa funcionar como uma vela solar cósmica."}, "resposta_correta": "B", "justificativa": "Fendas alares dividem a ponta da asa em pequenas lâminas independentes com alto coeficiente de sustentação, diminuindo os turbilhões induzidos de vórtice marginal e evitando o estol aerodinâmico em baixas velocidades operacionais de manobra florestal.", "possui_imagem": false},
  {"id": 170, "uid": "CIEN-7-170", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Evolução da Mandíbula e dos Ossículos Auditivos nos Mamíferos", "dificuldade": "Difícil", "enunciado": "Na transição dos répteis sinápsidos basais (terapsídeos/cinodontes) para os primeiros mamíferos verdadeiros, a mandíbula inferior, que antes era formada por vários ossos (dentário, articular, angular, surangular), simplificou-se em um único osso: o dentário. Durante essa profunda reorganização esquelética craniana, os antigos ossos reptilianos articular e quadrado migraram evolutivamente para o interior da orelha média, transformando-se, respectivamente, em:", "alternativas": {"A": "Tímpano e cóclea espiralada.", "B": "Martelo e Bigorna dos mamíferos, articulados ao estribo pré-existente.", "C": "Caninos superiores e inferiores de leite.", "D": "Cartilagens da laringe e tireoide.", "E": "Ossos pneumáticos do crânio da face."}, "resposta_correta": "B", "justificativa": "A homologia óssea de Reichert-Gaupp é um dos triunfos da anatomia comparada e paleontologia: o osso articular da mandíbula reptiliana derivou no martelo, o osso quadrado no topo da mandíbula derivou na bigorna e o osso angular na bula timpânica, aprimorando drasticamente a acuidade auditiva mamaliana.", "possui_imagem": false},
  {"id": 171, "uid": "CIEN-7-171", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Eficiência da Ventilação Cruzada Parabronquial das Aves", "dificuldade": "Difícil", "enunciado": "A hematose pulmonar nas aves não ocorre por difusão em fundo cego como nos alvéolos dos mamíferos, mas sim por um sistema de 'corrente cruzada' (cross-current exchange) nos capilares aéreos dos parabrônquios. Nesse sistema biofísico:", "alternativas": {"A": "O sangue arterial e o venoso correm juntos no mesmo vaso.", "B": "Capilares sanguíneos cruzam perpendicularmente o fluxo de ar unidirecional dos capilares aéreos; isso permite que o sangue arterial que deixa os pulmões atinja uma pressão parcial de oxigênio (pO2) superior à do ar expirado, conferindo incomparável capacidade de voo em altitudes extremas onde o ar é rarefeito (como gansos voando sobre o Everest).", "C": "A ave absorve oxigênio apenas pela moela mecânica.", "D": "O sangue perde oxigênio para a atmosfera a cada ciclo cardíaco.", "E": "As trocas gasosas só acontecem enquanto a ave está dormindo no ninho."}, "resposta_correta": "B", "justificativa": "No intercâmbio por corrente cruzada, capilares sanguíneos intersectam transversalmente o parabrânquio em série; o sangue oxigenado efluente atinge uma pO2 mais alta do que a do ar residual que sai dos pulmões, o que é fisiologicamente impossível no arranjo alveolar mamífero (onde a pO2 arterial nunca supera a pO2 alveolar).", "possui_imagem": false},
  {"id": 172, "uid": "CIEN-7-172", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Eletrorecepção no Focinho do Ornitorrinco", "dificuldade": "Difícil", "enunciado": "Quando o ornitorrinco mergulha em rios para caçar pequenos invertebrados bentônicos, ele fecha completamente seus olhos, narinas e condutos auditivos. A captura bem-sucedida de camarões e larvas no leito lamacento do rio depende de seu bico achatado flexível, que é forrado por dezenas de milhares de:", "alternativas": {"A": "Dentes afiados de marfim fossilizado.", "B": "Eletrorreceptores sensíveis a campos elétricos musculares de presas e mecanorreceptores táteis integrados, permitindo calcular por triangulação a distância e trajetória exatas da presa viva através do intervalo entre o sinal elétrico e a onda mecânica na água.", "C": "Papilas gustativas que provam o barro à distância de 20 metros.", "D": "Tentáculos carnívoros retráteis semelhantes aos de polvos.", "E": "Penas aquáticas com sensores ultravioleta."}, "resposta_correta": "B", "justificativa": "O bico do ornitorrinco é um órgão sensório-motor sofisticado com dezenas de milhares de poros glandulares modificados atuando como eletrorreceptores e mecanorreceptores de 'push-rod'; o córtex somatossensorial processa a defasagem temporal entre o sinal elétrico da contração da presa e a onda de pressão mecânica aquática para abocanhá-la de olhos fechados.", "possui_imagem": false},
  {"id": 173, "uid": "CIEN-7-173", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Rins com Alça de Henle e Concentração Urinária nos Mamíferos", "dificuldade": "Difícil", "enunciado": "Os mamíferos são capazes de produzir urina consideravelmente mais concentrada (hipertônica) do que o próprio plasma sanguíneo (roedores do deserto como o rato-canguru conseguem concentrar a urina em até 20 vezes a osmolaridade do sangue). Essa extraordinária capacidade fisiológica renal depende exclusivamente de uma inovação no néfron presente apenas em mamíferos e em certas aves:", "alternativas": {"A": "Glomérulos cobertos por queratina impermeável.", "B": "A presença de longas Alças de Henle mergulhadas na medula renal, que operam como multiplicadores de contracorrente osmótica gerando um gradiente hiperosmótico de solutos que força a reabsorção passiva de água sob estímulo do hormônio antidiurético (ADH/vasopressina).", "C": "Rins que deságuam diretamente nas glândulas mamárias.", "D": "A destruição de todas as moléculas de sódio pelas células renais.", "E": "Bexigas urinárias com paredes musculares de cartilagem condróide."}, "resposta_correta": "B", "justificativa": "A alça de Henle (alça do néfron) estabelece um gradiente corticomedular osmótico crescente por transporte ativo de NaCl no ramo ascendente impermeável à água; esse gradiente medular atrai água por osmose do ducto coletor via aquaporinas reguladas por ADH, produzindo urina hiperosmótica concentrada.", "possui_imagem": false},
  {"id": 174, "uid": "CIEN-7-174", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Evolução do Voo: Hipótese Cursoriana vs. Arbórea nas Aves", "dificuldade": "Difícil", "enunciado": "O debate paleontológico sobre a origem do voo das aves confronta duas hipóteses macroevolutivas clássicas: a 'hipótese arbórea' (top-down / de cima para baixo) e a 'hipótese cursorial' (bottom-up / de baixo para cima). A hipótese cursorial defende que:", "alternativas": {"A": "As aves ancestrais voavam nadando em oceanos profundos com brânquias.", "B": "Pequenos dinossauros terópodes bípedes corredores utilizavam o bater das asas plumadas para ganhar empuxo aerodinâmico e correr subindo encostas íngremes e troncos verticais (mecanismo WAIR / Wing-Assisted Incline Running) antes de atingir o voo batido sustentado livre.", "C": "Os animais caíam de paraquedas de árvores gigantescas sem bater as asas.", "D": "O voo surgiu a partir de saltos de gafanhotos gigantes pré-históricos.", "E": "As aves aprenderam a voar sendo arremessadas por erupções vulcânicas devonianas."}, "resposta_correta": "B", "justificativa": "A tese cursorial (WAIR) sustenta que a força aerodinâmica gerada por membros anteriores emplumados servia para pressionar o dinossauro contra o solo ou taludes (aumentando a tração nas patas posteriores) ao correr em ladeiras íngremes na fuga de predadores, precursora da transição biomecânica para o voo batido ascendente.", "possui_imagem": false},
  {"id": 175, "uid": "CIEN-7-175", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula Mamária e Imunologia: O Colostro", "dificuldade": "Difícil", "enunciado": "Nos primeiros dias após o parto, a glândula mamária dos mamíferos eutérios secreta um fluido leitoso espesso e amarelado denominado colostro antes da descida do leite maduro. A importância biológica insubstituível do colostro para a sobrevida do neonato baseia-se em:", "alternativas": {"A": "Conter grande quantidade de açúcar refinado que endurece os ossos em 2 horas.", "B": "Fornecer altíssimas concentrações de anticorpos maternos (especialmente imunoglobulina A secretora - IgA e IgG), fatores de crescimento e células fagocíticas que revestem a mucosa intestinal do filhote, conferindo imunidade passiva imediata contra patógenos ambientais.", "C": "Congelar o estômago do filhote para que ele não sinta fome durante semanas.", "D": "Conter veneno em dose fraca para treinar os músculos do filhote contra predadores.", "E": "Impedir que o filhote respire ar atmosférico nos primeiros dias de vida."}, "resposta_correta": "B", "justificativa": "O colostro atua como uma barreira imunológica transferida ativamente: a mucosa gástrica e intestinal imatura do recém-nascido é banhada por IgA secretora e anticorpos maternos que neutralizam bactérias e vírus entéricos, prevenindo infecções sistêmicas nas primeiras semanas de vida.", "possui_imagem": false},
  {"id": 176, "uid": "CIEN-7-176", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Giro da Pelve e Origem dos Dinossauros: Saurísquios vs. Ornitísquios", "dificuldade": "Difícil", "enunciado": "Os dinossauros são tradicionalmente classificados em duas grandes linhagens com base na anatomia da pelve óssea: Saurischia (pelve com púbis voltado para a frente, semelhante à dos lagartos) e Ornithischia (pelve com púbis voltado para trás, superficialmente semelhante à das aves). Surpreendentemente para a anatomia clássica, as aves modernas evoluíram a partir de qual linhagem?", "alternativas": {"A": "Dos Ornithischia herbívoros (como Triceratops e Estegossauro).", "B": "Dos Saurischia terópodes (carnívoros bípedes como velociraptores e tiranossauros), cuja pelve sofreu retroversão secundária do púbis ao longo da evolução da linhagem das aves.", "C": "Dos Pterossauros voadores de asas de pele membranosa.", "D": "Dos Crocodilianos basais de carapaça marinha.", "E": "Dos quelônios anapsídeos de casco de pedra."}, "resposta_correta": "B", "justificativa": "Apesar do nome 'ornitísquio' ('pelve de ave'), trata-se de homoplasia (convergência morfológica). Filogenias moleculares e osteológicas rigorosas comprovam que as aves são dinossauros terópodes pertencentes ao clado Saurischia (Eumaniraptora), tendo a pelve virada para trás por rearranjo evolutivo independente.", "possui_imagem": false},
  {"id": 177, "uid": "CIEN-7-177", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula Parótida e Mastigação com Saliva Amilásica em Mamíferos", "dificuldade": "Difícil", "enunciado": "A mastigação associada a glândulas salivares bem desenvolvidas (parótidas, submandibulares e sublinguais) nos mamíferos não apenas fragmenta o alimento, mas inicia ativamente a digestão química na boca. A produção contínua de saliva com amilase salivar (ptialina) e mucina é uma vantagem evolutiva para a endotermia porque:", "alternativas": {"A": "Transforma todo o alimento em osso sólido antes de engolir.", "B": "Aumenta a velocidade e eficiência da extração energética dos carboidratos, reduzindo o tempo de trânsito digestivo e suportando a voraz demanda energética metabólica contínua dos animais homeotérmicos.", "C": "Impede que a carne crua solte água no esôfago.", "D": "Substitui a circulação de sangue oxigenado pela saliva nos tecidos da cabeça.", "E": "Destrói o estômago para que o mamífero viva apenas de ar."}, "resposta_correta": "B", "justificativa": "Mamíferos gastam até 10 vezes mais energia basal por grama de tecido que répteis de mesmo porte. A mastigação refinada heterodonte aliada à insalivação enzimática acelera a taxa de quebra hidrolítica de macronutrientes, garantindo influxo calórico constante ao sangue.", "possui_imagem": false},
  {"id": 178, "uid": "CIEN-7-178", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Dimorfismo Sexual e Seleção Sexual nas Aves", "dificuldade": "Difícil", "enunciado": "Em muitas espécies de aves (como pavões, tangarás e galos-da-serra), os machos exibem plumagens exuberantes, cristas coloridas brilhantes e danças nupciais complexas em arenas coletivas (leks), enquanto as fêmeas possuem plumagem parda e camuflada. Esse dimorfismo sexual marcante é explicado pela teoria da seleção sexual através do princípio:", "alternativas": {"A": "Da sobrevivência exclusiva do animal com o bico mais duro.", "B": "Da escolha críptica das fêmeas por sinais honestos de vigor genético e baixa carga parasitária (Princípio do Handicap de Zahavi), balanceado pelo fato de que as fêmeas necessitam de camuflagem para não serem predadas no ninho durante a incubação dos ovos.", "C": "Do mimetismo batesiano com flores venenosas da copa das árvores.", "D": "De que machos coloridos absorvem radiação solar para voar sem bater asas.", "E": "De que as fêmeas perdem a visão das cores na idade adulta."}, "resposta_correta": "B", "justificativa": "A seleção intersexual impulsiona caracteres epigâmicos custosos: plumas berrantes e cortejos energéticos atestam capacidade imunológica e vigor físico (sinais honestos). Em contrapartida, a pressão de seleção natural sobre as fêmeas favorece camuflagem críptica craniocaudal para proteção da ninhada.", "possui_imagem": false},
  {"id": 179, "uid": "CIEN-7-179", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Adaptação ao Frio: Trocas Contracorrente nas Patas dos Pinguins", "dificuldade": "Difícil", "enunciado": "Pinguins imperadores caminham e permanecem em pé sobre gelo antártico a temperaturas de -40 ºC sem que suas patas congelem e sem perder o calor de seu corpo interno. A conservação biofísica de calor nessas extremidades desprovidas de penas baseia-se em um arranjo de trocas de calor por contracorrente (rete mirabile vascular) nas pernas, no qual:", "alternativas": {"A": "O sangue arterial quente que desce do coração cede calor diretamente às veias adjacentes frias que sobem das patas, resfriando o sangue que chega às extremidades e reaquecendo o sangue que volta ao núcleo corporal.", "B": "O sangue das patas é substituído por álcool etílico anticongelante puro.", "C": "As pernas não contêm vasos sanguíneos nem circulação de sangue no inverno.", "D": "A pele das patas emite radiação micro-ondas aquecida pelo fígado.", "E": "Os ossos das patas pegam fogo internamente através de reações de combustão lenta."}, "resposta_correta": "A", "justificativa": "A rede vascular de contracorrente arteriovenosa justaposta promove pré-resfriamento do fluxo arterial em direção ao pé e pré-aquecimento do fluxo venoso ascendente. A temperatura das patas mantém-se próxima de 0 ºC (reduzindo o gradiente com o gelo), mantendo o núcleo visceral protegido a 38 ºC.", "possui_imagem": false},
  {"id": 180, "uid": "CIEN-7-180", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Glândula Mamária nos Marsupiais e Leite Bifásico", "dificuldade": "Difícil", "enunciado": "Uma fêmea de canguru vermelho pode alimentar simultaneamente dois filhotes de idades completamente distintas: um filhote jovem confinado no marsúpio sugando uma teta e um filhote juvenil mais velho fora da bolsa sugando outra teta adjacente. A extraordinária sofisticação endócrina das glândulas mamárias nesse caso reside no fato de que:", "alternativas": {"A": "Uma das tetas fornece leite e a outra fornece água pura do mar.", "B": "Cada teta secreta concomitantemente leites com composições bioquímicas totalmente diferentes (uma secreta leite rico em proteínas e carboidratos para o filhote imaturo e a outra secreta leite rico em gorduras concentradas para o filhote em crescimento ativo).", "C": "O filhote mais velho come as tetas da mãe sem produzir saliva.", "D": "As glândulas mamárias trocam de lugar com o estômago da mãe a cada salto.", "E": "O leite dos marsupiais é produzido exclusivamente a partir de veneno de serpente."}, "resposta_correta": "B", "justificativa": "Glândulas mamárias adjacentes de fêmeas de marsupiais possuem receptores hormonais e transcrição diferencial assíncrona, sintetizando simultaneamente leite 'fase 1' (diluído e proteico para o neonato) e 'fase 2' (altamente calórico e lipídico para o jovem ambulante).", "possui_imagem": false},
  {"id": 181, "uid": "CIEN-7-181", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Bico dos Tentilhões de Darwin e Radiação Adaptativa", "dificuldade": "Difícil", "enunciado": "No Arquipélago de Galápagos, Charles Darwin observou diversas espécies de tentilhões que divergiam acentuadamente no tamanho, espessura e curvatura do bico córneo (alguns com bicos maciços para quebrar sementes duras, outros com bicos finos e pontiagudos para capturar insetos em fendas ou sugar néctar). Esse clássico exemplo de 'radiação adaptativa' demonstra que:", "alternativas": {"A": "Todas as aves do planeta foram criadas com o mesmo bico sem mutações genéticas.", "B": "A partir de uma espécie ancestral comum que colonizou as ilhas, populações isoladas em diferentes nichos ecológicos sofreram seleção natural divergente, adaptando a morfologia do bico à exploração eficiente de recursos alimentares distintos disponíveis.", "C": "Os tentilhões moldavam seus bicos batendo intencionalmente em pedras vulcânicas.", "D": "O bico das aves é feito de ferro maleável que amolece com a chuva ácida.", "E": "Aves com bicos grossos não possuem ossos pneumáticos nem penas de voo."}, "resposta_correta": "B", "justificativa": "A radiação adaptativa dos tentilhões de Darwin ilustra a diversificação morfológica a partir de um ancestral continental comum: variações na expressão de genes do desenvolvimento (como BMP4 para profundidade e calmodulina para comprimento do bico) foram selecionadas pelo espectro de sementes e presas de cada ilha.", "possui_imagem": false},
  {"id": 182, "uid": "CIEN-7-182", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Placenta Hemocorial vs. Epiteliocorial nos Eutérios", "dificuldade": "Difícil", "enunciado": "Na histologia comparada da reprodução dos mamíferos placentários, a placenta humana e de primatas é classificada como 'hemocorial', enquanto a de cavalos e porcos é 'epiteliocorial'. Essa diferença anatômica refere-se a:", "alternativas": {"A": "O número de meses que dura a gestação no útero da fêmea.", "B": "O número de camadas de tecido que separam o sangue materno do sangue fetal (na hemocorial, o trofoblasto fetal banha-se diretamente no sangue materno sem o endotélio materno, permitindo transporte transplacentário massivo de anticorpos IgG antes do nascimento).", "C": "O fato de a placenta humana ser feita de osso calcário e a de cavalos ser líquida.", "D": "A presença de asas embrionárias no feto de macacos durante a gestação.", "E": "O fato de os cavalos não possuírem vasos sanguíneos no cordão umbilical."}, "resposta_correta": "B", "justificativa": "A classificação de Grosser baseia-se nas camadas teciduais de separação: na barreira hemocorial (humanos, roedores) o sinciciotrofoblasto fetal está em contato direto com as lacunas de sangue materno, viabilizando a transferência ativa de anticorpos IgG; na epiteliocorial há seis camadas histológicas intactas, impedindo a passagem pré-natal de anticorpos e tornando o colostro imprescindível.", "possui_imagem": false},
  {"id": 183, "uid": "CIEN-7-183", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Músculos Peitorais Maior e Menor (Supracoracoídeo) no Voo das Aves", "dificuldade": "Difícil", "enunciado": "No voo batido das aves, o movimento de abaixar a asa (gerando impulso de sustentação e propulsão) e o movimento de levantar a asa são executados por dois grandes músculos peitorais ancorados na carena do esterno. O músculo responsável por elevar a asa atua de forma engenhosa por meio de:", "alternativas": {"A": "Um motor elétrico biológico localizado nas penas do rabo da ave.", "B": "Um tendão do músculo supracoracoídeo que passa através de uma polia óssea (o forame triósseo no ombro) e se insere na face dorsal do úmero, puxando a asa para cima como em um sistema de roldana mecânica invertida.", "C": "A força de atrito do vento soprando por baixo das patas da ave.", "D": "Contrações do estômago mecânico da moela durante o voo.", "E": "Células da glia espalhadas pela borda das asas de voo."}, "resposta_correta": "B", "justificativa": "Para manter o centro de gravidade rebaixado ventralmente no corpo, o músculo elevador da asa (supracoracoídeo) situa-se no peito sob o peitoral maior; seu tendão passa pelo canal triósseo (formado por escápula, coracoide e clavícula) e atua como cabo de roldana, erguendo o úmero dorsalmente.", "possui_imagem": false},
  {"id": 184, "uid": "CIEN-7-184", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Vibrissas (Bigodes) nos Mamíferos e Mecanorrecepção", "dificuldade": "Difícil", "enunciado": "As vibrissas (conhecidas popularmente como os bigodes de gatos, ratos, cães e focas) são pelos especializados dotados de rica inervação sensorial somática na base do folículo piloso. Esse aparato mecanorreceptor permite ao mamífero:", "alternativas": {"A": "Cheirar presas através da ponta dos pelos no escuro das tocas.", "B": "Tatear o ambiente, estimar a largura de passagens estreitas no escuro, detectar vibrações mecânicas sutis e correntezas de água, possuindo representação cortical somatossensorial massiva no cérebro (campos de barris corticais).", "C": "Produzir eletricidade para paralisar peixes na água doce.", "D": "Transpirar água mineral para resfriar a língua no calor.", "E": "Substituir os olhos quando o animal envelhece na floresta."}, "resposta_correta": "B", "justificativa": "Os folículos das vibrissas são envolvidos por um seio sanguíneo cavernoso e milhares de terminações nervosas livres e mecanorreceptores de Merkel e lamelados inervados pelo nervo trigêmeo, correspondendo a unidades modulares citoarquitetônicas colunares no córtex sensorial (os barris somatossensoriais de Woosley).", "possui_imagem": false},
  {"id": 185, "uid": "CIEN-7-185", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Ossificação e Fibras Musculares Vermelhas vs. Brancas nas Aves", "dificuldade": "Difícil", "enunciado": "Ao comer carne de galinha, nota-se que a carne do peito é esbranquiçada e seca, enquanto a carne das pernas e coxas é mais escura e avermelhada. Já em aves migratórias (como patos selvagens), a carne do peito é extremamente escura e vermelha. A causa fisiológica da coloração vermelha escura do músculo do peito dos patos é:", "alternativas": {"A": "A queima de gasolina fóssil dentro das fibras musculares do peito.", "B": "O predomínio de fibras musculares de contração lenta aeróbicas do Tipo I, densamente povoadas por mitocôndrias, capilares sanguíneos e pelo pigmento respiratório mioglobina, adaptadas a voos contínuos de milhares de quilômetros sem fadiga.", "C": "A presença de sangue venenoso estocado no peito das aves migratórias.", "D": "O fato de patos selvagens não possuírem ossos pneumáticos.", "E": "A contaminação das penas do pato por fuligem de queimadas."}, "resposta_correta": "B", "justificativa": "Fibras musculares do Tipo I (oxidativas/aeróbicas) são ricas em mioglobina carreadora de O2 e enzimas do ciclo de Krebs, sustentando contrações cíclicas prolongadas sem acidose lática. Galinhas domésticas possuem peito de fibras Tipo IIb (glicolíticas/brancas), aptas apenas a voos curtos explosivos.", "possui_imagem": false},
  {"id": 186, "uid": "CIEN-7-186", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Análise do Esqueleto do Pinguim: Nadadeiras e Perda de Voo Aéreo", "dificuldade": "Difícil", "enunciado": "Em estudos de biomecânica comparada, a evolução das asas dos pinguins demonstra uma transição esquelética radical: as articulações do cotovelo e do punho perderam a flexibilidade independente, fundindo-se em uma lâmina rígida, achatada e hidrodinâmica semelhante a uma pá. Essa modificação óssea anatômica viabilizou:", "alternativas": {"A": "O voo aéreo veloz acima das montanhas da Cordilheira dos Andes.", "B": "O chamado 'voo subaquático' (aquaflying), onde as nadadeiras atuam como hidrofólios rígidos capazes de suportar a imensa resistência e viscosidade da água (cerca de 800 vezes mais densa que o ar) sem sofrer torções ou fraturas mecânicas.", "C": "O nascimento de dentes na ponta das nadadeiras para comer caranguejos.", "D": "A respiração de água do mar pelas asas sem necessidade de pulmões.", "E": "A transformação das nadadeiras em patas de cavalo para correr na terra."}, "resposta_correta": "B", "justificativa": "A densidade e viscosidade da água geram cargas de cisalhamento centenas de vezes superiores às do ar. A fusão anquilosada e o achatamento dorsoventral dos ossos da asa dos pinguins convertem o membro anterior em um hidrofólio propulsivo sem flexões parasitas.", "possui_imagem": false},
  {"id": 187, "uid": "CIEN-7-187", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Termogênese e Pelagem em Mamíferos Polares: O Urso-Polar", "dificuldade": "Difícil", "enunciado": "O urso-polar (Ursus maritimus) vive nas geleiras do Ártico sob temperaturas de até -50 ºC e nada em águas congelantes sem perder calor. Entre as adaptações extraordinárias de seu tegumento, destaca-se o fato de que:", "alternativas": {"A": "Seus pelos são ocos e translúcidos (sem pigmento branco), dispersando a luz solar para o isolamento térmico, e a pele sob os pelos é completamente preta, absorvendo a radiação térmica solar com máxima eficiência.", "B": "Sua pele é fina e vascularizada como a dos anfíbios para absorver oxigênio do gelo.", "C": "Ele não possui pelos e tem o corpo coberto por penas de pinguim antártico.", "D": "Seu sangue corre em temperatura de fervura constante a 100 ºC.", "E": "Ele se alimenta exclusivamente de petróleo cru encontrado no mar congelado."}, "resposta_correta": "A", "justificativa": "A pelagem do urso-polar é formada por cerdas queratinizadas tubulares ocas preenchidas por ar (baixo coeficiente térmico k); a luz visível sofre espalhamento múltiplo gerando a cor branca aparente, enquanto a pele subjacente é preta melaninada para absorver a radiação e uma espessa panícula adiposa (até 11 cm de blubber) bloqueia a perda condutiva na água gelada.", "possui_imagem": false},
  {"id": 188, "uid": "CIEN-7-188", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 17: Cordados Vertebrados II: Aves e Mamíferos", "tema": "Comportamento Social e Inteligência em Primatas e Cetáceos", "dificuldade": "Difícil", "enunciado": "Primatas superiores (como chimpanzés e humanos) e cetáceos odontocetos (como golfinhos e orcas) apresentam o maior índice de encefalização (tamanho do cérebro relativo à massa corporal) de todos os animais. Esse hiperdesenvolvimento do córtex cerebral está associado à evolução de:", "alternativas": {"A": "Respiração branquial mista com pulmões de dinossauro.", "B": "Comportamentos sociais complexos, capacidade de transmissão cultural aprendida (como dialetos de caça e uso de ferramentas), reconhecimento de si mesmo no espelho e empatia intraespecífica.", "C": "Cascas de quelônio no crânio que protegem contra meteoros.", "D": "Dentes afiados que mastigam pedras no fundo do oceano.", "E": "Asas de voo que crescem na cabeça durante o sono."}, "resposta_correta": "B", "justificativa": "A hipótese do cérebro social em mamíferos sustenta que pressões de seleção decorrentes da cooperação, alianças dinâmicas, comunicação vocal complexa e transmissão vertical não genética de dialetos e táticas alimentares (cultura animal) impulsionaram a expansão do neocórtex em primatas e cetáceos.", "possui_imagem": false},
  {"id": 189, "uid": "CIEN-7-189", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Teoria da Deriva Continental: Pangeia", "dificuldade": "Fácil", "enunciado": "Em 1912, o cientista alemão Alfred Wegener propôs a Teoria da Deriva Continental. Segundo essa teoria, há cerca de 250 milhões de anos, todos os continentes atuais estavam unidos em um único supercontinente gigantesco chamado:", "alternativas": {"A": "Pantalassa.", "B": "Pangeia.", "C": "Laurásia.", "D": "Gondwana.", "E": "Eurásia."}, "resposta_correta": "B", "justificativa": "Wegener denominou o supercontinente primordial de Pangeia (do grego pan = todo; gea = terra), o qual era circundado pelo oceano universal Pantalassa.", "possui_imagem": true},
  {"id": 190, "uid": "CIEN-7-190", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Evidências Morfológicas da Deriva", "dificuldade": "Fácil", "enunciado": "Uma das primeiras observações visuais que chamaram a atenção de cientistas para a união passada dos continentes foi o notável encaixe geográfico de suas linhas de costa, semelhante às peças de um quebra-cabeça, especialmente evidente entre:", "alternativas": {"A": "A costa leste do Brasil (América do Sul) e a costa oeste da África.", "B": "A costa do Alasca e a costa da Antártica.", "C": "A Austrália e o Polo Norte.", "D": "A África do Sul e a Groenlândia.", "E": "O Japão e a Floresta Amazônica."}, "resposta_correta": "A", "justificativa": "O contorno do litoral atlântico oriental da América do Sul e o litoral atlântico ocidental africano exibem um paralelismo morfológico impressionante, evidência cartográfica primária da junção prévia dos continentes.", "possui_imagem": true},
  {"id": 191, "uid": "CIEN-7-191", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Evidências Fósseis: O Mesosaurus", "dificuldade": "Fácil", "enunciado": "Fósseis de um pequeno réptil aquático de água doce chamado Mesosaurus, datados de cerca de 280 milhões de anos, foram encontrados exclusivamente em rochas do sul do Brasil e do sul da África. Como o Mesosaurus não tinha capacidade de nadar milhares de quilômetros pelo oceano salgado, essa descoberta comprova que:", "alternativas": {"A": "O réptil foi transportado em navios de navegadores antigos.", "B": "A América do Sul e a África estiveram fisicamente unidas no passado geológico.", "C": "O Oceano Atlântico congelou completamente no verão.", "D": "O Mesosaurus voava pelo ar como as aves marinhas.", "E": "A rocha com fósseis foi jogada por um meteoro espacial."}, "resposta_correta": "B", "justificativa": "Sendo um réptil de águas rasas continentais incapaz de cruzar um oceano aberto de água salgada, a presença de fósseis idênticos na Bacia do Paraná e no Karoo africano atesta a contiguidade física pretérita dos continentes.", "possui_imagem": true},
  {"id": 192, "uid": "CIEN-7-192", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Placas Tectônicas: Litosfera", "dificuldade": "Fácil", "enunciado": "A camada sólida e rochosa mais externa da Terra, formada pela crosta e pela porção superior rígida do manto, é dividida em blocos móveis gigantescos chamados de:", "alternativas": {"A": "Núcleos internos e externos.", "B": "Placas tectônicas (ou placas litosféricas).", "C": "Câmaras magmáticas do ar.", "D": "Lençóis freáticos oceânicos.", "E": "Fossas da astenosfera."}, "resposta_correta": "B", "justificativa": "A litosfera terrestre é fragmentada em dezenas de blocos rochosos semirrígidos que se deslocam sobre a astenosfera, denominados placas tectônicas.", "possui_imagem": true},
  {"id": 193, "uid": "CIEN-7-193", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Motor do Movimento das Placas: Convecção", "dificuldade": "Fácil", "enunciado": "As placas tectônicas movem-se lentamente alguns centímetros por ano. A força motriz principal que impulsiona esse movimento contínuo da litosfera são as:", "alternativas": {"A": "Marés gravitacionais causadas pela Lua cheia.", "B": "Correntes de convecção de magma aquecido que circulam no interior do manto terrestre.", "C": "Forças dos ventos das tempestades oceânicas.", "D": "Explosões nucleares no fundo dos oceanos.", "E": "Ondas de rádio emitidas pelo Sol no espaço."}, "resposta_correta": "B", "justificativa": "O calor proveniente do núcleo e do manto profundo aquece o magma viscoso da astenosfera; o material aquecido menos denso ascende enquanto o material superficial resfriado mais denso afunda, gerando células de convecção que arrastam as placas tectônicas.", "possui_imagem": true},
  {"id": 194, "uid": "CIEN-7-194", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Limites Divergentes de Placas", "dificuldade": "Fácil", "enunciado": "Quando duas placas tectônicas se afastam uma da outra (como no meio do Oceano Atlântico), o limite entre elas é chamado de divergente. O afastamento das placas no fundo do mar provoca:", "alternativas": {"A": "A destruição total de todo o relevo dos continentes.", "B": "A subida de magma que se solidifica em contato com a água, formando nova crosta oceânica e uma cadeia de montanhas submarinas chamada dorsal meso-oceânica.", "C": "A formação instantânea de geleiras polares no equador.", "D": "O esvaziamento de toda a água dos oceanos para o centro da Terra.", "E": "A fusão da América do Sul com a Ásia."}, "resposta_correta": "B", "justificativa": "Nos limites divergentes construtivos, a separação de placas alivia a pressão sobre o manto; o magma basáltico ascende pela fenda central (rifte), solidifica-se e forma crosta oceânica jovem, erguendo a dorsal oceânica.", "possui_imagem": true},
  {"id": 195, "uid": "CIEN-7-195", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Limites Convergentes de Placas", "dificuldade": "Fácil", "enunciado": "Quando duas placas tectônicas colidem frontalmente (se chocam), o limite entre elas é classificado como convergente. Esse tipo de choque de placas costuma dar origem a:", "alternativas": {"A": "Dorsais submarinas onde o oceano se abre.", "B": "Grandes cadeias de montanhas, vulcões ativos, fossas oceânicas profundas e intensos terremotos.", "C": "Planícies calmas sem nenhuma atividade sísmica.", "D": "Buracos que sugam o ar da atmosfera para o subsolo.", "E": "Transformação de rochas em água potável pura."}, "resposta_correta": "B", "justificativa": "Limites convergentes destrutivos envolvem forças tectônicas compressivas extremas que dobram a crosta (formando orógenos e cordilheiras), forçam placas para o manto (subducção) e deflagram magmatismo e sismos frequentes.", "possui_imagem": true},
  {"id": 196, "uid": "CIEN-7-196", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "A Cordilheira dos Andes", "dificuldade": "Fácil", "enunciado": "A Cordilheira dos Andes, na América do Sul, é uma das maiores cadeias montanhosas do mundo. Ela foi e continua sendo formada pelo choque entre quais placas tectônicas?", "alternativas": {"A": "Placa Africana e Placa Antártica.", "B": "Placa de Nazca (oceânica) e Placa Sul-Americana (continental).", "C": "Placa Euroasiática e Placa Norte-Americana.", "D": "Placa de Cocos e Placa da Índia.", "E": "Placa do Pacífico e Placa do Caribe."}, "resposta_correta": "B", "justificativa": "Os Andes resultam da convergência entre a Placa oceânica de Nazca (mais densa, que mergulha sob o continente em zona de subducção) e a Placa continental Sul-Americana, provocando soerguimento crustal e vulcanismo andino.", "possui_imagem": true},
  {"id": 197, "uid": "CIEN-7-197", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "A Cordilheira do Himalaia", "dificuldade": "Fácil", "enunciado": "A Cordilheira do Himalaia, onde se localiza o Monte Everest (o pico mais alto do planeta), formou-se e continua crescendo devido à colisão frontal entre:", "alternativas": {"A": "Duas placas oceânicas no meio do Oceano Atlântico.", "B": "Duas placas continentais: a Placa Indiana e a Placa Euroasiática.", "C": "A Placa do Pacífico e a Placa de Nazca.", "D": "A Placa Africana e a Placa Sul-Americana.", "E": "Uma placa de gelo polar e o Deserto do Saara."}, "resposta_correta": "B", "justificativa": "O Himalaia é o maior exemplo de orogênese por colisão continente-continente: com densidades equivalentes e baixas, nenhuma das massas continentais submerge completamente no manto; a compressão enruga e soergue a crosta formando picos monumentais.", "possui_imagem": true},
  {"id": 198, "uid": "CIEN-7-198", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Terremotos: Foco e Epicentro", "dificuldade": "Fácil", "enunciado": "Em um terremoto (abalo sísmico), o ponto exato no interior da Terra onde as rochas se rompem e liberam energia na forma de ondas é o hipocentro (ou foco). O ponto na superfície da Terra localizado verticalmente logo acima do foco é denominado:", "alternativas": {"A": "Cratera.", "B": "Epicentro.", "C": "Magma.", "D": "Dorsal.", "E": "Fossa abissal."}, "resposta_correta": "B", "justificativa": "O epicentro é o ponto na superfície terrestre localizado exatamente na vertical acima do hipocentro (foco subterrâneo do abalo), sendo habitualmente a região onde as ondas sísmicas atingem o solo com maior violência.", "possui_imagem": true},
  {"id": 199, "uid": "CIEN-7-199", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Aparelho que Registra Terremotos", "dificuldade": "Fácil", "enunciado": "O instrumento científico utilizado pelos geofísicos para detectar, medir e registrar as vibrações das ondas sísmicas geradas por terremotos na Terra é o:", "alternativas": {"A": "Telescópio refrator.", "B": "Sismógrafo.", "C": "Barômetro de mercúrio.", "D": "Anemômetro eólico.", "E": "Termômetro de álcool."}, "resposta_correta": "B", "justificativa": "O sismógrafo registra com precisão as oscilações mecânicas da crosta terrestre produzidas por ondas sísmicas em um sismograma, permitindo determinar a magnitude, profundidade e epicentro do sismo.", "possui_imagem": true},
  {"id": 200, "uid": "CIEN-7-200", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Tsunamis (Maremotos)", "dificuldade": "Fácil", "enunciado": "Um tsunami é uma onda marinha gigante de imensa energia que se propaga pelos oceanos e pode devastar regiões costeiras. A principal causa da formação de tsunamis é:", "alternativas": {"A": "A atração gravitacional da Lua durante a maré alta.", "B": "A ocorrência de um forte abalo sísmico submarino (maremoto) com deslocamento vertical abrupto do fundo do oceano.", "C": "A passagem de navios cargueiros em alta velocidade.", "D": "A respiração de cardumes gigantes de baleias jubarte.", "E": "Ventos fracos que sopram no litoral no verão."}, "resposta_correta": "B", "justificativa": "Quando uma falha geológica submarina sofre ruptura com movimentação vertical súbita de blocos tectônicos, ela desloca abruptamente milhares de toneladas cúbicas de água marinha sobrejacente, gerando tsunamis em águas profundas.", "possui_imagem": true},
  {"id": 201, "uid": "CIEN-7-201", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Estrutura do Vulcão: Magma vs. Lava", "dificuldade": "Fácil", "enunciado": "O material rochoso fundido a altíssimas temperaturas no interior da crosta terrestre é chamado de magma. Quando esse material é expelido através da cratera de um vulcão e escorre sobre a superfície da Terra, ele passa a ser chamado de:", "alternativas": {"A": "Granito sedimentar.", "B": "Lava.", "C": "Calcário fóssil.", "D": "Quartzo líquido.", "E": "Basalto fóssil."}, "resposta_correta": "B", "justificativa": "Chama-se magma o material rochoso incandescente em fusão enquanto confinado no subsolo sob pressão com seus gases dissolvidos; ao atingir a superfície livre da atmosfera, desgaseifica-se parcialmente e é denominado lava.", "possui_imagem": true},
  {"id": 202, "uid": "CIEN-7-202", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Círculo de Fogo do Pacífico", "dificuldade": "Fácil", "enunciado": "A região do planeta que concentra cerca de 75% dos vulcões ativos do mundo e onde ocorrem cerca de 90% de todos os terremotos é conhecida como:", "alternativas": {"A": "Círculo de Gelo do Polo Norte.", "B": "Círculo de Fogo do Pacífico (Ring of Fire).", "C": "Dorsal Mesoatlântica Central.", "D": "Planície Amazônica Sul-Americana.", "E": "Fossa do Mar Mediterrâneo."}, "resposta_correta": "B", "justificativa": "O Círculo de Fogo do Pacífico (Anel de Fogo) é uma vasta ferradura de bordas de placas tectônicas convergentes e zonas de subducção que contorna o Oceano Pacífico (Japão, Indonésia, Chile, Costa Oeste dos EUA e Alasca).", "possui_imagem": true},
  {"id": 203, "uid": "CIEN-7-203", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Estabilidade Tectônica do Brasil", "dificuldade": "Fácil", "enunciado": "O território brasileiro raramente vivencia terremotos de grande magnitude e não possui vulcões ativos contemporâneos. A justificativa geológica para essa estabilidade sísmica é:", "alternativas": {"A": "O Brasil é protegido por uma carapaça de gelo subterrâneo.", "B": "O Brasil está localizado no centro estável da Placa Sul-Americana, muito distante das bordas ativas onde ocorrem os choques ou afastamentos de placas.", "C": "O solo brasileiro é feito de borracha natural elástica.", "D": "A Floresta Amazônica neutraliza a gravidade da Terra.", "E": "Os sismógrafos foram proibidos de funcionar no país."}, "resposta_correta": "B", "justificativa": "O Brasil ocupa uma posição intraplaca continental cratônica relativamente estável na porção central da Placa Tectônica Sul-Americana, distante milhares de quilômetros da zona de subducção andina a oeste e da dorsal atlântica a leste.", "possui_imagem": false},
  {"id": 204, "uid": "CIEN-7-204", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Falha de San Andreas: Limite Transformante", "dificuldade": "Fácil", "enunciado": "A famosa Falha de San Andreas, localizada no estado da Califórnia (Estados Unidos), é um limite tectônico onde a Placa do Pacífico e a Placa Norte-Americana deslizam horizontalmente uma ao lado da outra. Esse tipo de limite é classificado como:", "alternativas": {"A": "Convergente com subducção.", "B": "Transformante (ou conservativo).", "C": "Divergente com criação de oceano.", "D": "Vulcânico estático.", "E": "Glacial permanente."}, "resposta_correta": "B", "justificativa": "Limites transformantes (conservativos) caracterizam-se pelo deslizamento lateral horizontal entre duas placas tectônicas; não ocorre criação nem destruição substancial de litosfera, mas o atrito periódico gera sismos violentos.", "possui_imagem": false},
  {"id": 205, "uid": "CIEN-7-205", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Evidências Paleoclimáticas da Deriva Continental", "dificuldade": "Fácil", "enunciado": "Wegener encontrou evidências de geleiras antigas (marcas de arrasto de gelo e rochas trazidas por glaciares) de mesma época geológica no Brasil, no sul da África, na Índia e na Austrália — regiões que hoje possuem climas quentes tropicais. Esse fato comprova que:", "alternativas": {"A": "O Sol parou de queimar durante 100 milhões de anos.", "B": "No passado geológico, esses continentes estavam unidos próximos ao Polo Sul como parte do continente de Gondwana e migraram posteriormente para suas posições atuais.", "C": "O Brasil sempre esteve no Polo Norte até o século XIX.", "D": "Geleiras conseguem atravessar oceanos quentes flutuando no ar.", "E": "A Índia era uma ilha de gelo pura sem terra firme."}, "resposta_correta": "B", "justificativa": "Os depósitos de tilitos e estrias glaciais neopaleozoicas coincidentes em continentes hoje tropicais só encontram explicação lógica na aglutinação prévia dessas massas de terra na porção polar meridional da Pangeia (Gondwana).", "possui_imagem": false},
  {"id": 206, "uid": "CIEN-7-206", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "A Fossa das Marianas", "dificuldade": "Fácil", "enunciado": "O ponto mais profundo de todos os oceanos do planeta Terra é a Fossa das Marianas, com quase 11.000 metros de profundidade no Oceano Pacífico. Essa fossa submarina abissal foi formada pelo processo de:", "alternativas": {"A": "Afastamento divergente de duas placas continentais.", "B": "Subducção, onde uma placa tectônica oceânica mergulha sob outra placa tectônica oceânica em um limite convergente.", "C": "Erosão provocada por cachoeiras submarinas no fundo do mar.", "D": "Explosão de uma mina de petróleo submarina.", "E": "Impacto de uma geleira que afundou no mar."}, "resposta_correta": "B", "justificativa": "Fossas oceânicas são depressões topográficas lineares estreitas e profundíssimas originadas no ponto de inflexão de zonas de subducção, onde a borda da placa litosférica oceânica verga para mergulhar no manto astenosférico.", "possui_imagem": false},
  {"id": 207, "uid": "CIEN-7-207", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Escala Richter de Terremotos", "dificuldade": "Fácil", "enunciado": "Para quantificar a energia elástica total liberada no foco de um terremoto, utiliza-se mundialmente uma escala numérica logarítmica desenvolvida em 1935 pelo sismólogo Charles Richter, chamada:", "alternativas": {"A": "Escala Mercalli de danos visuais.", "B": "Escala Richter de magnitude.", "C": "Escala Celsius de temperatura.", "D": "Escala Beaufort de ventos.", "E": "Escala Mohs de dureza de minerais."}, "resposta_correta": "B", "justificativa": "A Escala Richter afere a magnitude sísmica com base na amplitude das ondas registradas em sismógrafos; sendo logarítmica de base 10, cada aumento de uma unidade na escala representa amplitude 10 vezes maior e cerca de 32 vezes mais energia liberada.", "possui_imagem": false},
  {"id": 208, "uid": "CIEN-7-208", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Camadas da Terra: Crosta, Manto e Núcleo", "dificuldade": "Fácil", "enunciado": "O interior do planeta Terra é estruturado em três camadas concêntricas principais com composições químicas distintas. Da superfície para o centro, a ordem correta dessas camadas é:", "alternativas": {"A": "Núcleo -> Manto -> Crosta.", "B": "Crosta terrestre -> Manto -> Núcleo.", "C": "Manto -> Crosta -> Astenosfera.", "D": "Litosfera -> Atmosfera -> Hidrosfera.", "E": "Núcleo interno -> Magma -> Crosta pura."}, "resposta_correta": "B", "justificativa": "A divisão geoquímica composicional clássica da Terra estratifica-se da periferia ao centro em: Crosta (rochosa, fina e rígida), Manto (silicatos densos de ferro e magnésio) e Núcleo (liga metálica densa de ferro e níquel - NiFe).", "possui_imagem": false},
  {"id": 209, "uid": "CIEN-7-209", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Por que Wegener foi Rejeitado em sua Época?", "dificuldade": "Médio", "enunciado": "Quando Alfred Wegener publicou seu livro defendendo a Deriva Continental em 1915, a grande maioria dos geólogos e físicos da época rejeitou veementemente suas ideias. O principal motivo científico para a rejeição da teoria de Wegener naquele período foi:", "alternativas": {"A": "Ele não saber desenhar mapas geográficos corretos.", "B": "Ele não ter conseguido explicar um mecanismo físico plausível ('o motor') capaz de mover continentes maciços de granito através da crosta oceânica sólida.", "C": "A descoberta de que a Terra era plana e estática.", "D": "O fato de os fósseis de Mesosaurus terem sido falsificados por ele.", "E": "A proibição do estudo de fósseis pelas academias europeias."}, "resposta_correta": "B", "justificativa": "Wegener propôs que os continentes navegavam como quebra-gelos sobre o leito basáltico do oceano impulsionados por forças de maré ou centrífugas, o que os geofísicos demonstraram ser mecanicamente impossível. Apenas na década de 1960 a convecção astenosférica e a tectônica de placas solucionaram a questão.", "possui_imagem": false},
  {"id": 210, "uid": "CIEN-7-210", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Mapeamento do Fundo Oceânico e a Hipótese de Hess", "dificuldade": "Médio", "enunciado": "Durante e após a Segunda Guerra Mundial, o uso militar de sonares permitiu o mapeamento topográfico detalhado do fundo dos oceanos. Em 1962, o geólogo Harry Hess propôs a 'Hipótese da Expansão do Assoalho Oceânico', demonstrando que:", "alternativas": {"A": "O fundo dos oceanos era completamente plano e plano como um deserto de areia.", "B": "A crosta oceânica está em constante renovação: magma ascende nas dorsais meso-oceânicas criando crosta nova que se afasta lateralmente, sendo mais jovem perto da dorsal e progressivamente mais antiga perto dos continentes.", "C": "O Oceano Atlântico estava diminuindo e iria fechar em cinquenta anos.", "D": "As rochas marinhas tinham a mesma idade de 4 bilhões de anos em todo o oceano.", "E": "O fundo do mar era formado inteiramente por ferro puro líquido."}, "resposta_correta": "B", "justificativa": "O paleomagnetismo e a datação radiométrica de basaltos do fundo marinho confirmaram a hipótese de Hess: rochas na crista da Dorsal Mesoatlântica são recém-formadas (idade zero) e tornam-se simétrica e progressivamente mais antigas à medida que nos afastamos da crista.", "possui_imagem": false},
  {"id": 211, "uid": "CIEN-7-211", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Paleomagnetismo e Faixas Magnéticas Simétricas", "dificuldade": "Médio", "enunciado": "Uma das provas mais irrefutáveis da expansão do fundo oceânico foi a descoberta de faixas simétricas de anomalias magnéticas paralelas à Dorsal Mesoatlântica. Essas faixas de polaridade magnética 'normal' e 'invertida' gravadas nos basaltos submarinos decorrem:", "alternativas": {"A": "Do uso de ímãs de neodímio instalados pelos navios oceanográficos.", "B": "Do alinhamento de minerais magnéticos (magnetita) com o campo magnético da Terra quando o magma basáltico se resfria, registrando as inversões periódicas do campo magnético terrestre ao longo das eras geológicas.", "C": "De cabos de eletricidade submarinos que transmitem corrente contínua.", "D": "Do atrito da água salgada do mar com o fundo arenoso.", "E": "De tempestades solares que queimam o fundo do oceano."}, "resposta_correta": "B", "justificativa": "Ao resfriar abaixo do ponto de Curie (~580 ºC), a magnetita basáltica orienta seus domínios magnéticos no sentido do campo geomagnético reinante. Como o campo da Terra inverte de polaridade a cada centenas de milhares de anos, a esteira de expansão registrou um 'código de barras' magnético simétrico em ambos os lados da dorsal.", "possui_imagem": false},
  {"id": 212, "uid": "CIEN-7-212", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Litosfera vs. Astenosfera: Reologia Mecânica", "dificuldade": "Médio", "enunciado": "Na divisão física da estrutura da Terra baseada no comportamento mecânico dos materiais, a Litosfera e a Astenosfera diferem fundamentalmente porque:", "alternativas": {"A": "A litosfera é líquida como água e a astenosfera é um bloco de ferro rígido.", "B": "A litosfera é rígida, fria e quebradiça, enquanto a astenosfera logo abaixo é quente, plástica e maleável (dúctil), comportando-se como um fluido de altíssima viscosidade em escalas geológicas de tempo.", "C": "A litosfera é formada apenas por ar gasoso e a astenosfera por gelo marinho.", "D": "Ambas são idênticas e não se movem de forma alguma.", "E": "A astenosfera fica no espaço sideral acima da atmosfera."}, "resposta_correta": "B", "justificativa": "A litosfera responde a esforços com fratura mecânica frágil (formando falhas e placas rígidas). A astenosfera, situada em temperaturas próximas do ponto de fusão parcial dos peridotitos, deforma-se plasticamente por fluência sob tensão de longo prazo, permitindo a mobilidade das placas.", "possui_imagem": false},
  {"id": 213, "uid": "CIEN-7-213", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Subducção e Destruição de Crosta", "dificuldade": "Médio", "enunciado": "Se nova crosta oceânica está sendo criada continuamente nas dorsais oceânicas pelo vulcanismo, por que o planeta Terra não está inflando ou aumentando de tamanho com o passar dos milhões de anos?", "alternativas": {"A": "Porque a Terra perde pedaços de rocha para a Lua a cada eclipse.", "B": "Porque a quantidade de crosta criada nas dorsais é balanceada por uma quantidade equivalente de crosta que é destruída e reciclada no manto nas zonas de subducção dos limites convergentes.", "C": "Porque as rochas evaporam na atmosfera sob a luz do sol quente.", "D": "Porque os oceanos estão secando e dando espaço para a nova crosta.", "E": "Porque a gravidade do núcleo esmaga os continentes até virarem poeira."}, "resposta_correta": "B", "justificativa": "O balanço de massa litosférico global é mantido em estado estacionário: enquanto placas divergem e geram nova crosta oceânica nas dorsais meso-oceânicas, placas oceânicas densas e antigas afundam no manto em zonas de subducção ao longo dos limites convergentes, sendo recicladas por fusão parcial.", "possui_imagem": false},
  {"id": 214, "uid": "CIEN-7-214", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Hotspots e Cadeias de Ilhas Vulcânicas: O Arquipélago do Havaí", "dificuldade": "Médio", "enunciado": "As ilhas do Havaí formam uma cadeia linear de vulcões no meio da Placa do Pacífico, longe de qualquer limite entre placas tectônicas. Esse vulcanismo intraplaca é causado por um 'hotspot' (ponto quente), cujo funcionamento é explicado por:", "alternativas": {"A": "A presença de um buraco negro no fundo do Oceano Pacífico.", "B": "Uma pluma térmica magmática fixa e profunda no manto que perfura a placa litosférica móvel que desliza sobre ela, criando uma sucessão de ilhas vulcânicas alinhadas segundo a direção de movimento da placa.", "C": "A colisão da Placa do Havaí com a Placa da Austrália.", "D": "O derretimento de gelo polar que queima o fundo do mar.", "E": "A queda de meteoros repetidamente no mesmo ponto do oceano."}, "resposta_correta": "B", "justificativa": "Hotspots originam-se de plumas mantélicas profundas estacionárias que perfuram a placa litosférica em movimento contínuo sobre elas. A ilha vulcânica sobre a pluma é ativa (como o vulcão Kilauea); à medida que a placa se afasta, o vulcão extingue-se e novas ilhas formam-se na esteira.", "possui_imagem": false},
  {"id": 215, "uid": "CIEN-7-215", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "A Samambaia Fóssil Glossopteris", "dificuldade": "Médio", "enunciado": "Outra evidência crucial encontrada por cientistas que sustentou a teoria de Wegener foi o fóssil da planta com folhas em forma de língua Glossopteris, presente em camadas de rochas sedimentares na América do Sul, África, Índia, Antártica e Austrália. O significado ecológico e evolutivo desse fóssil é:", "alternativas": {"A": "Essa planta só conseguia crescer no fundo de oceanos salgados profundos.", "B": "Tratava-se de uma flora de clima temperado/frio que não possuía sementes dispersas pelo vento marítimo, comprovando a conexão terrestre contínua dos continentes austrais (Gondwana).", "C": "A planta era na verdade um animal marinho predador de peixes.", "D": "A semente da Glossopteris voava pelo espaço sideral entre planetas.", "E": "A Glossopteris foi plantada por civilizações indígenas antigas."}, "resposta_correta": "B", "justificativa": "Glossopteris era uma gimnosperma de grande porte típica de climas frios de altas latitudes austrais, com sementes pesadas desprovidas de asas aerodinâmicas para dispersão oceânica. A sua distribuição circun-antártica fóssil é prova categórica da continuidade física de Gondwana.", "possui_imagem": false},
  {"id": 216, "uid": "CIEN-7-216", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Rifteamento Continental: O Vale do Rifte Africano", "dificuldade": "Médio", "enunciado": "Na África Oriental, o Grande Vale do Rifte (East African Rift) é uma imensa fenda geológica com lagos profundos e vulcões ativos (como o Kilimanjaro). Os geólogos sabem que essa região representa:", "alternativas": {"A": "O início do processo de separação de uma placa continental (rifteamento), que no futuro geológico de milhões de anos dividirá o leste africano e dará origem a um novo oceano.", "B": "A colisão violenta de dois continentes que estão fechando o Mar Vermelho.", "C": "Um impacto gigantesco de cometa que aconteceu no ano 2000.", "D": "A secagem definitiva de todos os rios do continente africano.", "E": "O congelamento do manto terrestre sob a África."}, "resposta_correta": "A", "justificativa": "O Vale do Rifte exemplifica a fase inicial de fragmentação continental divergente: a ascensão de magma astenosférico abaula e estira a crosta continental, gerando falhas normais em degraus (grábens e horsts) e vulcanismo; a evolução contínua levará à invasão marinha e gênese de uma nova bacia oceânica.", "possui_imagem": false},
  {"id": 217, "uid": "CIEN-7-217", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Sismos no Brasil: Origem Intraplaca", "dificuldade": "Médio", "enunciado": "Embora o Brasil não tenha terremotos catastróficos comparáveis aos do Chile ou do Japão, abalos sísmicos de baixa a média magnitude (entre 3 e 5 na escala Richter) ocorrem com frequência em estados como Ceará, Rio Grande do Norte, Minas Gerais e Mato Grosso. A causa desses tremores no território brasileiro é:", "alternativas": {"A": "O choque da Placa Brasileira com a Placa de São Paulo.", "B": "Acomodação de tensões tectônicas acumuladas em falhas geológicas antigas reativadas no interior da própria Placa Sul-Americana (sismos intraplaca).", "C": "A passagem de trens e caminhões pesados nas rodovias federais.", "D": "O calor do verão que dilata o asfalto das cidades.", "E": "A atividade de vulcões submarinos ativos na Baía de Guanabara."}, "resposta_correta": "B", "justificativa": "A litosfera intraplaca está sujeita a campos de tensão compressiva horizontais regionais decorrentes da expansão da Dorsal Mesoatlântica a leste e da resistência da subducção andina a oeste, descarregando energia ao longo de zonas de fraqueza e falhamentos pré-cambrianos reativados.", "possui_imagem": false},
  {"id": 218, "uid": "CIEN-7-218", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Ondas Sísmicas: Primárias (P) vs. Secundárias (S)", "dificuldade": "Médio", "enunciado": "Quando ocorre um terremoto, dois tipos principais de ondas sísmicas de corpo viajam pelo interior da Terra: as ondas P (primárias) e as ondas S (secundárias). A diferença física fundamental entre elas é:", "alternativas": {"A": "Ondas P são lentas e viajam só no ar; ondas S são velozes e viajam no vácuo.", "B": "Ondas P são longitudinais (compressão e descompressão) e propagam-se em sólidos, líquidos e gases; ondas S são transversais (cisalhamento) e só se propagam através de meios materiais sólidos.", "C": "Ondas S são as primeiras a chegar ao sismógrafo por serem elétricas.", "D": "Ondas P queimam as rochas e ondas S congelam a água subterrânea.", "E": "Não há diferença, são apenas nomes comerciais de aparelhos."}, "resposta_correta": "B", "justificativa": "Ondas P (P-waves) são ondas mecânicas compressionais mais rápidas, capazes de atravessar sólidos e fluidos. Ondas S (S-waves) propagam-se por deformação tangencial de cisalhamento perpendicular à propagação; como fluidos não suportam forças de cisalhamento estáticas, ondas S são barradas por líquidos.", "possui_imagem": false},
  {"id": 219, "uid": "CIEN-7-219", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Descoberta do Núcleo Externo Líquido da Terra", "dificuldade": "Médio", "enunciado": "A geofísica descobriu que o núcleo externo da Terra é líquido sem nunca ter perfurado o interior do planeta a mais de 12 km de profundidade. Essa fantástica dedução científica foi obtida a partir da análise de sismogramas mundiais que demonstraram:", "alternativas": {"A": "A saída de magma líquido das torneiras residenciais.", "B": "A existência de uma 'zona de sombra das ondas S' no lado oposto da Terra após grandes sismos, comprovando que as ondas sísmicas transversais (S) são incapazes de atravessar o núcleo externo por este ser fluido/líquido.", "C": "A medição da temperatura da lava com termômetros ópticos no espaço.", "D": "A atração gravitacional da Lua que puxa o núcleo para fora.", "E": "A presença de diamantes que flutuam na água dos rios."}, "resposta_correta": "B", "justificativa": "A sismologia revelou que ondas S não são registradas em estações sismológicas localizadas a mais de 103º de distância angular do epicentro (zona de sombra das ondas S). Como ondas S não se propagam em líquidos, a descontinuidade de Gutenberg a 2.890 km delimita o topo do núcleo externo metálico em estado líquido.", "possui_imagem": false},
  {"id": 220, "uid": "CIEN-7-220", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Arco Vulcânico do Pacífico e os 'Andesitos'", "dificuldade": "Médio", "enunciado": "As rochas vulcânicas expelidas pelos vulcões da Cordilheira dos Andes receberam o nome geológico de 'andesitos'. Elas possuem composição química intermediária (com cerca de 57% a 63% de sílica). O magma que origina essas rochas é formado por:", "alternativas": {"A": "Petróleo fóssil que queima espontaneamente no cume da montanha.", "B": "Fusão parcial da placa oceânica de basalto que mergulha hidratada no manto em conjunto com a assimilação de rochas graníticas da crosta continental sobrejacente.", "C": "Areia de praia derretida pela luz solar concentrada por espelhos.", "D": "Carbonato de cálcio de conchas marinhas sem nenhum silicato.", "E": "Gelo derretido dos picos nevados das montanhas andinas."}, "resposta_correta": "B", "justificativa": "Na subducção, a liberação de voláteis (água da crosta oceânica alterada) induz a fusão parcial do manto astenosférico sobrejacente; à medida que o magma basáltico ascende, ele sofre fracionamento magmático e contaminação crustal por rochas félsicas da placa sul-americana, gerando magmas andesíticos viscosos.", "possui_imagem": false},
  {"id": 221, "uid": "CIEN-7-221", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Escala Mercalli Modificada: Intensidade vs. Magnitude", "dificuldade": "Médio", "enunciado": "Em notícias de terremotos, frequentemente mencionam-se duas escalas: Richter e Mercalli. Enquanto a Escala Richter mede a magnitude (energia física pura liberada na fonte da falha), a Escala de Mercalli Modificada mede a:", "alternativas": {"A": "Profundidade da falha em quilômetros abaixo do nível do mar.", "B": "Intensidade sísmica com base nos efeitos observados, grau de destruição de construções humanas e na percepção das pessoas no local do tremor.", "C": "Velocidade do vento no epicentro durante o terremoto.", "D": "Temperatura da lava expelida pelas fendas da rua.", "E": "Quantidade de água que vazou dos encanamentos residenciais."}, "resposta_correta": "B", "justificativa": "A Escala de Intensidade Mercalli Modificada (MMI) é qualitativa e descritiva (graus I a XII em algarismos romanos), avaliando o impacto empírico do sismo em edificações e testemunhos locais, variando com a distância ao epicentro e tipo de solo.", "possui_imagem": false},
  {"id": 222, "uid": "CIEN-7-222", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Solos Vulcânicos e Fertilidade Agrícola", "dificuldade": "Médio", "enunciado": "Apesar do perigo iminente de erupções, milhões de pessoas em países como Itália (ao redor do Vesúvio e Etna), Indonésia e Equador vivem e cultivam encostas de vulcões ativos. A razão agronômica dessa ocupação histórica de encostas vulcânicas é:", "alternativas": {"A": "A lava fria transforma-se em ouro maciço que os agricultores vendem.", "B": "O intemperismo das cinzas e rochas vulcânicas gera solos excepcionalmente férteis (como os andossolos), ricos em minerais nutrientes essenciais para as plantas como potássio, fósforo, ferro, magnésio e cálcio.", "C": "A temperatura do chão cozinha os legumes embaixo da terra.", "D": "Os vulcões impedem a ocorrência de geadas no inverno.", "E": "A ausência total de insetos e pragas ao redor das crateras."}, "resposta_correta": "B", "justificativa": "Cinzas e lavas básicas sofrem rápida desagregação físico-química em climas úmidos, liberando cátions trocáveis (K+, Ca2+, Mg2+) e formando minerais de argila amorfos (alofana) com extraordinária capacidade de retenção de água e nutrientes agronômicos.", "possui_imagem": false},
  {"id": 223, "uid": "CIEN-7-223", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Erupções Efusivas vs. Explosivas", "dificuldade": "Médio", "enunciado": "O comportamento de um vulcão pode variar de erupções calmas (efusivas, como no Kilauea no Havaí) a erupções violentamente catastróficas (explosivas, como no Monte Santa Helena ou Vesúvio). O fator físico-químico preponderante que determina o grau de explosividade do magma é:", "alternativas": {"A": "A cor das rochas ao redor da cratera do vulcão.", "B": "O teor de sílica (SiO2) do magma e a quantidade de gases voláteis dissolvidos: magmas ricos em sílica são extremamente viscosos, aprisionando gases até que a pressão acumulada cause explosões piroclásticas colossais.", "C": "A proximidade do vulcão com cidades habitadas por humanos.", "D": "A quantidade de sal marinho jogado pelos pescadores no topo da cratera.", "E": "A fase em que a Lua se encontrava no dia da erupção."}, "resposta_correta": "B", "justificativa": "Magmas riolíticos/dacíticos félsicos possuem alto teor de sílica (>65%), formando cadeias de polímeros que elevam exponencialmente sua viscosidade. Gases em expansão (H2O, CO2, SO2) não conseguem escapar suavemente, fragmentando o magma em cinzas, bombas e nuvens piroclásticas avassaladoras.", "possui_imagem": false},
  {"id": 224, "uid": "CIEN-7-224", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "As 'Terras Roxas' no Brasil e o Vulcanismo Antigo", "dificuldade": "Médio", "enunciado": "No interior de São Paulo e no Paraná, os famosos e férteis solos avermelhados de 'terra roxa', que impulsionaram a cafeicultura no século XIX, têm sua origem geológica diretamente ligada a:", "alternativas": {"A": "Cinzas de vulcões ativos que entraram em erupção há dez anos atrás.", "B": "Um gigantesco vulcanismo de fissura ocorrido no período Cretáceo (derrames basálticos da Formação Serra Geral da Bacia do Paraná), cujas rochas vulcânicas (basalto e diabásio) sofreram intemperismo químico ao longo de milhões de anos.", "C": "A queima de florestas nativas pelos povos indígenas antigos.", "D": "Depósitos de argila trazidos por tempestades de poeira do Saara.", "E": "Fósseis de dinossauros que tingiram a terra de vermelho."}, "resposta_correta": "B", "justificativa": "A Bacia do Paraná vivenciou um dos maiores eventos de derrame basáltico continental da história da Terra (província magmática de Paraná-Etendeka há ~134 Ma) durante a abertura do Atlântico Sul. O intemperismo tropical do basalto originou os latossolos férteis de terra roxa (do italiano terra rossa).", "possui_imagem": false},
  {"id": 225, "uid": "CIEN-7-225", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Gêiseres e Energia Geotérmica", "dificuldade": "Médio", "enunciado": "Em países vulcanicamente ativos como a Islândia e Nova Zelândia, é comum a ocorrência de 'gêiseres' (jatos intermitentes de água quente e vapor que brotam do solo) e o aproveitamento de energia geotérmica. Esse fenômeno é explicado por:", "alternativas": {"A": "A queima de carvão mineral por mineradores subterrâneos.", "B": "Água subterrânea que se infiltra em fendas profundas, entra em contato com rochas quentes aquecidas pelo magma e entra em ebulição sob pressão, sendo expelida ou canalizada para gerar eletricidade limpa.", "C": "Tubulações de esgoto residencial com defeito nas cidades.", "D": "A passagem de correntes elétricas trazidas por raios da tempestade.", "E": "O atrito de peixes que nadam em rios subterrâneos."}, "resposta_correta": "B", "justificativa": "Campos geotérmicos situam-se sobre anomalias térmicas da crosta onde câmaras magmáticas rasas aquecem aquíferos profundos. A água superaquecida sob pressão gera jatos de vapor em gêiseres ou é turbinada em usinas geotérmicas para geração elétrica baseload e calefação urbana.", "possui_imagem": false},
  {"id": 226, "uid": "CIEN-7-226", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Movimento Atual das Placas Medido por GPS", "dificuldade": "Médio", "enunciado": "Hoje em dia, os cientistas não precisam deduzir o movimento das placas apenas por fósseis e rochas antigas: eles medem o deslocamento milimétrico em tempo real das placas litosféricas através de:", "alternativas": {"A": "Bússolas magnéticas de mão apoiadas no chão.", "B": "Estações geodésicas de alta precisão conectadas ao sistema de satélites de posicionamento global (GPS / GNSS).", "C": "Fitas métricas esticadas de um continente a outro sobre as ondas do mar.", "D": "Pêndulos de relógio de parede nas universidades.", "E": "Contagem de passos de caminhantes que viajam de navio."}, "resposta_correta": "B", "justificativa": "Redes geodésicas globais de receptores GNSS de dupla frequência fixados em pilares rochosos fundamentais monitoram vetores de deslocamento crustal com precisão milimétrica, confirmando taxas de deriva continental de 1 a 15 cm por ano exatamente coincidentes com os dados geológicos.", "possui_imagem": false},
  {"id": 227, "uid": "CIEN-7-227", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Ciclo de Wilson", "dificuldade": "Médio", "enunciado": "Na geologia histórica, o geofísico canadense Tuzo Wilson propôs que os continentes e oceanos passam por um ciclo periódico de abertura e fechamento que dura cerca de 400 a 500 milhões de anos (o Ciclo de Wilson). As etapas desse ciclo envolvem:", "alternativas": {"A": "O congelamento e a evaporação da água dos oceanos a cada década.", "B": "Rifteamento de um continente -> Formação de um oceano jovem com dorsal -> Expansão oceânica madura -> Início de subducção e fechamento do oceano -> Colisão continental com formação de supercontinente -> Novo rifteamento.", "C": "A queda contínua de meteoros nos mesmos locais geográficos da Terra.", "D": "A transformação de rochas magmáticas em ferro líquido a cada 1.000 anos.", "E": "O giro da Terra de cabeça para baixo no espaço sideral."}, "resposta_correta": "B", "justificativa": "O Ciclo de Wilson modela a evolução tectônica cíclica de supercontinentes: fragmentação cratônica inicial por rifteamento (ex: Mar Vermelho), expansão com margens passivas (ex: Atlântico), consumo por subducção (ex: Pacífico) e sutura orogenética com colisão continental (ex: Himalaia).", "possui_imagem": false},
  {"id": 228, "uid": "CIEN-7-228", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Tectônica e Clima: O Silício e o Ciclo do Carbono", "dificuldade": "Médio", "enunciado": "O soerguimento de grandes cadeias de montanhas por colisão tectônica (como o Himalaia nos últimos 40 milhões de anos) exerce profundo impacto no clima global da Terra a longo prazo porque:", "alternativas": {"A": "As montanhas altas bloqueiam a luz solar resfriando o universo inteiro.", "B": "A exposição maciça de rochas silicatadas frescas ao intemperismo químico acelerado consome enormes quantidades de gás carbônico (CO2) da atmosfera por dissolução em água de chuva e formação de bicarbonato, promovendo o resfriamento climático global da Terra.", "C": "As montanhas atraem o oxigênio para seus picos e deixam o resto do planeta sem ar.", "D": "O Himalaia emite fumaça tóxica que destrói a camada de ozônio.", "E": "Os terremotos aumentam a temperatura do oceano em 50 graus."}, "resposta_correta": "B", "justificativa": "O intemperismo químico de silicatos (meteorização de rochas continentais) reage com o ácido carbônico da chuva (CaSiO3 + 2 CO2 + H2O -> Ca2+ + 2 HCO3- + SiO2), carreado aos oceanos onde organismos formam conchas de CaCO3, atuando como o principal sumidouro geológico de carbono atmosférico de longo prazo.", "possui_imagem": false},
  {"id": 229, "uid": "CIEN-7-229", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Fossa Oceânica e Falha de Benioff-Wadati", "dificuldade": "Médio", "enunciado": "Ao mapear a profundidade dos terremotos ao longo da costa oeste da América do Sul (onde a Placa de Nazca afunda sob o continente), os sismólogos observam que os tremores são rasos perto da costa e tornam-se progressivamente mais profundos em direção ao interior do continente, atingindo até 600 km de profundidade. Essa zona inclinada de sismos é chamada de 'Zona de Wadati-Benioff' e sua existência comprova que:", "alternativas": {"A": "O interior da Terra é formado inteiramente por túneis de ferro construídos por formigas.", "B": "A placa litosférica rígida está realmente mergulhando inclinada para dentro do manto aquecido, sofrendo atrito mecânico e rupturas sísmicas enquanto desce.", "C": "A América do Sul está afundando no Oceano Atlântico a cada semana.", "D": "Os terremotos são causados pelo peso dos caminhões nas cidades do interior.", "E": "O núcleo da Terra está subindo para a superfície dos Andes."}, "resposta_correta": "B", "justificativa": "A Zona sísmica de Wadati-Benioff mapeia com precisão geométrica a trajetória da placa oceânica rígida e fria (slab) em subducção inclinada através da astenosfera; as rupturas de cisalhamento e desidratação mineral ao longo da placa em afundamento disparam sismos em profundidades crescentes.", "possui_imagem": false},
  {"id": 230, "uid": "CIEN-7-230", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Reologia do Manto e o Conceito de Isostasia", "dificuldade": "Difícil", "enunciado": "Blocos continentais de grande espessura crostal (como o Planalto do Tibete, com cerca de 70 km de crosta) possuem profundas 'raízes' rochosas mergulhadas no manto denso, enquanto a crosta oceânica fina (cerca de 7 km) projeta raízes muito menores. Esse equilíbrio hidrostático de flutuação dos blocos litosféricos sobre a astenosfera viscosa obedece ao princípio geofísico da:", "alternativas": {"A": "Lei de Hooke de elasticidade linear pura.", "B": "Isostasia (Modelos de Airy e Pratt), análoga ao princípio de Arquimedes onde blocos de madeira menos densos flutuam em água proporcionalmente à sua espessura e densidade relativa.", "C": "Precessão dos equinócios solares.", "D": "Refração de Snell na atmosfera superior.", "E": "Condução térmica unidirecional de Fourier."}, "resposta_correta": "B", "justificativa": "A isostasia descreve o equilíbrio gravitacional flutuante da litosfera sobre a astenosfera dúctil. Pelo modelo de Airy, montanhas elevadas são compensadas por espessas raízes crustais de baixa densidade mergulhadas no manto mais denso; a erosão da montanha induz soerguimento isostático rebote da raiz.", "possui_imagem": false},
  {"id": 231, "uid": "CIEN-7-231", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Forças Tectônicas Condutoras: Slab Pull vs. Ridge Push", "dificuldade": "Difícil", "enunciado": "Estudos geodinâmicos contemporâneos que modelam as forças que movem as placas tectônicas indicam que a força motriz mais poderosa de todo o sistema NÃO é o empurrão do magma na dorsal, mas sim a força denominada 'Slab Pull' (tração da placa mergulhante). O fundamento físico da força de Slab Pull reside em:", "alternativas": {"A": "A atração magnética do polo sul sobre o ferro das montanhas.", "B": "O fato de a litosfera oceânica antiga que mergulha na zona de subducção ser muito mais fria e densa que a astenosfera circundante (agravado pela transformação mineralógica de basalto em eclogito, de altíssima densidade), afundando por gravidade e puxando o restante da placa atrás de si como uma toalha pesada escorregando de uma mesa.", "C": "O calor dos vulcões que sopra vento sob a placa tectônica.", "D": "A rotação da Terra que joga as placas para fora do planeta pela força centrífuga.", "E": "A evaporação da água do mar que cria vácuo nas fossas submarinas."}, "resposta_correta": "B", "justificativa": "A força de tração da placa mergulhante (slab pull) decorre da instabilidade gravitacional negativa: a litosfera oceânica envelhecida termicamente (>60 Ma) é mais densa que o manto circundante. Sob altas pressões na subducção, o basalto e gabro metamorfizam-se em eclogito ultra-denso, tracionando toda a placa litosférica conectada.", "possui_imagem": false},
  {"id": 232, "uid": "CIEN-7-232", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Anomalia Magnética e Taxa de Expansão Oceânica", "dificuldade": "Difícil", "enunciado": "Se uma faixa de anomalia magnética de basalto correspondente a uma reversão de polaridade ocorrida há 10 milhões de anos for identificada a 200 quilômetros de distância do eixo central de uma dorsal meso-oceânica, qual é a taxa MÉDIA anual de expansão para cada lado dessa dorsal?", "alternativas": {"A": "2 milímetros por ano.", "B": "2 centímetros por ano (20 km a cada milhão de anos).", "C": "20 metros por ano.", "D": "200 quilômetros por ano.", "E": "0,2 centímetro a cada século."}, "resposta_correta": "B", "justificativa": "Cálculo da velocidade de espalhamento unilateral: v = distância / tempo = 200 km / 10.000.000 anos = 200.000 m / 10.000.000 anos = 0,02 metro por ano = 2 cm/ano (taxa média típica de expansão da Dorsal Mesoatlântica).", "possui_imagem": false},
  {"id": 233, "uid": "CIEN-7-233", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Falhas Transformantes vs. Falhas Transcorrentes Puras", "dificuldade": "Difícil", "enunciado": "Em 1965, J. Tuzo Wilson revolucionou a geologia estrutural ao demonstrar a diferença geométrica entre uma 'falha transformante' e uma falha transcorrente simples clássica. No segmento ativo de uma falha transformante que conecta dois eixos defasados de uma dorsal meso-oceânica, o sentido relativo do movimento entre os blocos de rocha é:", "alternativas": {"A": "Exatamente igual ao sentido de afastamento dos continentes em ambos os lados.", "B": "Oposto ao sentido que a separação dos eixos da dorsal sugeriria em um mapa estático, ocorrendo movimento relativo e sismicidade ativa estritamente no segmento de falha delimitado entre os dois eixos de dorsal.", "C": "Completamente vertical sem nenhum deslocamento horizontal.", "D": "Nulo, pois o fundo do mar não sofre atrito entre dorsais.", "E": "Espiralado girando em torno de um redemoinho aquático."}, "resposta_correta": "B", "justificativa": "Nas falhas transformantes que segmentam cristas de dorsais, os blocos de crosta entre as duas cristas deslocam-se em sentidos opostos devido à expansão divergente em direções contrárias proveniente de cada eixo; além dos eixos da dorsal (zonas de fratura), as placas viajam na mesma direção e não há atrito sísmico relativo.", "possui_imagem": false},
  {"id": 234, "uid": "CIEN-7-234", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Transição de Fases Minerais no Manto e Sismos Profundos", "dificuldade": "Difícil", "enunciado": "Embora em profundidades superiores a 100 km a temperatura e a pressão tornem as rochas plásticas (o que impediria fraturas frágeis ordinárias), sismólogos registram terremotos profundos ocasionais na Zona de Wadati-Benioff entre 400 e 670 km de profundidade. A explicação mineralógica para a ocorrência desses sismos no manto profundo baseia-se em:", "alternativas": {"A": "Bactérias subterrâneas que explodem sob calor intenso.", "B": "Transformações polimórficas de fase metastáveis induzidas por alta pressão na placa subductada (como a transição da olivina para espinélio e ringwoodita/wadsleyita), gerando fraturamento por cisalhamento por transformação de fase e desidratação catastrófica de serpentinas.", "C": "A entrada de água líquida da chuva que desce até o núcleo externo.", "D": "Fricção de ossos de dinossauros soterrados no manto da Terra.", "E": "Campos magnéticos que quebram o ferro puro do manto em pedaços."}, "resposta_correta": "B", "justificativa": "Em placas frias que descem rapidamente, o núcleo da placa permanece termicamente retardado; a olivina persiste em estado metaestável até sofrer colapso de volume súbito ao transicionar para a fase de espinélio (wadsleyita/ringwoodita) e a desidratação de minerais hidratados gera frouxidão e sismicidade por cisalhamento transformacional.", "possui_imagem": false},
  {"id": 235, "uid": "CIEN-7-235", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Metamorfismo Regional e Orogênese", "dificuldade": "Difícil", "enunciado": "Durante a colisão continental e orogênese (formação de montanhas), rochas sedimentares e ígneas pré-existentes são submetidas a pressões tectônicas direcionais colossais e temperaturas de 300 ºC a 700 ºC sem se fundirem completamente, transformando-se em rochas metamórficas foliadas. A sequência progressiva de metamorfismo regional a partir de um folhelho argiloso inicial é:", "alternativas": {"A": "Ardósia -> Filito -> Xisto -> Gnaisse (com migmatito na fusão incipiente).", "B": "Granito -> Basalto -> Calcário -> Mármore.", "C": "Areia -> Arenito -> Petróleo -> Diamante.", "D": "Carvão -> Ferro -> Chumbo -> Ouro.", "E": "Basalto -> Gabro -> Riolito -> Lava."}, "resposta_correta": "A", "justificativa": "O metamorfismo baroviano regional de sedimentos pelíticos (folhelho) reflete aumento contínuo de grau térmico e pressórico: o folhelho compacta-se em ardósia (clivagem ardosiana), evolui para filito (brilho sedoso de sericita), xisto (foliação xistosa macroscópica de micas) e culmina em gnaisse (bandamento composicional quartzo-feldspático).", "possui_imagem": false},
  {"id": 236, "uid": "CIEN-7-236", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Astenosfera e Fusão por Descompressão Adiapática", "dificuldade": "Difícil", "enunciado": "Sob as dorsais meso-oceânicas e os rifting continentais, o manto astenosférico peridotítico sólido sofre fusão parcial gerando o magma basáltico que forma a nova crosta. O mecanismo termodinâmico responsável por essa fusão NÃO é o aquecimento da rocha, mas sim a:", "alternativas": {"A": "Adição massiva de água da chuva que gela o manto.", "B": "Fusão por descompressão adiabática, onde o material astenosférico ascende tão rapidamente que quase não perde calor para as vizinhanças, cruzando a curva do solidus de fusão simplesmente devido à redução da pressão litosférica confinante.", "C": "Combustão de carvão fóssil localizado nas dorsais submarinas.", "D": "Pressão do peso da água do oceano que esmaga os minerais.", "E": "Interferência da gravidade da Lua que puxa o calor para cima."}, "resposta_correta": "B", "justificativa": "O peridotito astenosférico quente ascende passivamente na fenda divergente. Em movimento convectivo ascendente rápido (adiabático), a temperatura decresce ligeiramente por expansão, mas a pressão decresce muito mais velozmente; a descompressão cruza o solidus do manto seco, gerando fusão parcial de 10% a 25% de magma basáltico.", "possui_imagem": false},
  {"id": 237, "uid": "CIEN-7-237", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Fusão por Fluxo (Flux Melting) em Zonas de Subducção", "dificuldade": "Difícil", "enunciado": "Diferente das dorsais onde o magma funde por descompressão, nas zonas de subducção o magma que alimenta o vulcanismo dos arcos de ilhas e cordilheiras (como no Círculo de Fogo) é produzido pelo mecanismo de 'fusão por fluxo' (flux melting). Esse processo ocorre porque:", "alternativas": {"A": "A placa continental quebra o magma em pequenos pedaços com suas raízes.", "B": "A placa oceânica que afunda desidrata sob alta pressão, liberando fluidos aquosos ricos em voláteis (H2O e CO2) para o cunho do manto peridotítico sobrejacente, o que reduz drasticamente a temperatura de fusão do manto (abaixa o ponto de solidus), induzindo a fusão parcial.", "C": "O atrito físico mecânico entre as placas gera calor suficiente para fundir a Terra inteira.", "D": "O oxigênio da atmosfera penetra pela fossa abissal e queima as rochas.", "E": "A água do mar ferve na superfície e desce como vapor elétrico."}, "resposta_correta": "B", "justificativa": "A quebra metamórfica de minerais hidratados na placa oceânica descendente (clorita, anfibólios) expele fluidos supercríticos aquosos para a cunha mantélica astenosférica sobrejacente. A água atua como fundente, quebrando pontes de Si-O e diminuindo o ponto de fusão do manto peridotítico em centenas de graus Celsius.", "possui_imagem": false},
  {"id": 238, "uid": "CIEN-7-238", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Terremoto de Lisboa de 1755 e a História da Ciência", "dificuldade": "Difícil", "enunciado": "Em 1º de novembro de 1755, um cataclismo sísmico de magnitude estimada em cerca de 8,5 a 9,0 atingiu Lisboa, acompanhado por um grande tsunami e incêndios generalizados que destruíram a capital portuguesa. Do ponto de vista da história da ciência, o Terremoto de Lisboa é considerado o marco inaugural da:", "alternativas": {"A": "Química orgânica de combustíveis fósseis.", "B": "Sismologia científica moderna, impulsionada pelo Marquês de Pombal, que conduziu o primeiro inquérito empírico sistemático com questionários distribuídos por todas as paróquias para mapear os danos, tempo de abalo e direção dos tremores, rompendo com explicações puramente teológicas.", "C": "Meteorologia por satélites de previsão de furacões.", "D": "Engenharia espacial de foguetes a vapor.", "E": "Criação dos primeiros motores a combustão interna da Europa."}, "resposta_correta": "B", "justificativa": "O Terremoto de Lisboa de 1755 instigou debates filosóficos (como o Poema sobre o Desastre de Lisboa de Voltaire e tratados de Kant) e levou o Marquês de Pombal a encomendar um inquérito investigativo estruturado nacional, marco da transição da interpretação punitiva religiosa para o estudo mecanicista racional dos sismos.", "possui_imagem": false},
  {"id": 239, "uid": "CIEN-7-239", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Bacia Sedimentar do Paraná e Armazenamento de Aquíferos", "dificuldade": "Difícil", "enunciado": "Na geologia estrutural do continente sul-americano, a Bacia Sedimentar do Paraná é uma imensa sinéclise intracratônica que acumulou quilômetros de rochas sedimentares e vulcânicas entre o Paleozoico e o Mesozoico. Sob os espessos derrames basálticos de terra roxa encontra-se a Formação Botucatu, um antigo paleodeserto de dunas de areia de quartzo de grande porosidade que hoje abriga:", "alternativas": {"A": "As maiores jazidas de urânio enriquecido do hemisfério sul.", "B": "O Sistema Aquífero Guarani, uma das maiores reservas transfronteiriças de água doce subterrânea do planeta.", "C": "Câmaras de magma basáltico líquido ativo que aquecem a cidade de Curitiba.", "D": "Poços gigantescos de petróleo fóssil de alta octanagem de superfície.", "E": "Florestas subterrâneas fósseis com dinossauros vivos."}, "resposta_correta": "B", "justificativa": "Os arenitos eólicos de alta porosidade e permeabilidade da Formação Botucatu (e Piramboia), confinados superiormente pela espessa capa impermeável de basaltos da Formação Serra Geral, constituem a gigantesca estrutura hidrogeológica do Sistema Aquífero Guarani.", "possui_imagem": false},
  {"id": 240, "uid": "CIEN-7-240", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Refração e Descontinuidade de Moho (Mohorovičić)", "dificuldade": "Difícil", "enunciado": "Em 1909, o sismólogo croata Andrija Mohorovičić observou que as ondas sísmicas geradas por um terremoto chegavam a sismógrafos distantes mais rápido do que a sismógrafos próximos, deduzindo que as ondas haviam sofrido refração e acelerado em uma camada mais densa em profundidade. Essa fronteira que separa a crosta terrestre do manto superior é a:", "alternativas": {"A": "Descontinuidade de Gutenberg a 2.900 km.", "B": "Descontinuidade de Lehmann a 5.150 km.", "C": "Descontinuidade de Mohorovičić (ou Moho), situada a profundidades que variam de cerca de 5 a 10 km sob oceanos e 30 a 70 km sob continentes.", "D": "Superfície do mar na maré baixa.", "E": "Fronteira da estratosfera com a troposfera."}, "resposta_correta": "C", "justificativa": "A descontinuidade de Moho marca o salto composicional abrupto da crosta (rochas félsicas a máficas com velocidade Vp ~6,0 a 6,8 km/s) para o manto peridotítico ultrabásico (Vp ~8,0 a 8,2 km/s), refratando criticamente ondas sísmicas de acordo com a Lei de Snell.", "possui_imagem": false},
  {"id": 241, "uid": "CIEN-7-241", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Fenômeno da Liquefação do Solo em Terremotos", "dificuldade": "Difícil", "enunciado": "Durante sismos severos em áreas urbanas costeiras ou fundadas sobre solos arenosos saturados de água (como aterros de portos ou leitos aluviais fluviais), edifícios de concreto armado frequentemente afundam ou tombam intactos sem sofrer colapso estrutural prévio. Esse fenômeno geotécnico é a 'liquefação do solo', que ocorre porque:", "alternativas": {"A": "O chão abre fendas que sugam os prédios para o centro da Terra.", "B": "A passagem contínua das ondas sísmicas aumenta dramaticamente a pressão da água nos poros da areia (poropressão), anulando a tensão efetiva entre os grãos de areia e fazendo o solo perder completamente sua resistência ao cisalhamento, comportando-se temporariamente como um líquido espesso.", "C": "A lava vulcânica sobe pela areia e derrete as fundações dos prédios.", "D": "A gravidade da Terra inverte seu sentido na praia durante o terremoto.", "E": "O concreto dos edifícios se transforma em pó químico solúvel."}, "resposta_correta": "B", "justificativa": "A ciclagem de cisalhamento das ondas sísmicas induz a tendência de adensamento em sedimentos arenosos saturados não consolidados. Como a água não tem tempo de drenar, a poropressão sobe até igualar a tensão confinante total; a tensão efetiva zera (σ' = 0), a resistência cisalhante desaparece e o substrato liquefaz-se instantaneamente.", "possui_imagem": false},
  {"id": 242, "uid": "CIEN-7-242", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Ondas Sísmicas de Superfície: Rayleigh e Love", "dificuldade": "Difícil", "enunciado": "Enquanto as ondas de corpo (P e S) viajam pelo interior da Terra, as ondas sísmicas superficiais (ondas de Rayleigh e ondas de Love) viajam estritamente pela superfície livre da crosta. Embora viajem mais lentamente que as ondas de corpo, as ondas de superfície são as maiores responsáveis pela destruição catastrófica de edifícios em terremotos rasos porque:", "alternativas": {"A": "Elas queimam as paredes dos prédios com faíscas elétricas.", "B": "Apresentam amplitudes muito maiores e decaem mais lentamente com a distância (dispersão bidimensional 1/sqrt(r) em vez de tridimensional 1/r^2), produzindo movimentos combinados de rolamento elíptico vertical (Rayleigh) e cisalhamento horizontal severo (Love).", "C": "Elas viajam na velocidade da luz congelando o solo das cidades.", "D": "Elas transformam as vigas de aço em plástico maleável.", "E": "Elas só ocorrem durante a noite quando as pessoas estão dormindo."}, "resposta_correta": "B", "justificativa": "Ondas de Love induzem cisalhamento horizontal destrutivo nas fundações e ondas de Rayleigh geram movimento de onda elíptica retrógrada no plano vertical. Por estarem confinadas à superfície, sua energia geométrica dissipa-se proporcionalmente a 1/r (em vez de 1/r^2), retendo alta amplitude destrutiva a grandes distâncias.", "possui_imagem": false},
  {"id": 243, "uid": "CIEN-7-243", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Supercontinente Gondwana e a Formação da Laurásia", "dificuldade": "Difícil", "enunciado": "Quando a Pangeia iniciou sua fragmentação há cerca de 200 milhões de anos (no início do período Jurássico), ela dividiu-se inicialmente em duas imensas massas continentais separadas pelo antigo Mar de Tétis. A massa continental do norte e a massa continental do sul eram compostas, respectivamente, por:", "alternativas": {"A": "Laurásia (América do Norte, Europa e Ásia exceto Índia) e Gondwana (América do Sul, África, Índia, Antártica e Austrália).", "B": "Pantalassa e Gondwana.", "C": "Groenlândia e Patagônia pura.", "D": "Brasil e Saara oceânico.", "E": "Ásia e Antártica apenas."}, "resposta_correta": "A", "justificativa": "O rifteamento primário da Pangeia ao longo da linha equatorial gerou a Laurásia ao norte (América do Norte e Eurásia continental) e Gondwana ao sul (América do Sul, África, Madagascar, Península Indiana, Austrália e Antártica), com o Mar de Tétis interposto.", "possui_imagem": false},
  {"id": 244, "uid": "CIEN-7-244", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Geometria Fractal das Falhas e Lei de Gutenberg-Richter", "dificuldade": "Difícil", "enunciado": "Na sismologia estatística, a frequência com que terremotos ocorrem em uma região geológica segue a clássica 'Lei de Gutenberg-Richter': log N = a - b.M, onde N é o número de sismos com magnitude maior ou igual a M. Em termos práticos de probabilidade e dinâmica não linear, essa relação matemática significa que:", "alternativas": {"A": "Para cada terremoto de grande magnitude (como M = 7), ocorrem na mesma região cerca de dez vezes mais terremotos de magnitude intermediária (M = 6) e centenas de microtremores menores (M = 5 ou 4).", "B": "Terremotos grandes acontecem rigorosamente a cada 10 dias em qualquer país.", "C": "A cada dez anos todos os terremotos do mundo param de acontecer.", "D": "Terremotos pequenos liberam mais energia do que terremotos gigantes.", "E": "A escala de Richter não pode ser usada para medir sismos com números decimais."}, "resposta_correta": "A", "justificativa": "Com valor típico do expoente de escala b próximo de 1,0, a Lei de Gutenberg-Richter expressa a distribuição de potência auto-similar (fractal) da liberação de estresse tectônico: a cada decréscimo de uma unidade na magnitude (M - 1), a frequência de ocorrência do evento aumenta aproximadamente por um fator de 10.", "possui_imagem": false},
  {"id": 245, "uid": "CIEN-7-245", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Balanço Térmico da Terra: Calor Primordial e Decaimento Radioativo", "dificuldade": "Difícil", "enunciado": "O fluxo geotérmico contínuo que alimenta as correntes de convecção do manto e sustenta a tectônica de placas há mais de 4 bilhões de anos provém de duas fontes energéticas internas principais no interior da Terra, que são:", "alternativas": {"A": "Luz solar absorvida pelas raízes das árvores e fricção do vento.", "B": "O calor primordial remanescente da época da acreção planetária e diferenciação do núcleo da Terra, somado ao calor radiogênico contínuo liberado pelo decaimento de isótopos radioativos de longa meia-vida presentes nas rochas do manto e da crosta (como Urânio-238, Urânio-235, Tório-232 e Potássio-40).", "C": "A queima de carvão mineral sob a crosta provocada por faíscas vulcânicas.", "D": "Reações químicas de fermentação de bactérias anaeróbias no centro do manto.", "E": "O magnetismo da Lua que puxa o ferro do núcleo para a crosta."}, "resposta_correta": "B", "justificativa": "A geodinâmica interna da máquina térmica terrestre é sustentada em aproximadamente 50% pelo calor primordial residual de impactos cometários/acreção e diferenciação gravitacional do núcleo há 4,5 Ga, e os outros 50% pelo decaimento radioativo contínuo de actinídeos e do 40K no silicato mantélico e crosta.", "possui_imagem": false},
  {"id": 246, "uid": "CIEN-7-246", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "O Terremoto de Sumatra de 2004 e a Deformação do Eixo da Terra", "dificuldade": "Difícil", "enunciado": "Em 26 de dezembro de 2004, um megaterremoto de magnitude 9,1 na zona de subducção da Fossa de Sunda em Sumatra (Indonésia) gerou o mais letal tsunami dos tempos modernos e liberou tamanha quantidade de energia elástica que a distribuição de massa da Terra foi ligeiramente alterada. Modelos geodésicos da NASA comprovaram que esse evento sísmico colossal:", "alternativas": {"A": "Parou a rotação da Terra por três semanas completas.", "B": "Deslocou o eixo de rotação médio da Terra em alguns centímetros e acelerou sutilmente a rotação do planeta (pela conservação do momento angular devido ao rebaixamento de massa na subducção), encurtando a duração do dia em frações de microssegundos.", "C": "Fez a Lua colidir com a atmosfera dos oceanos asiáticos.", "D": "Eliminou o campo magnético da Terra na região do equador.", "E": "Transformou a crosta continental da Ásia em basalto líquido permanente."}, "resposta_correta": "B", "justificativa": "Por efeito do teorema do momento angular (análogo a uma patinadora que recolhe os braços para girar mais rápido), o afundamento cosísmico de massas litosféricas densas na fossa de subducção diminuiu ligeiramente o momento de inércia da Terra, acelerando a rotação em ~2,68 microssegundos e deslocando o polo médio de figura em ~2,5 cm.", "possui_imagem": false},
  {"id": 247, "uid": "CIEN-7-247", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Efeito das Cinzas Vulcânicas no Clima: O Ano Sem Verão (1816)", "dificuldade": "Difícil", "enunciado": "A gigantesca erupção do vulcão Monte Tambora na Indonésia em 1815 ejetou mais de 100 quilômetros cúbicos de piroclastos e milhões de toneladas de gases na estratosfera. No ano seguinte (1816), o Hemisfério Norte vivenciou o famoso 'Ano Sem Verão', com geadas em pleno mês de julho na Europa e América do Norte. O mecanismo físico-químico causador desse resfriamento climático global foi:", "alternativas": {"A": "As cinzas e o dióxido de enxofre (SO2) injetados na estratosfera reagiram com o vapor de água formando uma névoa densa e persistente de aerossóis de sulfato que refletiram parte da radiação solar de volta para o espaço (aumento do albedo planetário), resfriando a superfície da Terra.", "B": "O vulcão que sugou todo o oxigênio do planeta diminuindo a temperatura para zero.", "C": "A quebra da órbita da Terra, que se afastou 100 milhões de quilômetros do Sol.", "D": "O congelamento do magma do manto que parou de aquecer o chão europeu.", "E": "A queda da Lua sobre o vulcão durante a erupção."}, "resposta_correta": "A", "justificativa": "Plumas plinianas ejetam SO2 acima da tropopausa (estratosfera), onde a ausência de chuva impede a lavagem rápida de partículas. O SO2 converte-se em gotículas de aerossóis de ácido sulfúrico (H2SO4) com tempo de residência de 1 a 3 anos, dispersando a radiação solar incidente por retroespalhamento óptico (forçante radiativa negativa acentuada).", "possui_imagem": false},
  {"id": 248, "uid": "CIEN-7-248", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Metamorfismo de Fácies de Alta Pressão e Baixa Temperatura: Xistos Azuis", "dificuldade": "Difícil", "enunciado": "Em zonas de subducção ativas, rochas basálticas do fundo oceânico afundam com a placa oceânica fria a grandes profundidades antes que tenham tempo de se aquecer termicamente. O resultado dessa condição geodinâmica ímpar de 'alta pressão e baixa temperatura' (HP-LT) é a formação de rochas metamórficas diagnósticas de fácies:", "alternativas": {"A": "Granito de alta temperatura sem pressão tectônica.", "B": "Xistos Azuis (com minerais diagnósticos como o anfibólio azul glaucofana e a lawsonita), que atuam na geologia como marcadores incontestáveis de antigas zonas de subducção de placas.", "C": "Calcário fóssil intemperizado por água doce de lagoas.", "D": "Arenito eólico desértico de dunas puras.", "E": "Basalto vesícular efusivo comum de superfície."}, "resposta_correta": "B", "justificativa": "O metamorfismo da fácies xisto azul requer gradientes geotérmicos extraordinariamente deprimidos (<10 ºC/km), encontrados exclusivamente em zonas de subducção ativas onde a rápida descida de litosfera oceânica fria impõe pressões tectônicas gigantescas antes da condução térmica de calor do manto vizinho, estabilizando glaucofana e lawsonita.", "possui_imagem": false},
  {"id": 249, "uid": "CIEN-7-249", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "Obducção e Ofiolitos: Pedaços de Manto na Terra Firme", "dificuldade": "Difícil", "enunciado": "Em raras situações tectônicas de colisões continentais, fragmentos intactos de crosta oceânica e manto superior peridotítico não sofrem subducção, mas são empurrados e cavalgados sobre a borda da crosta continental (fenômeno da obducção). Esses conjuntos de rochas oceânicas preservados sobre os continentes são conhecidos como:", "alternativas": {"A": "Complexos Ofiolíticos (ou ofiolitos), que fornecem aos geólogos a oportunidade única de estudar a composição estratigráfica da crosta e do manto oceânicos diretamente na superfície terrestre sem perfuração.", "B": "Dunas de areia fóssil de praia litorânea.", "C": "Depósitos de carvão mineral de pântano antigo.", "D": "Crateras de impacto de meteoros ricos em ferro puro.", "E": "Geleiras continentais de alta altitude."}, "resposta_correta": "A", "justificativa": "Os ofiolitos (como o célebre Complexo Ofiolítico de Samail em Omã) representam seções completas de litosfera oceânica (peridotitos mantélicos serpentinizados, gabros acamados, diques em lâmina de diabásio, basaltos em almofada e sedimentos pelágicos radiolaríticos) guilhotinadas e obductadas sobre margens continentais.", "possui_imagem": false},
  {"id": 250, "uid": "CIEN-7-250", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "7º Ano", "ano": "7º Ano", "modulo": "Módulo 18: A Dinâmica da Terra e a Tectônica de Placas", "tema": "A Superpluma do Cretáceo e o Efeito Estufa Hothouse", "dificuldade": "Difícil", "enunciado": "Durante o período Cretáceo Médio (há cerca de 100 a 90 milhões de anos), a Terra viveu um período de superaquecimento climático global extremo ('Cretaceous Hothouse'), sem nenhuma geleira nos polos e com florestas tropicais e dinossauros habitando a Antártica. A causa geodinâmica primária desse calor planetário contínuo foi:", "alternativas": {"A": "A queima de gasolina em veículos automotores da época dos dinossauros.", "B": "Uma fase de intensa atividade de superplumas mantélicas e aceleração massiva da expansão dos fundos oceânicos em todo o planeta, que gerou vulcanismo submarino e subaéreo colossal, descarregando teores monumentais de CO2 na atmosfera e elevando o nível dos oceanos em centenas de metros por intumescimento das dorsais meso-oceânicas.", "C": "O congelamento do núcleo externo que parou o campo magnético.", "D": "A colisão da Terra com três cometas de gelo quente consecutivos.", "E": "O desaparecimento total de todos os vegetais verdes do planeta."}, "resposta_correta": "B", "justificativa": "Eventos de superplumas no Cretáceo impulsionaram altíssimas taxas de produção crustal oceânica nas dorsais meso-oceânicas globais e platôs basálticos oceânicos (como Ontong-Java), com desgasificação massiva de CO2 vulcânico (atingindo mais de 1.000 a 2.000 ppm na atmosfera) e subsidência marinha reduzida, configurando o paradigma do super-efeito estufa geológico cretáceo.", "possui_imagem": false}
];
